
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `report_category`;
CREATE TABLE `report_category`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '名称',
  `html_content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'html模板内容',
  `config` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '公用配置项',
  `build_in` int(11) NOT NULL DEFAULT 0 COMMENT '是否内置 0-否 1-是 默认 0',
  `ctime` datetime(0) NOT NULL COMMENT '创建时间',
  `uid` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `utime` datetime(0) NOT NULL COMMENT '修改时间',
  `remark` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '描述',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of report_category
-- ----------------------------

INSERT INTO `report_category` VALUES (1, 'IDC租用方报告', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<#setting number_format=\"0.####\"/>\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <title>IDC${Tenant}服务质量监测报告</title>\r\n  <script src=\"http://${uiStaticUrl}/assets/echarts.min.js\"></script>\r\n  <style>${reportStyleCommon}</style>\r\n</head>\r\n<body>\r\n<div class=\"header1\">IDC${Tenant}服务质量监测报告<span class=\"header1__time\" id=\"currentRange0\"></span></div>\r\n<div class=\"table__footer\">\r\n    <div class=\"footer__label\">* 流量接入情况说明：</div>IDC链路共计22条，总带宽1.21Tbps（11*100Gbps、11*10Gbps）；系统实际接入链路15条，接入带宽1.14Tbps（11*100Gbps、4*10Gbps）。实际接入带宽为总带宽的94.21%。\r\n</div>\r\n<div class=\"header2\">一.整体流量概况</div>\r\n<div class=\"header3\">1.流量规模概况</div>\r\n<div class=\"table-box indent-3\">\r\n  <div class=\"table__title\">表1 IDC${Tenant}整体流量概况</div>\r\n  <table class=\"table\">\r\n    <thead class=\"table__header\">\r\n    <tr class=\"table__tr\">\r\n      <th class=\"table__th\">速率均值</th>\r\n      <th class=\"table__th\">速率谷值</th>\r\n      <th class=\"table__th\">速率分位值</th>\r\n      <th class=\"table__th\">速率峰值</th>\r\n      <th class=\"table__th\">速率均值环比</th>\r\n      <th class=\"table__th\">总流量</th>\r\n      <th class=\"table__th\">总流量占比</th>\r\n      <th class=\"table__th\">总流量环比</th>\r\n    </tr>\r\n    </thead>\r\n    <tbody><tr class=\"table__tr\">\r\n      <td class=\"table__td\">\r\n        ${convertNumber(getFromArr(xxxServiceRate,0,\'rate_avg\',\'number\'),\'bps\',1000)}\r\n      </td>\r\n      <td class=\"table__td\">\r\n        ${convertNumber(getFromArr(xxxServiceRate,0,\'rate_min\',\'number\'),\'bps\',1000)}\r\n      </td>\r\n      <td class=\"table__td\">\r\n        <div class=\"td__quantile-group\">\r\n          <div class=\"td__quantile\">\r\n            <div class=\"quantile__label\">\r\n              <div class=\"label-box\">\r\n                <div><span class=\"quantile__point quantile__point--p50\"></span>P50</div>\r\n              </div>\r\n            </div>\r\n            <div class=\"quantile__value\">\r\n              ${convertNumber(getFromArr(xxxServiceRate,0,\'rate50\',\'number\'),\'bps\',1000)}\r\n            </div>\r\n          </div>\r\n          <div class=\"td__quantile\">\r\n            <div class=\"quantile__label\">\r\n              <div class=\"label-box\">\r\n                <div><span class=\"quantile__point quantile__point--p90\"></span>P90</div>\r\n              </div>\r\n            </div>\r\n            <div class=\"quantile__value\">\r\n              ${convertNumber(getFromArr(xxxServiceRate,0,\'rate90\',\'number\'),\'bps\',1000)}\r\n            </div>\r\n          </div>\r\n          <div class=\"td__quantile\">\r\n            <div class=\"quantile__label\">\r\n              <div class=\"label-box\">\r\n                <div><span class=\"quantile__point quantile__point--p99\"></span>P99</div>\r\n              </div>\r\n            </div>\r\n            <div class=\"quantile__value\">\r\n              ${convertNumber(getFromArr(xxxServiceRate,0,\'rate99\',\'number\'),\'bps\',1000)}\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </td>\r\n      <td class=\"table__td\">\r\n        ${convertNumber(getFromArr(xxxServiceRate,0,\'rate_max\',\'number\'),\'bps\',1000)}\r\n      </td>\r\n      <td class=\"table__td\">\r\n        <div class=\"td__quantile-group\">\r\n          <div class=\"td__quantile\">\r\n            <div class=\"quantile__label quantile__label--ratio\">\r\n              <div class=\"label-box\">\r\n                <div>本期vs上期</div>\r\n              </div>\r\n            </div>\r\n            <div class=\"quantile__value quantile__value--ratio\">\r\n              ${chainRatio(getFromArr(xxxServiceRate,0,\'rate_avg\',\'number\'),getFromArr(pre1stxxxServiceRate,0,\'rate_avg\',\'number\'))}\r\n            </div>\r\n          </div>\r\n          <div class=\"td__quantile\">\r\n            <div class=\"quantile__label quantile__label--ratio\">\r\n              <div class=\"label-box\">\r\n                <div>上期vs上上期</div>\r\n              </div>\r\n            </div>\r\n            <div class=\"quantile__value quantile__value--ratio\">\r\n              ${chainRatio(getFromArr(pre1stxxxServiceRate,0,\'rate_avg\',\'number\'),getFromArr(pre2stxxxServiceRate,0,\'rate_avg\',\'number\'))}\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </td>\r\n      <td class=\"table__td\">\r\n        ${convertNumber(getFromArr(xxxServiceTrafficTotal,0,\'bytes\',\'number\'),\'byte\',1024)}\r\n      </td>\r\n      <td class=\"table__td\">\r\n        ${proportion(getFromArr(xxxServiceTrafficTotal,0,\'bytes\',\'number\'),getFromArr(trafficTotal,0,\'bytes\',\'number\'))}\r\n      </td>\r\n      <td class=\"table__td\">\r\n        <div class=\"td__quantile-group\">\r\n          <div class=\"td__quantile\">\r\n            <div class=\"quantile__label quantile__label--ratio\">\r\n              <div class=\"label-box\">\r\n                <div>本期vs上期</div>\r\n              </div>\r\n            </div>\r\n            <div class=\"quantile__value quantile__value--ratio\">\r\n              ${chainRatio(getFromArr(xxxServiceTrafficTotal,0,\'bytes\',\'number\'),getFromArr(pre1stxxxServiceTrafficTotal,0,\'bytes\',\'number\'))}\r\n            </div>\r\n          </div>\r\n          <div class=\"td__quantile\">\r\n            <div class=\"quantile__label quantile__label--ratio\">\r\n              <div class=\"label-box\">\r\n                <div>上期vs上上期</div>\r\n              </div>\r\n            </div>\r\n            <div class=\"quantile__value quantile__value--ratio\">\r\n              ${chainRatio(getFromArr(pre1stxxxServiceTrafficTotal,0,\'bytes\',\'number\'),getFromArr(pre2stxxxServiceTrafficTotal,0,\'bytes\',\'number\'))}\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </td>\r\n    </tr>\r\n    </tbody></table>\r\n  <div class=\"table__footer\">\r\n    <div class=\"footer__label\">* 流量速率分位值计算方式：</div>以5分钟为时间粒度计算平均流量速率vi，取观测时间范围内的{v1, v2, v3……vn}的分位值，下同。\r\n  </div>\r\n</div>\r\n<div class=\"echarts-box indent-3\">\r\n  <div class=\"echarts\">\r\n    <div class=\"echarts__canvas echarts__line\" id=\"canvas1\"></div>\r\n    <div class=\"echarts__title\">图1 当日流量变化曲线</div>\r\n  </div>\r\n</div>\r\n\r\n<div class=\"header3\">2.服务质量概况</div>\r\n<div class=\"table-box indent-3\">\r\n  <div class=\"table__title\">表2 客户端访问IDC${Tenant}（Z-A）的服务质量</div>\r\n  <table class=\"table\">\r\n    <thead class=\"table__header\">\r\n    <tr class=\"table__tr\">\r\n      <th class=\"table__th\">服务质量指标</th>\r\n      <th class=\"table__th\">分位值</th>\r\n      <th class=\"table__th\">峰值</th>\r\n      <th class=\"table__th\">均值</th>\r\n      <th class=\"table__th\">均值环比</th>\r\n    </tr>\r\n    </thead>\r\n    <tbody><tr class=\"table__tr\">\r\n      <td class=\"table__td\">TCP会话创建延迟</td>\r\n      <td class=\"table__td\">\r\n        <div class=\"td__quantile-group\">\r\n          <div class=\"td__quantile\">\r\n            <div class=\"quantile__label\">\r\n              <div class=\"label-box\">\r\n                <div><span class=\"quantile__point quantile__point--p50\"></span>P50</div>\r\n              </div>\r\n            </div>\r\n            <div class=\"quantile__value\">\r\n              ${convertTime(getFromArr(xxxServiceZATcp,0,\'establish_latency_p50\',\'number\'))}\r\n            </div>\r\n          </div>\r\n          <div class=\"td__quantile\">\r\n            <div class=\"quantile__label\">\r\n              <div class=\"label-box\">\r\n                <div><span class=\"quantile__point quantile__point--p90\"></span>P90</div>\r\n              </div>\r\n            </div>\r\n            <div class=\"quantile__value\">\r\n              ${convertTime(getFromArr(xxxServiceZATcp,0,\'establish_latency_p90\',\'number\'))}\r\n            </div>\r\n          </div>\r\n          <div class=\"td__quantile\">\r\n            <div class=\"quantile__label\">\r\n              <div class=\"label-box\">\r\n                <div><span class=\"quantile__point quantile__point--p99\"></span>P99</div>\r\n              </div>\r\n            </div>\r\n            <div class=\"quantile__value\">\r\n              ${convertTime(getFromArr(xxxServiceZATcp,0,\'establish_latency_p99\',\'number\'))}\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </td>\r\n      <td class=\"table__td\">\r\n        ${convertTime(getFromArr(xxxServiceZATcp,0,\'establish_latency_max\',\'number\'))}\r\n      </td>\r\n      <td class=\"table__td\">\r\n        ${convertTime(getFromArr(xxxServiceZATcp,0,\'establish_latency_avg\',\'number\'))}\r\n      </td>\r\n      <td class=\"table__td\">\r\n        ${chainRatio(getFromArr(xxxServiceZATcp,0,\'establish_latency_avg\',\'number\'),getFromArr(pre1stxxxServiceZATcp,0,\'establish_latency_avg\',\'number\'))}\r\n      </td>\r\n    </tr>\r\n    <tr class=\"table__tr\">\r\n      <td class=\"table__td\">缺包率</td>\r\n      <td class=\"table__td\">\r\n        <div class=\"td__quantile-group\">\r\n          <div class=\"td__quantile\">\r\n            <div class=\"quantile__label\">\r\n              <div class=\"label-box\">\r\n                <div><span class=\"quantile__point quantile__point--p50\"></span>P50</div>\r\n              </div>\r\n            </div>\r\n            <div class=\"quantile__value\">\r\n              ${convertPercent(getFromArr(xxxServiceZALoss,0,\'sequence_gap_loss_p50\',\'number\'))}\r\n            </div>\r\n          </div>\r\n          <div class=\"td__quantile\">\r\n            <div class=\"quantile__label\">\r\n              <div class=\"label-box\">\r\n                <div><span class=\"quantile__point quantile__point--p90\"></span>P90</div>\r\n              </div>\r\n            </div>\r\n            <div class=\"quantile__value\">\r\n              ${convertPercent(getFromArr(xxxServiceZALoss,0,\'sequence_gap_loss_p90\',\'number\'))}\r\n            </div>\r\n          </div>\r\n          <div class=\"td__quantile\">\r\n            <div class=\"quantile__label\">\r\n              <div class=\"label-box\">\r\n                <div><span class=\"quantile__point quantile__point--p99\"></span>P99</div>\r\n              </div>\r\n            </div>\r\n            <div class=\"quantile__value\">\r\n              ${convertPercent(getFromArr(xxxServiceZALoss,0,\'sequence_gap_loss_p99\',\'number\'))}\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </td>\r\n      <td class=\"table__td\">\r\n        ${convertPercent(getFromArr(xxxServiceZALoss,0,\'sequence_gap_loss_max\',\'number\'))}\r\n      </td>\r\n      <td class=\"table__td\">\r\n        ${convertPercent(getFromArr(xxxServiceZALoss,0,\'sequence_gap_loss_avg\',\'number\'))}\r\n      </td>\r\n      <td class=\"table__td\">\r\n        ${chainRatio(getFromArr(xxxServiceZALoss,0,\'sequence_gap_loss_avg\',\'number\'),getFromArr(pre1stxxxServiceZALoss,0,\'sequence_gap_loss_avg\',\'number\'))}\r\n      </td>\r\n    </tr>\r\n    </tbody></table>\r\n</div>\r\n<div class=\"table-box indent-3\">\r\n  <div class=\"table__title\">表3 IDC${Tenant}内容获取（A-Z）的服务质量</div>\r\n  <table class=\"table\">\r\n    <thead class=\"table__header\">\r\n    <tr class=\"table__tr\">\r\n      <th class=\"table__th\">服务质量指标</th>\r\n      <th class=\"table__th\">分位值</th>\r\n      <th class=\"table__th\">峰值</th>\r\n      <th class=\"table__th\">均值</th>\r\n      <th class=\"table__th\">均值环比</th>\r\n    </tr>\r\n    </thead>\r\n    <tbody><tr class=\"table__tr\">\r\n      <td class=\"table__td\">TCP会话创建延迟</td>\r\n      <td class=\"table__td\">\r\n        <div class=\"td__quantile-group\">\r\n          <div class=\"td__quantile\">\r\n            <div class=\"quantile__label\">\r\n              <div class=\"label-box\">\r\n\r\n                <div><span class=\"quantile__point quantile__point--p50\"></span>P50</div>\r\n              </div>\r\n            </div>\r\n            <div class=\"quantile__value\">\r\n              ${convertTime(getFromArr(xxxServiceAZTcp,0,\'establish_latency_p50\',\'number\'))}\r\n            </div>\r\n          </div>\r\n          <div class=\"td__quantile\">\r\n            <div class=\"quantile__label\">\r\n              <div class=\"label-box\">\r\n\r\n                <div><span class=\"quantile__point quantile__point--p90\"></span>P90</div>\r\n              </div>\r\n            </div>\r\n            <div class=\"quantile__value\">\r\n              ${convertTime(getFromArr(xxxServiceAZTcp,0,\'establish_latency_p90\',\'number\'))}\r\n            </div>\r\n          </div>\r\n          <div class=\"td__quantile\">\r\n            <div class=\"quantile__label\">\r\n              <div class=\"label-box\">\r\n                <div><span class=\"quantile__point quantile__point--p99\"></span>P99</div>\r\n              </div>\r\n            </div>\r\n            <div class=\"quantile__value\">\r\n              ${convertTime(getFromArr(xxxServiceAZTcp,0,\'establish_latency_p99\',\'number\'))}\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </td>\r\n      <td class=\"table__td\">\r\n        ${convertTime(getFromArr(xxxServiceAZTcp,0,\'establish_latency_max\',\'number\'))}\r\n      </td>\r\n      <td class=\"table__td\">\r\n        ${convertTime(getFromArr(xxxServiceAZTcp,0,\'establish_latency_avg\',\'number\'))}\r\n      </td>\r\n      <td class=\"table__td\">\r\n        ${chainRatio(getFromArr(xxxServiceAZTcp,0,\'establish_latency_avg\',\'number\'),getFromArr(pre1stxxxServiceAZTcp,0,\'establish_latency_avg\',\'number\'))}\r\n      </td>\r\n    </tr>\r\n    <tr class=\"table__tr\">\r\n      <td class=\"table__td\">缺包率</td>\r\n      <td class=\"table__td\">\r\n        <div class=\"td__quantile-group\">\r\n          <div class=\"td__quantile\">\r\n            <div class=\"quantile__label\">\r\n              <div class=\"label-box\">\r\n                <div><span class=\"quantile__point quantile__point--p50\"></span>P50</div>\r\n              </div>\r\n            </div>\r\n            <div class=\"quantile__value\">\r\n              ${convertPercent(getFromArr(xxxServiceAZLoss,0,\'sequence_gap_loss_p50\',\'number\'))}\r\n            </div>\r\n          </div>\r\n          <div class=\"td__quantile\">\r\n            <div class=\"quantile__label\">\r\n              <div class=\"label-box\">\r\n                <div><span class=\"quantile__point quantile__point--p90\"></span>P90</div>\r\n              </div>\r\n            </div>\r\n            <div class=\"quantile__value\">\r\n              ${convertPercent(getFromArr(xxxServiceAZLoss,0,\'sequence_gap_loss_p90\',\'number\'))}\r\n            </div>\r\n          </div>\r\n          <div class=\"td__quantile\">\r\n            <div class=\"quantile__label\">\r\n              <div class=\"label-box\">\r\n                <div><span class=\"quantile__point quantile__point--p99\"></span>P99</div>\r\n              </div>\r\n            </div>\r\n            <div class=\"quantile__value\">\r\n              ${convertPercent(getFromArr(xxxServiceAZLoss,0,\'sequence_gap_loss_p99\',\'number\'))}\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </td>\r\n      <td class=\"table__td\">\r\n        ${convertPercent(getFromArr(xxxServiceAZLoss,0,\'sequence_gap_loss_max\',\'number\'))}\r\n      </td>\r\n      <td class=\"table__td\">\r\n        ${convertPercent(getFromArr(xxxServiceAZLoss,0,\'sequence_gap_loss_avg\',\'number\'))}\r\n      </td>\r\n      <td class=\"table__td\">\r\n        ${chainRatio(getFromArr(xxxServiceAZLoss,0,\'sequence_gap_loss_avg\',\'number\'),getFromArr(pre1stxxxServiceAZLoss,0,\'sequence_gap_loss_avg\',\'number\'))}\r\n      </td>\r\n    </tr>\r\n    </tbody></table>\r\n</div>\r\n\r\n<div class=\"header2\">二.业务分布</div>\r\n<div class=\"echarts-box indent-3\">\r\n  <div class=\"echarts pie-style\">\r\n    <div class=\"echarts__canvas echarts__pie\" id=\"canvas12\"></div>\r\n    <div class=\"echarts__title\">图2 相关APP流量占比</div>\r\n  </div>\r\n  <div class=\"echarts pie-style\">\r\n    <div class=\"echarts__canvas echarts__pie\" id=\"canvas13\"></div>\r\n    <div class=\"echarts__title\">图3 相关域名流量占比</div>\r\n  </div>\r\n</div>\r\n<div class=\"echarts-box indent-3\">\r\n  <div class=\"echarts pie-style\">\r\n    <div class=\"echarts__canvas echarts__pie\" id=\"canvas18\"></div>\r\n    <div class=\"echarts__title\">图4 应用层协议流量占比</div>\r\n  </div>\r\n  <div class=\"echarts\"></div>\r\n</div>\r\n\r\n<div class=\"header2\">三.地理位置分布</div>\r\n<div class=\"header3\">1.各省份流量分布</div>\r\n<div class=\"echarts-box indent-3\">\r\n  <div class=\"echarts\">\r\n    <div class=\"echarts__canvas echarts__line-and-bar\" id=\"canvas2\"></div>\r\n  </div>\r\n</div>\r\n<div class=\"table-box indent-3\">\r\n  <table class=\"table\">\r\n    <thead class=\"table__header\">\r\n    <tr class=\"table__tr\">\r\n      <th class=\"table__th\">各省份流量速率</th>\r\n      <#if provinceZASentTrafficBytesTop10??>\r\n        <#list provinceZASentTrafficBytesTop10 as val>\r\n          <th class=\"table__th\">${getFromObj(val,\'client_province\',\'string\')}</th>\r\n        </#list>\r\n      </#if>\r\n    </tr>\r\n    </thead>\r\n    <tbody><tr class=\"table__tr font-size-14\">\r\n      <td class=\"table__td\">峰值</td>\r\n      <#if provinceZASentTrafficBytesTop10??>\r\n        <#list provinceZASentTrafficBytesTop10 as val>\r\n          <td class=\"table__td\">${convertNumber(getFromObj(val,\'sent_rate_max\',\'number\'),\'bps\',1000)}</td>\r\n        </#list>\r\n      </#if>\r\n    </tr>\r\n    <tr class=\"table__tr font-size-14\">\r\n      <td class=\"table__td\">均值</td>\r\n      <#if provinceZASentTrafficBytesTop10??>\r\n        <#list provinceZASentTrafficBytesTop10 as val>\r\n          <td class=\"table__td\">${convertNumber(getFromObj(val,\'sent_rate_avg\',\'number\'),\'bps\',1000)}</td>\r\n        </#list>\r\n      </#if>\r\n    </tr>\r\n    </tbody></table>\r\n  <div class=\"echarts__title echarts__line-and-bar-title\">图5 IDC${Tenant}对外（省Z-A）服务能力的TOP10省份请求流量分布</div>\r\n</d