0},rate_max:${jsGetNumFromObj(d,\'rate_max\')/1000}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n  var preAppCompanyRegionTrafficBytes1st = [\r\n    <#if preAppCompanyRegionTrafficBytes1st??>\r\n    <#list preAppCompanyRegionTrafficBytes1st as d>\r\n    {client_region:\'${getFromObj(d,\'client_region\',\'string\')}\',app_company:\'${getFromObj(d,\'app_company\',\'string\')}\',bytes:${jsGetNumFromObj(d,\'bytes\')/1024},rate50:${jsGetNumFromObj(d,\'rate50\')/1000},rate90:${jsGetNumFromObj(d,\'rate90\')/1000},rate99:${jsGetNumFromObj(d,\'rate99\')/1000},rate_avg:${jsGetNumFromObj(d,\'rate_avg\')/1000},rate_min:${jsGetNumFromObj(d,\'rate_min\')/1000},rate_max:${jsGetNumFromObj(d,\'rate_max\')/1000}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n  var pre2ndAppCompanyRegionTrafficBytes1st = [\r\n    <#if pre2ndAppCompanyRegionTrafficBytes1st??>\r\n    <#list pre2ndAppCompanyRegionTrafficBytes1st as d>\r\n    {client_region:\'${getFromObj(d,\'client_region\',\'string\')}\',app_company:\'${getFromObj(d,\'app_company\',\'string\')}\',bytes:${jsGetNumFromObj(d,\'bytes\')/1024},rate50:${jsGetNumFromObj(d,\'rate50\')/1000},rate90:${jsGetNumFromObj(d,\'rate90\')/1000},rate99:${jsGetNumFromObj(d,\'rate99\')/1000},rate_avg:${jsGetNumFromObj(d,\'rate_avg\')/1000},rate_min:${jsGetNumFromObj(d,\'rate_min\')/1000},rate_max:${jsGetNumFromObj(d,\'rate_max\')/1000}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n  // num2(AppCompany Province Traffic Bytes 2nd)\r\n  var appCompanyRegionTrafficBytes2nd = [\r\n    <#if appCompanyRegionTrafficBytes2nd??>\r\n    <#list appCompanyRegionTrafficBytes2nd as d>\r\n    {client_region:\'${getFromObj(d,\'client_region\',\'string\')}\',app_company:\'${getFromObj(d,\'app_company\',\'string\')}\',bytes:${jsGetNumFromObj(d,\'bytes\')/1024},rate50:${jsGetNumFromObj(d,\'rate50\')/1000},rate90:${jsGetNumFromObj(d,\'rate90\')/1000},rate99:${jsGetNumFromObj(d,\'rate99\')/1000},rate_avg:${jsGetNumFromObj(d,\'rate_avg\')/1000},rate_min:${jsGetNumFromObj(d,\'rate_min\')/1000},rate_max:${jsGetNumFromObj(d,\'rate_max\')/1000}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n  var preAppCompanyRegionTrafficBytes2nd = [\r\n    <#if preAppCompanyRegionTrafficBytes2nd??>\r\n    <#list preAppCompanyRegionTrafficBytes2nd as d>\r\n    {client_region:\'${getFromObj(d,\'client_region\',\'string\')}\',app_company:\'${getFromObj(d,\'app_company\',\'string\')}\',bytes:${jsGetNumFromObj(d,\'bytes\')/1024},rate50:${jsGetNumFromObj(d,\'rate50\')/1000},rate90:${jsGetNumFromObj(d,\'rate90\')/1000},rate99:${jsGetNumFromObj(d,\'rate99\')/1000},rate_avg:${jsGetNumFromObj(d,\'rate_avg\')/1000},rate_min:${jsGetNumFromObj(d,\'rate_min\')/1000},rate_max:${jsGetNumFromObj(d,\'rate_max\')/1000}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n  var pre2ndAppCompanyRegionTrafficBytes2nd = [\r\n    <#if pre2ndAppCompanyRegionTrafficBytes2nd??>\r\n    <#list pre2ndAppCompanyRegionTrafficBytes2nd as d>\r\n    {client_region:\'${getFromObj(d,\'client_region\',\'string\')}\',app_company:\'${getFromObj(d,\'app_company\',\'string\')}\',bytes:${jsGetNumFromObj(d,\'bytes\')/1024},rate50:${jsGetNumFromObj(d,\'rate50\')/1000},rate90:${jsGetNumFromObj(d,\'rate90\')/1000},rate99:${jsGetNumFromObj(d,\'rate99\')/1000},rate_avg:${jsGetNumFromObj(d,\'rate_avg\')/1000},rate_min:${jsGetNumFromObj(d,\'rate_min\')/1000},rate_max:${jsGetNumFromObj(d,\'rate_max\')/1000}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n  // num3(AppCompany Province Traffic Bytes 3rd)\r\n  var appCompanyRegionTrafficBytes3rd = [\r\n    <#if appCompanyRegionTrafficBytes3rd??>\r\n    <#list appCompanyRegionTrafficBytes3rd as d>\r\n    {client_region:\'${getFromObj(d,\'client_region\',\'string\')}\',app_company:\'${getFromObj(d,\'app_company\',\'string\')}\',bytes:${jsGetNumFromObj(d,\'bytes\')/1024},rate50:${jsGetNumFromObj(d,\'rate50\')/1000},rate90:${jsGetNumFromObj(d,\'rate90\')/1000},rate99:${jsGetNumFromObj(d,\'rate99\')/1000},rate_avg:${jsGetNumFromObj(d,\'rate_avg\')/1000},rate_min:${jsGetNumFromObj(d,\'rate_min\')/1000},rate_max:${jsGetNumFromObj(d,\'rate_max\')/1000}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n  var preAppCompanyRegionTrafficBytes3rd = [\r\n    <#if preAppCompanyRegionTrafficBytes3rd??>\r\n    <#list preAppCompanyRegionTrafficBytes3rd as d>\r\n    {client_region:\'${getFromObj(d,\'client_region\',\'string\')}\',app_company:\'${getFromObj(d,\'app_company\',\'string\')}\',bytes:${jsGetNumFromObj(d,\'bytes\')/1024},rate50:${jsGetNumFromObj(d,\'rate50\')/1000},rate90:${jsGetNumFromObj(d,\'rate90\')/1000},rate99:${jsGetNumFromObj(d,\'rate99\')/1000},rate_avg:${jsGetNumFromObj(d,\'rate_avg\')/1000},rate_min:${jsGetNumFromObj(d,\'rate_min\')/1000},rate_max:${jsGetNumFromObj(d,\'rate_max\')/1000}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n  var pre2ndAppCompanyRegionTrafficBytes3rd = [\r\n    <#if pre2ndAppCompanyRegionTrafficBytes3rd??>\r\n    <#list pre2ndAppCompanyRegionTrafficBytes3rd as d>\r\n    {client_region:\'${getFromObj(d,\'client_region\',\'string\')}\',app_company:\'${getFromObj(d,\'app_company\',\'string\')}\',bytes:${jsGetNumFromObj(d,\'bytes\')/1024},rate50:${jsGetNumFromObj(d,\'rate50\')/1000},rate90:${jsGetNumFromObj(d,\'rate90\')/1000},rate99:${jsGetNumFromObj(d,\'rate99\')/1000},rate_avg:${jsGetNumFromObj(d,\'rate_avg\')/1000},rate_min:${jsGetNumFromObj(d,\'rate_min\')/1000},rate_max:${jsGetNumFromObj(d,\'rate_max\')/1000}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n  // Top 10省内各地区流量分布（IDC内容获取(地市A-Z)服务能力）\r\n  var regionAZSentTrafficBytesTop10 = [\r\n    <#if regionAZSentTrafficBytesTop10??>\r\n    <#list regionAZSentTrafficBytesTop10 as d>\r\n    {server_region:\'${getFromObj(d,\'server_region\',\'string\')}\',bytes_sent:${jsGetNumFromObj(d,\'bytes_sent\')/1024},sent_rate_avg:${jsGetNumFromObj(d,\'sent_rate_avg\')/1000},sent_rate_max:${jsGetNumFromObj(d,\'sent_rate_max\')/1000},sent_rate_min:${jsGetNumFromObj(d,\'sent_rate_min\')/1000}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n  var pre1stRegionAZSentTrafficBytesTop10 = [\r\n    <#if pre1stRegionAZSentTrafficBytesTop10??>\r\n    <#list pre1stRegionAZSentTrafficBytesTop10 as d>\r\n    {server_region:\'${getFromObj(d,\'server_region\',\'string\')}\',bytes_sent:${jsGetNumFromObj(d,\'bytes_sent\')/1024},sent_rate_avg:${jsGetNumFromObj(d,\'sent_rate_avg\')/1000},sent_rate_max:${jsGetNumFromObj(d,\'sent_rate_max\')/1000},sent_rate_min:${jsGetNumFromObj(d,\'sent_rate_min\')/1000}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n  var pre2stRegionAZSentTrafficBytesTop10 = [\r\n    <#if pre2stRegionAZSentTrafficBytesTop10??>\r\n    <#list pre2stRegionAZSentTrafficBytesTop10 as d>\r\n    {server_region:\'${getFromObj(d,\'server_region\',\'string\')}\',bytes_sent:${jsGetNumFromObj(d,\'bytes_sent\')/1024},sent_rate_avg:${jsGetNumFromObj(d,\'sent_rate_avg\')/1000},sent_rate_max:${jsGetNumFromObj(d,\'sent_rate_max\')/1000},sent_rate_min:${jsGetNumFromObj(d,\'sent_rate_min\')/1000}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n  // IDC内容获取(地市A-Z)服务能力 TOP 10 省内地区响应流量分布(Region AZ\r\n  var regionAZReceivedTrafficBytesTop10 = [\r\n    <#if regionAZReceivedTrafficBytesTop10??>\r\n    <#list regionAZReceivedTrafficBytesTop10 as d>\r\n    {server_region:\'${getFromObj(d,\'server_region\',\'string\')}\',bytes_received:${jsGetNumFromObj(d,\'bytes_received\')/1024},received_rate_avg:${jsGetNumFromObj(d,\'received_rate_avg\')/1000},received_rate_max:${jsGetNumFromObj(d,\'received_rate_max\')/1000},received_rate_min:${jsGetNumFromObj(d,\'received_rate_min\')/1000}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n  var pre1stRegionAZReceivedTrafficBytesTop10 = [\r\n    <#if pre1stRegionAZReceivedTrafficBytesTop10??>\r\n    <#list pre1stRegionAZReceivedTrafficBytesTop10 as d>\r\n    {server_region:\'${getFromObj(d,\'server_region\',\'string\')}\',bytes_received:${jsGetNumFromObj(d,\'bytes_received\')/1024},received_rate_avg:${jsGetNumFromObj(d,\'received_rate_avg\')/1000},received_rate_max:${jsGetNumFromObj(d,\'received_rate_max\')/1000},received_rate_min:${jsGetNumFromObj(d,\'received_rate_min\')/1000}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n  var pre2stRegionAZReceivedTrafficBytesTop10 = [\r\n    <#if pre2stRegionAZReceivedTrafficBytesTop10??>\r\n    <#list pre2stRegionAZReceivedTrafficBytesTop10 as d>\r\n    {server_region:\'${getFromObj(d,\'server_region\',\'string\')}\',bytes_received:${jsGetNumFromObj(d,\'bytes_received\')/1024},received_rate_avg:${jsGetNumFromObj(d,\'received_rate_avg\')/1000},received_rate_max:${jsGetNumFromObj(d,\'received_rate_max\')/1000},received_rate_min:${jsGetNumFromObj(d,\'received_rate_min\')/1000}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n\r\n  /* 4.1 IDC xxx 命中流量 */\r\n  // 总流量\r\n  var xxxServiceTrafficBytes = [\r\n    <#if xxxServiceTrafficBytes??>\r\n    <#list xxxServiceTrafficBytes as d>\r\n    {received_bytes:${jsGetNumFromObj(d,\'received_bytes\')/1024}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n  // 未命中缓存流量\r\n  var xxxServiceMissCacheBytes = [\r\n    <#if xxxServiceMissCacheBytes??>\r\n    <#list xxxServiceMissCacheBytes as d>\r\n    {received_bytes:${jsGetNumFromObj(d,\'received_bytes\')/1024}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n  /* 4.2 IDCxxx缓存命中会话 */\r\n  var xxxServiceTotalSessions = [\r\n    <#if xxxServiceTotalSessions??>\r\n    <#list xxxServiceTotalSessions as d>\r\n    {sessions:${jsGetNumFromObj(d,\'sessions\')}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n  var xxxServiceMissCacheSessions = [\r\n    <#if xxxServiceMissCacheSessions??>\r\n    <#list xxxServiceMissCacheSessions	 as d>\r\n    {sessions:${jsGetNumFromObj(d,\'sessions\')}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n  /* 4.3 IDCxxx缓存未命中APP流量 */\r\n  var top10AppMissCacheBytes = [\r\n    <#if top10AppMissCacheBytes??>\r\n    <#list top10AppMissCacheBytes as d>\r\n    {app_company:\'${getFromObj(d,\'app_company\',\'string\')}\',received_bytes:${jsGetNumFromObj(d,\'received_bytes\')/1024}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n  /* 4.4 IDCxxx缓存未命中DOMAIN流量 */\r\n  var top10DomainMissCacheBytes = [\r\n    <#if top10DomainMissCacheBytes??>\r\n    <#list top10DomainMissCacheBytes as d>\r\n    {domain:\'${getFromObj(d,\'domain\',\'string\')}\',received_bytes:${jsGetNumFromObj(d,\'received_bytes\')/1024}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n  /* 4.5 IDCxxx缓存未命中的应用层协议流量占比 */\r\n  var top10ProtocolMissCacheBytes = [\r\n    <#if top10ProtocolMissCacheBytes??>\r\n    <#list top10ProtocolMissCacheBytes as d>\r\n    {l7_protocol:\'${getFromObj(d,\'l7_protocol\',\'string\')}\',received_bytes:${jsGetNumFromObj(d,\'received_bytes\')/1024}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n  /* 4.6 IDCxxx缓存未命中APP会话 */\r\n  var top10AppMissCacheSessions = [\r\n    <#if top10AppMissCacheSessions??>\r\n    <#list top10AppMissCacheSessions as d>\r\n    {app_company:\'${getFromObj(d,\'app_company\',\'string\')}\',sessions:${jsGetNumFromObj(d,\'sessions\')}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n  /* 4.7 IDCxxx缓存未命中DOMAIN会话 */\r\n  var top10DomainMissCacheSessions = [\r\n    <#if top10DomainMissCacheSessions??>\r\n    <#list top10DomainMissCacheSessions as d>\r\n    {domain:\'${getFromObj(d,\'domain\',\'string\')}\',sessions:${jsGetNumFromObj(d,\'sessions\')}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n  /* 4.8 IDCxxx缓存未命中的应用层协议会话占比 */\r\n  var top10ProtocolMissCacheSessions = [\r\n    <#if top10ProtocolMissCacheSessions??>\r\n    <#list top10ProtocolMissCacheSessions as d>\r\n    {l7_protocol:\'${getFromObj(d,\'l7_protocol\',\'string\')}\',sessions:${jsGetNumFromObj(d,\'sessions\')}},\r\n    </#list>\r\n    </#if>\r\n  ]\r\n\r\n  /** 数据 end */\r\n\r\n\r\n  ${reportJsCommon}\r\n\r\n  if (!isNaN(parseInt(timeZoneOffset))) {\r\n    var explorerTimeOffset = new Date().getTimezoneOffset() * 60 * 1000\r\n    xxxServiceTrafficChangingCurve = xxxServiceTrafficChangingCurve.map(d => ({ rate: d.rate, stat_time: d.stat_time + explorerTimeOffset + timeZoneOffset}))\r\n    timeRange = [timeRange[0] + explorerTimeOffset / 1000 + timeZoneOffset / 1000, timeRange[1] + explorerTimeOffset / 1000 + timeZoneOffset / 1000]\r\n  }\r\n  // 计算出前三个周期的时间戳范围，填充时间\r\n  function initTimeRange () {\r\n    var timeOffset = timeRange[1] - timeRange[0]\r\n    var wholeTimeOffset = [60 * 60 - 1, 60 * 60 * 24 - 1, 60 * 60 * 24 * 7 - 1]\r\n    if (wholeTimeOffset.indexOf(timeOffset) > -1) {\r\n      timeOffset++\r\n    }\r\n    var prevTimeRange = [timeRange[0] - timeOffset, timeRange[1] - timeOffset]\r\n    var pprevTimeRange = [prevTimeRange[0] - timeOffset, prevTimeRange[1] - timeOffset]\r\n    var ppprevTimeRange = [pprevTimeRange[0] - timeOffset, pprevTimeRange[1] - timeOffset]\r\n    var statisticTimeRange = [prevTimeRange[0] - timeOffset, prevTimeRange[1] - timeOffset]\r\n\r\n    var currentRanges = [\'currentRange0\', \'currentRange7\', \'currentRange8\', \'currentRange13\', \'currentRange14\']\r\n    var prevRanges = [\'prevRange0\', \'prevRange7\', \'prevRange8\', \'prevRange13\', \'prevRange14\']\r\n    var statisticsRanges = [\r\n      \'statisticsRange1\',\r\n      \'statisticsRange2\',\r\n      \'statisticsRange3\',\r\n      \'statisticsRange4\'\r\n    ]\r\n\r\n    var currentRangeStr = \'\'\r\n    var prevRangeStr = \'\'\r\n    var statisticsStr = \'\'\r\n    if (isWholeDay(timeRange)) {\r\n      currentRangeStr = timestampToStr(timeRange[0]).substring(0, 10)\r\n      prevRangeStr = timestampToStr(prevTimeRange[0]).substring(0, 10)\r\n      statisticsStr = timestampToStr(statisticTimeRange[0]).substring(0, 10)\r\n    } else {\r\n      currentRangeStr = timestampToStr(timeRange[0]) + \' -- \' + timestampToStr(timeRange[1])\r\n      prevRangeStr = timestampToStr(prevTimeRange[0]) + \' -- \' + timestampToStr(prevTimeRange[1])\r\n      statisticsStr = timestampToStr(statisticTimeRange[0]) + \' -- \' + timestampToStr(statisticTimeRange[1])\r\n    }\r\n    currentRanges.forEach(c => {\r\n      var dom = document.getElementById(c)\r\n      if (dom) {\r\n        dom.innerText = currentRangeStr\r\n      }\r\n    })\r\n    prevRanges.forEach(c => {\r\n      var dom = document.getElementById(c)\r\n      if (dom) {\r\n        dom.innerText = prevRangeStr\r\n      }\r\n    })\r\n    statisticsRanges.forEach(c => {\r\n      var dom = document.getElementById(c)\r\n      if (dom) {\r\n        dom.innerText = statisticsStr\r\n      }\r\n    })\r\n  }\r\n\r\n  // Top5 流量占比 公方法\r\n  function barDataFormatHandling (total, preTotalList, ppreTotalList, list, preList, ppreList, oneLevelKey, twoLevelKey, dataKey) {\r\n    var seriesData = []\r\n    var prevSeriesData = []\r\n    var pprevSeriesData = []\r\n    var categoryData = []\r\n    if (total) {\r\n      var prevTotal = preTotalList.find(t => t[oneLevelKey] === total[oneLevelKey])\r\n      if (prevTotal) {\r\n        var pprevTotal = ppreTotalList.find(d => d[oneLevelKey] === prevTotal[oneLevelKey])\r\n      }\r\n      list.forEach(d => {\r\n        if (d[oneLevelKey] === total[oneLevelKey]) {\r\n          categoryData.push(d[twoLevelKey])\r\n          if (total && total[dataKey] !== 0) {\r\n            seriesData.push(d[dataKey] / total[dataKey])\r\n          } else {\r\n            seriesData.push(0)\r\n          }\r\n          var prevTwoLevel = preList.find(p => p[twoLevelKey] === d[twoLevelKey] && p[oneLevelKey] === d[oneLevelKey])\r\n          if (prevTwoLevel && prevTwoLevel[dataKey] && prevTotal && prevTotal[dataKey] !== 0) {\r\n            prevSeriesData.push(prevTwoLevel[dataKey] / prevTotal[dataKey])\r\n            var pprevTwoLevel = ppreList.find(p => p[twoLevelKey] === d[twoLevelKey] && p[oneLevelKey] === d[oneLevelKey])\r\n            if (pprevTwoLevel && pprevTwoLevel[dataKey] && pprevTotal && pprevTotal[dataKey] !== 0) {\r\n              pprevSeriesData.push(pprevTwoLevel[dataKey] / pprevTotal[dataKey])\r\n            } else {\r\n              pprevSeriesData.push(0)\r\n            }\r\n          } else {\r\n            prevSeriesData.push(0)\r\n          }\r\n        }\r\n      })\r\n    }\r\n    return {\r\n      seriesData,\r\n      prevSeriesData,\r\n      pprevSeriesData,\r\n      categoryData\r\n    }\r\n  }\r\n\r\n  function initEcharts1 () {\r\n    var seriesData1 = xxxServiceTrafficChangingCurve.map(d => [d.stat_time, d.rate])\r\n    var unit1 = \'Kbps\'\r\n\r\n    var myChart = initEchartsInstance(\'canvas1\')\r\n    var option = {\r\n      color: chartColor,\r\n      animation: false,\r\n      grid: {\r\n        left: 100,\r\n        right: 120,\r\n        bottom: 25,\r\n        top: 40\r\n      },\r\n      xAxis: {\r\n        type: \'time\',\r\n        splitNumber: 12\r\n      },\r\n      yAxis: {\r\n        splitLine: { show: false },\r\n        offset: 10,\r\n        axisLabel: {\r\n          formatter (params) {\r\n            return unitConvert(params, unitTypes.bps, unit1).join(\' \')\r\n          }\r\n        }\r\n      },\r\n      series: {\r\n        type: \'line\',\r\n        symbol: \'none\',\r\n        data: seriesData1,\r\n        markLine: {\r\n          silent: true,\r\n          lineStyle: {\r\n            color: \'rgb(153,153,153)\'\r\n          },\r\n          symbol: \'none\',\r\n          label: {\r\n            formatter (params) {\r\n              var arr = unitConvert(params.value, unitTypes.bps, unit1).join(\' \')\r\n              var desc = \'\'\r\n              switch (params.dataIndex) {\r\n                case 0: {\r\n                  desc = \'P50\'\r\n                  break\r\n                }\r\n                case 1: {\r\n                  desc = \'P90\'\r\n                  break\r\n                }\r\n                case 2: {\r\n                  desc = \'P99\'\r\n                  break\r\n                }\r\n                default: break\r\n              }\r\n              return arr + \' (\' + desc + \')\'\r\n            }\r\n          }\r\n        }\r\n      }\r\n    }\r\n    if (xxxServiceRate.rate99 > xxxServiceRate.rate90 && xxxServiceRate.rate90 > xxxServiceRate.rate50 && (xxxServiceRate.rate90 && xxxServiceRate.rate50 && xxxServiceRate.rate99) !== 0){\r\n      option.visualMap = {\r\n        show: false,\r\n        pieces: [\r\n   