startTime} AND common_recv_time < ${endTime}\",\r\n			\"type\": \"table\",\r\n			\"valueAlias\": \"trafficSummary\"\r\n		},\r\n		{\r\n			\"querySql\": \"SELECT SUM(common_c2s_byte_num) AS bytes_sent, SUM(common_s2c_byte_num) AS bytes_received, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes, SUM(common_sessions) AS sessions FROM session_record_cn WHERE common_recv_time >= ${startTime} - ${timeDiff} AND common_recv_time < ${endTime} - ${timeDiff}\",\r\n			\"type\": \"table\",\r\n			\"valueAlias\": \"trafficSummaryPre1st\"\r\n		},\r\n		{\r\n			\"querySql\": \"SELECT SUM(common_c2s_byte_num) AS bytes_sent, SUM(common_s2c_byte_num) AS bytes_received, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes, SUM(common_sessions) AS sessions FROM session_record_cn WHERE common_recv_time >= ${startTime} - ${timeDiff} * 2 AND common_recv_time < ${endTime} - ${timeDiff} * 2\",\r\n			\"type\": \"table\",\r\n			\"valueAlias\": \"trafficSummaryPre2nd\"\r\n		},\r\n		{\r\n			\"querySql\": \"SELECT IFNULL( ROUND(QUANTILE(rate,0.5), 4), 0) AS rate50, IFNULL( ROUND(QUANTILE(rate,0.9), 4), 0) AS rate90, IFNULL( ROUND(QUANTILE(rate,0.99), 4), 0) AS rate99, IFNULL( ROUND(AVG(rate), 4), 0) AS rate_avg, ROUND(max(rate), 4) AS rate_max, ROUND(min(rate), 4) AS rate_min FROM ( SELECT SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes, (bytes * 8) / 300 AS rate, toDateTime(toStartOfInterval(toDateTime(common_recv_time), INTERVAL 5 MINUTE)) AS granularity FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} GROUP BY granularity)\",\r\n			\"type\": \"table\",\r\n			\"valueAlias\": \"trafficRate\"\r\n		},\r\n		{\r\n			\"querySql\": \"SELECT IFNULL( ROUND(QUANTILE(rate,0.5), 4), 0) AS rate50, IFNULL( ROUND(QUANTILE(rate,0.9), 4), 0) AS rate90, IFNULL( ROUND(QUANTILE(rate,0.99), 4), 0) AS rate99, IFNULL( ROUND(AVG(rate), 4), 0) AS rate_avg, ROUND(max(rate), 4) AS rate_max, ROUND(min(rate), 4) AS rate_min FROM ( SELECT SUM(common_c2s_byte_num 