<tr class=\"table__tr\">\r\n            <th class=\"table__th\">各地区流量速率</th>\r\n            <#if regionOut2inReceivedTrafficBytesTop10??>\r\n                <#list regionOut2inReceivedTrafficBytesTop10 as val>\r\n                    <th class=\"table__th\">${getFromObj(val,\'server_region\',\'string\')}</th>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </thead>\r\n        <tbody>\r\n        <tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">峰值</td>\r\n            <#if regionOut2inReceivedTrafficBytesTop10??>\r\n                <#list regionOut2inReceivedTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'received_rate_max\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        <tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">均值</td>\r\n            <#if regionOut2inReceivedTrafficBytesTop10??>\r\n                <#list regionOut2inReceivedTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'received_rate_avg\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </tbody></table>\r\n    <div class=\"echarts__title echarts__line-and-bar-title\">图11 省外访问省内${Provider}服务的Top 10 省内地区的响应流量分布</div>\r\n</div>\r\n<div class=\"header2\">四.链路方向流量构成</div>\r\n<div class=\"echarts-box indent-3\">\r\n    <div class=\"echarts\">\r\n        <div class=\"echarts__canvas echarts__sankey\" id=\"canvas42\"></div>\r\n    </div>\r\n</div>\r\n<div class=\"echarts__title\">图12 省内访问省外${Provider}会话的流量流向图</div>\r\n<div class=\"table-box indent-3\">\r\n    <table class=\"table table-contain-echarts\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th></th>\r\n            <th class=\"table__th\">西宁</th>\r\n            <th class=\"table__th\">太原</th>\r\n            <th class=\"table__th\">西安</th>\r\n        </tr>\r\n        </thead>\r\n        <tbody>\r\n        <tr class=\"table__tr\">\r\n            <td class=\"table__td table__td-up\">上行链路</td>\r\n            <td class=\"table__td echarts__td-bar\">\r\n                <div class=\"echarts-box\">\r\n                    <div class=\"echarts\">\r\n                        <div class=\"echarts__canvas\" id=\"canvas49\"></div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n            <td class=\"table__td echarts__td-bar\">\r\n                <div class=\"echarts-box\">\r\n                    <div class=\"echarts\">\r\n                        <div class=\"echarts__canvas\" id=\"canvas50\"></div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n            <td class=\"table__td echarts__td-bar\">\r\n                <div class=\"echarts-box\">\r\n                    <div class=\"echarts\">\r\n                        <div class=\"echarts__canvas\" id=\"canvas51\"></div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n        </tr>\r\n        <tr class=\"table__tr\">\r\n            <td class=\"table__td table__td-down\">下行链路</td>\r\n            <td class=\"table__td echarts__td-bar\">\r\n                <div class=\"echarts-box\">\r\n                    <div class=\"echarts\">\r\n                        <div class=\"echarts__canvas\" id=\"canvas52\"></div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n            <td class=\"table__td echarts__td-bar\">\r\n                <div class=\"echarts-box\">\r\n                    <div class=\"echarts\">\r\n                        <div class=\"echarts__canvas\" id=\"canvas53\"></div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n            <td class=\"table__td echarts__td-bar\">\r\n                <div class=\"echarts-box\">\r\n                    <div class=\"echarts\">\r\n                        <div class=\"echarts__canvas\" id=\"canvas54\"></div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n        </tr>\r\n        </tbody></table>\r\n</div>\r\n<div class=\"echarts__legends\">\r\n    <span class=\"echarts__legend\">\r\n    <span class=\"color-block light-green\"></span>\r\n    <span class=\"legend-text\" id=\"statisticsRange9\"></span>\r\n  </span>\r\n    <span class=\"echarts__legend\">\r\n    <span class=\"color-block green\"></span>\r\n    <span class=\"legend-text\" id=\"prevRange20\"></span>\r\n  </span>\r\n    <span class=\"echarts__legend\">\r\n    <span class=\"color-block blue\"></span>\r\n    <span class=\"legend-text\" id=\"currentRange20\"></span>\r\n  </span>\r\n</div>\r\n<div class=\"echarts__title\">图13 省内访问省外${Provider}各链路Top5 省份流量占比</div>\r\n\r\n<div class=\"echarts-box indent-3\">\r\n    <div class=\"echarts\">\r\n        <div class=\"echarts__canvas echarts__sankey\" id=\"canvas55\"></div>\r\n    </div>\r\n</div>\r\n<div class=\"echarts__title\">图14 省外访问省内${Provider}会话的流量流向图</div>\r\n<div class=\"table-box indent-3\">\r\n    <table class=\"table table-contain-echarts\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th></th>\r\n            <th class=\"table__th\">西宁</th>\r\n            <th class=\"table__th\">太原</th>\r\n            <th class=\"table__th\">西安</th>\r\n        </tr>\r\n        </thead>\r\n        <tbody>\r\n        <tr class=\"table__tr\">\r\n            <td class=\"table__td table__td-up\">上行链路</td>\r\n            <td class=\"table__td\">\r\n                <div class=\"echarts-box\">\r\n                    <div class=\"echarts\">\r\n                        <div class=\"echarts__canvas echarts__td-bar\" id=\"canvas62\"></div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n            <td class=\"table__td\">\r\n                <div class=\"echarts-box\">\r\n                    <div class=\"echarts\">\r\n                        <div class=\"echarts__canvas echarts__td-bar\" id=\"canvas63\" ></div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n            <td class=\"table__td\">\r\n                <div class=\"echarts-box\">\r\n                    <div class=\"echarts\">\r\n                        <div class=\"echarts__canvas echarts__td-bar\" id=\"canvas64\"></div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n        </tr>\r\n        <tr class=\"table__tr\">\r\n            <td class=\"table__td table__td-down\">下行链路</td>\r\n            <td class=\"table__td echarts__td-bar\">\r\n                <div class=\"echarts-box\">\r\n                    <div class=\"echarts\">\r\n                        <div class=\"echarts__canvas\" id=\"canvas65\"></div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n            <td class=\"table__td echarts__td-bar\">\r\n                <div class=\"echarts-box\">\r\n                    <div class=\"echarts\">\r\n                        <div class=\"echarts__canvas \" id=\"canvas66\"></div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n            <td class=\"table__td echarts__td-bar\">\r\n                <div class=\"echarts-box\">\r\n                    <div class=\"echarts\">\r\n                        <div class=\"echarts__canvas\" id=\"canvas67\"></div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n        </tr>\r\n        </tbody></table>\r\n</div>\r\n<div class=\"echarts__legends\">\r\n    <span class=\"echarts__legend\">\r\n    <span class=\"color-block light-green\"></span>\r\n    <span class=\"legend-text\" id=\"statisticsRange11\"></span>\r\n  </span>\r\n    <span class=\"echarts__legend\">\r\n    <span class=\"color-block green\"></span>\r\n    <span class=\"legend-text\" id=\"prevRange22\"></span>\r\n  </span>\r\n    <span class=\"echarts__legend\">\r\n    <span class=\"color-block blue\"></span>\r\n    <span class=\"legend-text\" id=\"currentRange22\"></span>\r\n  </span>\r\n</div>\r\n<div class=\"echarts__title\">图15 省外访问省内${Provider}各链路Top5 省份流量占比</div>\r\n\r\n<script>\r\n    /** 数据 begin */\r\n        // 时间区间\r\n    var timeRange = [${startTime}, ${endTime}]\r\n    // 时区偏移毫秒\r\n    var timeZoneOffset = ${timeZoneOffset}\r\n    /* 1.1 流量变化曲线 */\r\n    // 总流量\r\n    var trafficTotal = ${jsGetNumFromArr(trafficTotal,0,\'bytes\')/1024}\r\n    // xxx服务总流量 (xxxService traffic total)\r\n    var xxxServiceTrafficTotal = ${jsGetNumFromArr(xxxServiceTrafficTotal,0,\'bytes\')/1024}\r\n    // 前一周期(Pre 1st xxxService traffic total)\r\n    var pre1stxxxServiceTrafficTotal = ${jsGetNumFromArr(pre1stxxxServiceTrafficTotal,0,\'bytes\')/1024}\r\n    // 前二周期(Pre 2st xxxService traffic total)\r\n    var pre2ndxxxServiceTrafficTotal = ${jsGetNumFromArr(pre2ndxxxServiceTrafficTotal,0,\'bytes\')/1024}\r\n    // 省外访问省内服${Provider}的服务质量\r\n    var xxxServiceOut2inTrafficTotal = {\r\n        bytes_sent: ${jsGetNumFromArr(xxxServiceOut2inTrafficTotal,0,\'bytes_sent\')/1024},\r\n        bytes_received: ${jsGetNumFromArr(xxxServiceOut2inTrafficTotal,0,\'bytes_received\')/1024},\r\n        bytes: ${jsGetNumFromArr(xxxServiceOut2inTrafficTotal,0,\'bytes\')/1024}\r\n    }\r\n    // 前一周期(Pre 1st xxxService ZA traffic total)\r\n    var Pre1stxxxServiceOut2inTrafficTotal = {\r\n        bytes_sent: ${jsGetNumFromArr(Pre1stxxxServiceOut2inTrafficTotal,0,\'bytes_sent\')/1024},\r\n        bytes_received: ${jsGetNumFromArr(Pre1stxxxServiceOut2inTrafficTotal,0,\'bytes_received\')/1024},\r\n        bytes: ${jsGetNumFromArr(Pre1stxxxServiceOut2inTrafficTotal,0,\'bytes\')/1024}\r\n    }\r\n    // 前二周期(Pre 2nd xxxService ZA traffic total)\r\n    var Pre2ndxxxServiceOut2inTrafficTotal = {\r\n        bytes_sent: ${jsGetNumFromArr(Pre2ndxxxServiceOut2inTrafficTotal,0,\'bytes_sent\')/1024},\r\n        bytes_received: ${jsGetNumFromArr(Pre2ndxxxServiceOut2inTrafficTotal,0,\'bytes_received\')/1024},\r\n        bytes: ${jsGetNumFromArr(Pre2ndxxxServiceOut2inTrafficTotal,0,\'bytes\')/1024}\r\n    }\r\n    // 省内访问省外${Provider}服务流量\r\n    var xxxServiceIn2outTrafficTotal = {\r\n        bytes_sent: ${jsGetNumFromArr(xxxServiceIn2outTrafficTotal,0,\'bytes_sent\')/1024},\r\n        bytes_received: ${jsGetNumFromArr(xxxServiceIn2outTrafficTotal,0,\'bytes_received\')/1024},\r\n        bytes: ${jsGetNumFromArr(xxxServiceIn2outTrafficTotal,0,\'bytes\')/1024}\r\n    }\r\n    var pre1stxxxServiceIn2outTrafficTotal = {\r\n        bytes_sent: ${jsGetNumFromArr(pre1stxxxServiceIn2outTrafficTotal,0,\'bytes_sent\')/1024},\r\n        bytes_received: ${jsGetNumFromArr(pre1stxxxServiceIn2outTrafficTotal,0,\'bytes_received\')/1024},\r\n        bytes: ${jsGetNumFromArr(pre1stxxxServiceIn2outTrafficTotal,0,\'bytes\')/1024}\r\n    }\r\n    var pre2ndxxxServiceIn2outTrafficTotal = {\r\n        bytes_sent: ${jsGetNumFromArr(pre2ndxxxServiceIn2outTrafficTotal,0,\'bytes_sent\')/1024},\r\n        bytes_received: ${jsGetNumFromArr(pre2ndxxxServiceIn2outTrafficTotal,0,\'bytes_received\')/1024},\r\n        bytes: ${jsGetNumFromArr(pre2ndxxxServiceIn2outTrafficTotal,0,\'bytes\')/1024}\r\n    }\r\n    // ${Provider}服务速率\r\n    var xxxServiceRate = {\r\n        rate50: ${jsGetNumFromArr(xxxServiceRate,0,\'rate50\')/1000},\r\n        rate90: ${jsGetNumFromArr(xxxServiceRate,0,\'rate90\')/1000},\r\n        rate99: ${jsGetNumFromArr(xxxServiceRate,0,\'rate99\')/1000},\r\n        rate_avg:${jsGetNumFromArr(xxxServiceRate,0,\'rate_avg\')/1000},\r\n        rate_max:${jsGetNumFromArr(xxxServiceRate,0,\'rate_max\')/1000},\r\n        rate_min:${jsGetNumFromArr(xxxServiceRate,0,\'rate_min\')/1000}\r\n    }\r\n    var pre1stxxxServiceRate = {\r\n        rate50: ${jsGetNumFromArr(pre1stxxxServiceRate,0,\'rate50\')/1000},\r\n        rate90: ${jsGetNumFromArr(pre1stxxxServiceRate,0,\'rate90\')/1000},\r\n        rate99: ${jsGetNumFromArr(pre1stxxxServiceRate,0,\'rate99\')/1000},\r\n        rate_avg:${jsGetNumFromArr(pre1stxxxServiceRate,0,\'rate_avg\')/1000},\r\n        rate_max:${jsGetNumFromArr(pre1stxxxServiceRate,0,\'rate_max\')/1000},\r\n        rate_min:${jsGetNumFromArr(pre1stxxxServiceRate,0,\'rate_min\')/1000}\r\n    }\r\n    var pre2ndxxxServiceRate = {\r\n        rate50: ${jsGetNumFromArr(pre2ndxxxServiceRate,0,\'rate50\')/1000},\r\n        rate90: ${jsGetNumFromArr(pre2ndxxxServiceRate,0,\'rate90\')/1000},\r\n        rate99: ${jsGetNumFromArr(pre2ndxxxServiceRate,0,\'rate99\')/1000},\r\n        rate_avg:${jsGetNumFromArr(pre2ndxxxServiceRate,0,\'rate_avg\')/1000},\r\n        rate_max:${jsGetNumFromArr(pre2ndxxxServiceRate,0,\'rate_max\')/1000},\r\n        rate_min:${jsGetNumFromArr(pre2ndxxxServiceRate,0,\'rate_min\')/1000}\r\n    }\r\n    // ${Provider}服务当日流量变化曲线\r\n    var xxxServiceTrafficChangingCurve = [\r\n        <#if xxxServiceTrafficChangingCurve??>\r\n        <#list xxxServiceTrafficChangingCurve as d>\r\n        {stat_time:${jsGetNumFromObj(d,\'stat_time\') * 1000},rate:${jsGetNumFromObj(d,\'rate\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n\r\n    // 1.2 服务质量情况\r\n    // 省外访问省内${Provider}服务的服务质量\r\n    // TCP会话创建延迟(xxxService Out2in TCP)\r\n    var xxxServiceOut2inTcp = {\r\n        establish_latency_p50: ${jsGetNumFromArr(xxxServiceOut2inTcp,0,\'establish_latency_p50\')},\r\n        establish_latency_p90: ${jsGetNumFromArr(xxxServiceOut2inTcp,0,\'establish_latency_p90\')},\r\n        establish_latency_p99: ${jsGetNumFromArr(xxxServiceOut2inTcp,0,\'establish_latency_p99\')},\r\n        establish_latency_avg:${jsGetNumFromArr(xxxServiceOut2inTcp,0,\'establish_latency_avg\')},\r\n        establish_latency_max:${jsGetNumFromArr(xxxServiceOut2inTcp,0,\'establish_latency_max\')},\r\n        establish_latency_min:${jsGetNumFromArr(xxxServiceOut2inTcp,0,\'establish_latency_min\')}\r\n    }\r\n    // 上周期(Pre 1st xxxService Out2in TCP)\r\n    var pre1stxxxServiceOut2inTcp = {\r\n        establish_latency_p50: ${jsGetNumFromArr(pre1stxxxServiceOut2inTcp,0,\'establish_latency_p50\')},\r\n        establish_latency_p90: ${jsGetNumFromArr(pre1stxxxServiceOut2inTcp,0,\'establish_latency_p90\')},\r\n        establish_latency_p99: ${jsGetNumFromArr(pre1stxxxServiceOut2inTcp,0,\'establish_latency_p99\')},\r\n        establish_latency_avg:${jsGetNumFromArr(pre1stxxxServiceOut2inTcp,0,\'establish_latency_avg\')},\r\n        establish_latency_max:${jsGetNumFromArr(pre1stxxxServiceOut2inTcp,0,\'establish_latency_max\')},\r\n        establish_latency_min:${jsGetNumFromArr(pre1stxxxServiceOut2inTcp,0,\'establish_latency_min\')}\r\n    }\r\n    // 丢包率(xxxService Out2in loss packets)\r\n    var xxxServiceOut2inLossPackets = {\r\n        sequence_gap_loss_p50: ${jsGetNumFromArr(xxxServiceOut2inLossPackets,0,\'establish_latency_p50\')},\r\n        sequence_gap_loss_p90: ${jsGetNumFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_p90\')},\r\n        sequence_gap_loss_p99: ${jsGetNumFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_p99\')},\r\n        sequence_gap_loss_avg:${jsGetNumFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_avg\')},\r\n        sequence_gap_loss_max:${jsGetNumFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_max\')},\r\n        sequence_gap_loss_min:${jsGetNumFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_min\')}\r\n    }\r\n    // 上周期(Pre 1st xxxService Out2in loss packets)\r\n    var pre1stxxxServiceOut2inLossPackets = {\r\n        sequence_gap_loss_p50: ${jsGetNumFromArr(pre1stxxxServiceOut2inLossPackets,0,\'sequence_gap_loss_p50\')},\r\n        sequence_gap_loss_p90: ${jsGetNumFromArr(pre1stxxxServiceOut2inLossPackets,0,\'sequence_gap_loss_p90\')},\r\n        sequence_gap_loss_p99: ${jsGetNumFromArr(pre1stxxxServiceOut2inLossPackets,0,\'sequence_gap_loss_p99\')},\r\n        sequence_gap_loss_avg:${jsGetNumFromArr(pre1stxxxServiceOut2inLossPackets,0,\'sequence_gap_loss_avg\')},\r\n        sequence_gap_loss_max:${jsGetNumFromArr(pre1stxxxServiceOut2inLossPackets,0,\'sequence_gap_loss_max\')},\r\n        sequence_gap_loss_min:${jsGetNumFromArr(pre1stxxxServiceOut2inLossPackets,0,\'sequence_gap_loss_min\')}\r\n    }\r\n    // 省内访问省外${Provider}的服务质量\r\n    // TCP会话创建延迟(xxxService In2out TCP)\r\n    var xxxServiceIn2outTcp = {\r\n        establish_latency_p50: ${jsGetNumFromArr(xxxServiceIn2outTcp,0,\'establish_latency_p50\')},\r\n        establish_latency_p90: ${jsGetNumFromArr(xxxServiceIn2outTcp,0,\'establish_latency_p90\')},\r\n        establish_latency_p99: ${jsGetNumFromArr(xxxServiceIn2outTcp,0,\'establish_latency_p99\')},\r\n        establish_latency_avg:${jsGetNumFromArr(xxxServiceIn2outTcp,0,\'establish_latency_avg\')},\r\n        establish_latency_max:${jsGetNumFromArr(xxxServiceIn2outTcp,0,\'establish_latency_max\')},\r\n        establish_latency_min:${jsGetNumFromArr(xxxServiceIn2outTcp,0,\'establish_latency_min\')}\r\n    }\r\n    // 上周期(Pre 1st xxxService In2out TCP)\r\n    var pre1stxxxServiceIn2outTcp = {\r\n        establish_latency_p50: ${jsGetNumFromArr(pre1stxxxServiceIn2outTcp,0,\'establish_latency_p50\')},\r\n        establish_latency_p90: ${jsGetNumFromArr(pre1stxxxServiceIn2outTcp,0,\'establish_latency_p90\')},\r\n        establish_latency_p99: ${jsGetNumFromArr(pre1stxxxServiceIn2outTcp,0,\'establish_latency_p99\')},\r\n        establish_latency_avg:${jsGetNumFromArr(pre1stxxxServiceIn2outTcp,0,\'establish_latency_avg\')},\r\n        establish_latency_max:${jsGetNumFromArr(pre1stxxxServiceIn2outTcp,0,\'establish_latency_max\')},\r\n        establish_latency_min:${jsGetNumFromArr(pre1stxxxServiceIn2outTcp,0,\'establish_latency_min\')}\r\n    }\r\n    // 丢包率(xxxService In2out loss packets)\r\n    var xxxServiceIn2outLossPackets = {\r\n        sequence_gap_loss_p50: ${jsGetNumFromArr(xxxServiceIn2outLossPackets,0,\'sequence_gap_loss_p50\')},\r\n        sequence_gap_loss_p90: ${jsGetNumFromArr(xxxServiceIn2outLossPackets,0,\'seque