n        }\r\n        var myChart = initEchartsInstance(\'canvas18\')\r\n        var option = deepClone(pieOption)\r\n        option.series[0].data = pieDomainData18\r\n        myChart.setOption(option)\r\n    }\r\n\r\n    var sankeyOption = {\r\n        animation: false,\r\n        series: [\r\n            {\r\n                type: \'sankey\',\r\n                layout: \'none\',\r\n                emphasis: {\r\n                    disabled: true\r\n                },\r\n                lineStyle: {\r\n                    color: \'gradient\',\r\n                    curveness: 0.5\r\n                }\r\n            }\r\n        ]\r\n    }\r\n    var barOption = {\r\n        animation: false,\r\n        color: [chartColor[12], chartColor[6], chartColor[1]],\r\n        grid: {\r\n            top: 30,\r\n            bottom: 35,\r\n            right: 20,\r\n            left: 70\r\n        },\r\n        xAxis: {\r\n            type: \'category\',\r\n            axisLabel: {\r\n                interval: 0,\r\n                rotate: 20,\r\n                fontSize: 12\r\n            }\r\n        },\r\n        yAxis: {\r\n            type: \'value\',\r\n            axisLabel: {\r\n                formatter (value) {\r\n                    return unitConvert(value, unitTypes.percent).join(\'\')\r\n                }\r\n            }\r\n        },\r\n        series: [\r\n            {\r\n                type: \'bar\',\r\n                barWidth: 10,\r\n                barMinHeight: 2\r\n            },\r\n            {\r\n                type: \'bar\',\r\n                barWidth: 10,\r\n                barMinHeight: 2\r\n            },\r\n            {\r\n                type: \'bar\',\r\n                barWidth: 10,\r\n                barMinHeight: 2\r\n            }\r\n        ]\r\n    }\r\n    // 省内访问省外\r\n    function initEcharts42 () {\r\n        var Data42 = []\r\n        var Links42 = []\r\n        linkDirectionTrafficIn2Out.forEach(b => {\r\n            if (b.egress_link_direction) {\r\n                b.egress_link_direction = \'上行\' + b.egress_link_direction\r\n            }\r\n            if (b.ingress_link_direction) {\r\n                b.ingress_link_direction = \'下行\' + b.ingress_link_direction\r\n            }\r\n            Data42.push(b.egress_link_direction, b.ingress_link_direction)\r\n        })\r\n        Links42 = linkDirectionTrafficIn2Out.map((d, i) => {\r\n            return {\r\n                source: d.egress_link_direction,\r\n                target: d.ingress_link_direction,\r\n                value: d.bytes\r\n            }\r\n        })\r\n        Data42 = Array.from(new Set(Data42))\r\n        Data42 = Data42.map((d, i) => {\r\n            return {\r\n                name: d,\r\n                itemStyle: {\r\n                    color: directionChartColor[i],\r\n                    borderColor: directionChartColor[i]\r\n                }\r\n            }\r\n        })\r\n        var myChart = initEchartsInstance(\'canvas42\')\r\n        sankeyOption.series[0].data = Data42\r\n        sankeyOption.series[0].links = Links42\r\n        myChart.setOption(sankeyOption)\r\n    }\r\n    // 上行链路 TOP5省份流量占比\r\n    function initEcharts49 () {\r\n        var province49 = linkEgressTrafficIn2Out.find(t => t.egress_link_direction === \'西宁\')\r\n        var { seriesData, prevSeriesData, pprevSeriesData, categoryData } = barDataFormatHandling(province49, pre1stLinkEgressTrafficIn2Out, pre2ndLinkEgressTrafficIn2Out, linkEgressTrafficTopNProvinceIn2OutXN, pre1stLinkEgressTrafficTopNProvinceIn2OutXN, pre2ndLinkEgressTrafficTopNProvinceIn2OutXN, \'egress_link_direction\', \'server_province\', \'egress_bytes\')\r\n        var myChart = initEchartsInstance(\'canvas49\')\r\n        barOption.xAxis.data = categoryData\r\n        barOption.series[2].data = seriesData\r\n        barOption.series[1].data = prevSeriesData\r\n        barOption.series[0].data = pprevSeriesData\r\n        myChart.setOption(barOption)\r\n    }\