\n      \"querySql\": \"SELECT IFNULL(ROUND(QUANTILE(rate, 0.5), 4), 0) AS rate50, IFNULL(ROUND(QUANTILE(rate, 0.9), 4), 0) AS rate90, IFNULL(ROUND(QUANTILE(rate, 0.99), 4), 0) AS rate99, IFNULL(ROUND(AVG(rate), 4), 0) AS rate_avg, IFNULL(ROUND(max(rate), 4), 0) AS rate_max, IFNULL(ROUND(min(rate), 4), 0) AS rate_min FROM ( SELECT SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes, (bytes * 8) / 300  AS rate, toDateTime(toStartOfInterval(toDateTime(common_recv_time), INTERVAL 5 MINUTE)) AS granularity FROM session_record_cn WHERE common_recv_time >= ${startTime} - ${timeDiff} AND common_recv_time < ${endTime} - ${timeDiff} AND (app_company IN (\'${Provider}\')) GROUP BY granularity)\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"pre1stxxxServiceRate\"\r\n    },\r\n    {\r\n      \"querySql\": \"SELECT IFNULL(ROUND(QUANTILE(rate, 0.5), 4), 0) AS rate50, IFNULL(ROUND(QUANTILE(rate, 0.9), 4), 0) AS rate90, IFNULL(ROUND(QUANTILE(rate, 0.99), 4), 0) AS rate99, IFNULL(ROUND(AVG(rate), 4), 0) AS rate_avg, IFNULL(ROUND(max(rate), 4), 0) AS rate_max, IFNULL(ROUND(min(rate), 4), 0) AS rate_min FROM ( SELECT SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes, (bytes * 8) / 300  AS rate, toDateTime(toStartOfInterval(toDateTime(common_recv_time), INTERVAL 5 MINUTE)) AS granularity FROM session_record_cn WHERE common_recv_time >= ${startTime} - 2*${timeDiff} AND common_recv_time < ${endTime} - 2*${timeDiff} AND (app_company IN (\'${Provider}\')) GROUP BY granularity)\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"pre2ndxxxServiceRate\"\r\n    },\r\n    {\r\n      \"querySql\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT5M\',\'zero\') AS stat_time, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes, ROUND(bytes * 8/300) AS rate FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND (app_company IN (\'${Provider}\')) GROUP BY stat_time ORDER BY stat_time ASC\",\r\n      \"t