   <#if pre1stLinkIngressTrafficTopNAppOut2InXA??>\r\n        <#list pre1stLinkIngressTrafficTopNAppOut2InXA as d>\r\n        {\r\n            ingress_link_direction:\'${getFromObj(d,\'ingress_link_direction\',\'string\')}\',\r\n            app_company:\'${getFromObj(d,\'app_company\',\'string\')}\',\r\n            ingress_bytes:${jsGetNumFromObj(d,\'ingress_bytes\')/1024},\r\n            sessions:${jsGetNumFromObj(d,\'sessions\')}\r\n        },\r\n        </#list>\r\n        </#if>\r\n    ]\r\n\r\n    // 2.2.7.6 下行链路TopN APP-上上周期\r\n    var pre2ndLinkIngressTrafficTopNAppOut2InXA = [\r\n        <#if pre2ndLinkIngressTrafficTopNAppOut2InXA??>\r\n        <#list pre2ndLinkIngressTrafficTopNAppOut2InXA as d>\r\n        {\r\n            ingress_link_direction:\'${getFromObj(d,\'ingress_link_direction\',\'string\')}\',\r\n            app_company:\'${getFromObj(d,\'app_company\',\'string\')}\',\r\n            ingress_bytes:${jsGetNumFromObj(d,\'ingress_bytes\')/1024},\r\n            sessions:${jsGetNumFromObj(d,\'sessions\')}\r\n        },\r\n        </#list>\r\n        </#if>\r\n    ]\r\n\r\n    // 2.2.8 西安链路TopN 省份统计\r\n    // 2.2.8.1 上行链路TopN Province-本周期\r\n    var linkEgressTrafficTopNProvinceOut2InXA = [\r\n        <#if linkEgressTrafficTopNProvinceOut2InXA??>\r\n        <#list linkEgressTrafficTopNProvinceOut2InXA as d>\r\n        {\r\n            egress_link_direction:\'${getFromObj(d,\'egress_link_direction\',\'string\')}\',\r\n            client_province:\'${getFromObj(d,\'client_province\',\'string\')}\',\r\n            egress_bytes:${jsGetNumFromObj(d,\'egress_bytes\')/1024},\r\n            sessions:${jsGetNumFromObj(d,\'sessions\')}\r\n        },\r\n        </#list>\r\n        </#if>\r\n    ]\r\n\r\n    // 2.2.8.2 上行链路TopNProvince-上周期\r\n    var pre1stLinkEgressTrafficTopNProvinceOut2InXA = [\r\n        <#if pre1stLinkEgressTrafficTopNProvinceOut2InXA??>\r\n        <#list pre1stLinkEgressTrafficTopNProvinceOut2InXA as d>\r\n        {\r\n            egress_link_direction:\'${getFromObj(d,\'egress_link_direction\',\'string\')}\',\r\n            client_province:\'${getFromObj(d,\'client_province\',\'string\')}\',\r\n            egress_bytes:${jsGetNumFromObj(d,\'egress_bytes\')/1024},\r\n            sessions:${jsGetNumFromObj(d,\'sessions\')}\r\n        },\r\n        </#list>\r\n        </#if>\r\n    ]\r\n\r\n    // 2.2.8.3 上行链路TopNProvince-上上周期\r\n    var pre2ndLinkEgressTrafficTopNProvinceOut2InXA = [\r\n        <#if pre2ndLinkEgressTrafficTopNProvinceOut2InXA??>\r\n        <#list pre2ndLinkEgressTrafficTopNProvinceOut2InXA as d>\r\n        {\r\n            egress_link_direction:\'${getFromObj(d,\'egress_link_direction\',\'string\')}\',\r\n            client_province:\'${getFromObj(d,\'client_province\',\'string\')}\',\r\n            egress_bytes:${jsGetNumFromObj(d,\'egress_bytes\')/1024},\r\n            sessions:${jsGetNumFromObj(d,\'sessions\')}\r\n        },\r\n        </#list>\r\n        </#if>\r\n    ]\r\n\r\n    // 2.2.8.4 下行链路TopN Province-本周期\r\n    var linkIngressTrafficTopNProvinceOut2InXA = [\r\n        <#if linkIngressTrafficTopNProvinceOut2InXA??>\r\n        <#list linkIngressTrafficTopNProvinceOut2InXA as d>\r\n        {\r\n            ingress_link_direction:\'${getFromObj(d,\'ingress_link_direction\',\'string\')}\',\r\n            client_province:\'${getFromObj(d,\'client_province\',\'string\')}\',\r\n            ingress_bytes:${jsGetNumFromObj(d,\'ingress_bytes\')/1024},\r\n            sessions:${jsGetNumFromObj(d,\'sessions\')}\r\n        },\r\n        </#list>\r\n        </#if>\r\n    ]\r\n\r\n    // 2.2.8.5 下行链路TopNProvince-上周期\r\n    var pre1stLinkIngressTrafficTopNProvinceOut2InXA = [\r\n        <#if pre1stLinkIngressTrafficTopNProvinceOut2InXA??>\r\n        <#list pre1stLinkIngressTrafficTopNProvinceOut2InXA as d>\r\n        {\r\n            ingress_link_direction:\'${getFromObj(d,\'ingress_link_direction\',\'string\')}\',\r\n            client_province:\'${getFromObj(d,\'client_province\',\'string\')}\',\r\n            ingress_bytes:${jsGetNumFromObj(d,\'ingress_bytes\')/1024},\r\n            sessions:${jsGetNumFromObj(d,\'sessions\')}\r\n        },\r\n        </#list>\r\n        </#if>\r\n    ]\r\n\r\n    // 2.2.8.6 下行链路TopNProvince-上上周期\r\n    var pre2ndLinkIngressTrafficTopNProvinceOut2InXA = [\r\n        <#if pre2ndLinkIngressTrafficTopNProvinceOut2InXA??>\r\n        <#list pre2ndLinkIngressTrafficTopNProvinceOut2InXA as d>\r\n        {\r\n            ingress_link_direction:\'${getFromObj(d,\'ingress_link_direction\',\'string\')}\',\r\n            client_province:\'${getFromObj(d,\'client_province\',\'string\')}\',\r\n            ingress_bytes:${jsGetNumFromObj(d,\'ingress_bytes\')/1024},\r\n            sessions:${jsGetNumFromObj(d,\'sessions\')}\r\n        },\r\n        </#list>\r\n        </#if>\r\n    ]\r\n\r\n\r\n    /** 数据 end */\r\n\r\n\r\n    ${reportJsCommon}\r\n\r\n\r\n    if (!isNaN(parseInt(timeZoneOffset))) {\r\n        var explorerTimeOffset = new Date().getTimezoneOffset() * 60 * 1000\r\n        trafficRateTrend = trafficRateTrend.map(d => ({ rate: d.rate, stat_time: d.stat_time + explorerTimeOffset + timeZoneOffset}))\r\n        timeRange = [timeRange[0] + explorerTimeOffset / 1000 + timeZoneOffset / 1000, timeRange[1] + explorerTimeOffset / 1000 + timeZoneOffset / 1000]\r\n    }\r\n    // 计算出前三个周期的时间戳范围，填充时间\r\n    function initTimeRange () {\r\n        var timeOffset = timeRange[1] - timeRange[0]\r\n        var wholeTimeOffset = [60 * 60 - 1, 60 * 60 * 24 - 1, 60 * 60 * 24 * 7 - 1]\r\n        if (wholeTimeOffset.indexOf(timeOffset) > -1) {\r\n            timeOffset++\r\n        }\r\n        var prevTimeRange = [timeRange[0] - timeOffset, timeRange[1] - timeOffset]\r\n        var pprevTimeRange = [prevTimeRange[0] - timeOffset, prevTimeRange[1] - timeOffset]\r\n        var ppprevTimeRange = [pprevTimeRange[0] - timeOffset, pprevTimeRange[1] - timeOffset]\r\n        var statisticTimeRange = [prevTimeRange[0] - timeOffset, prevTimeRange[1] - timeOffset]\r\n\r\n        var currentRanges = [\r\n            \'currentRange0\',\r\n            \'currentRange1\',\r\n            \'currentRange2\',\r\n            \'currentRange3\',\r\n            \'currentRange4\',\r\n            \'currentRange9\',\r\n            \'currentRange10\',\r\n            \'currentRange17\',\r\n            \'currentRange18\',\r\n            \'currentRange19\',\r\n            \'currentRange20\',\r\n            \'currentRange21\',\r\n            \'currentRange22\'\r\n        ]\r\n        var statisticsRanges = [\r\n            \'statisticsRange0\',\r\n            \'statisticsRange1\',\r\n            \'statisticsRange2\',\r\n            \'statisticsRange3\',\r\n            \'statisticsRange4\',\r\n            \'statisticsRange5\',\r\n            \'statisticsRange6\',\r\n            \'statisticsRange7\',\r\n            \'statisticsRange8\',\r\n            \'statisticsRange9\',\r\n            \'statisticsRange10\',\r\n            \'statisticsRange11\'\r\n        ]\r\n        var prevRanges = [\r\n            \'prevRange0\',\r\n            \'prevRange1\',\r\n            \'prevRange2\',\r\n            \'prevRange3\',\r\n            \'prevRange4\',\r\n            \'prevRange9\',\r\n            \'prevRange10\',\r\n            \'prevRange17\',\r\n            \'prevRange18\',\r\n            \'prevRange19\',\r\n            \'prevRange20\',\r\n            \'prevRange21\',\r\n            \'prevRange22\'\r\n        ]\r\n\r\n        var currentRangeStr = \'\'\r\n        var prevRangeStr = \'\'\r\n        var statisticsStr = \'\'\r\n        if (isWholeDay(timeRange)) {\r\n            currentRangeStr = timestampToStr(timeRange[0]).substring(0, 10)\r\n            prevRangeStr = timestampToStr(prevTimeRange[0]).substring(0, 10)\r\n            statisticsStr = timestampToStr(statisticTimeRange[0]).substring(0, 10)\r\n        } else {\r\n            currentRangeStr = timestampToStr(timeRange[0]) + \' -- \' + timestampToStr(timeRange[1])\r\n            prevRangeStr = timestampToStr(prevTimeRange[0]) + \' -- \' + timestampToStr(prevTimeRange[1])\r\n            statisticsStr = timestampToStr(statisticTimeRange[0]) + \' -- \' + timestampToStr(statisticTimeRange[1])\r\n        }\r\n        currentRanges.forEach(c => {\r\n            var dom = document.getElementById(c)\r\n            if (dom) {\r\n                dom.innerText = currentRangeStr\r\n            }\r\n        })\r\n        prevRanges.forEach(c => {\r\n            var dom = document.getElementById(c)\r\n            if (dom) {\r\n                dom.innerText = prevRangeStr\r\n            }\r\n        })\r\n        statisticsRanges.forEach(c => {\r\n            var dom = document.getElementById(c)\r\n            if (dom) {\r\n                dom.innerText = statisticsStr\r\n            }\r\n        })\r\n    }\r\n\r\n    // 1.2 流量变化曲线\r\n    function initEcharts1() {\r\n        var seriesData1 = trafficRateTrend.map(d =>  [d.stat_time, d.rate] )\r\n        var unit1 = \'Kbps\'\r\n\r\n        var myChart = initEchartsInstance(\'canvas1\')\r\n        var option = {\r\n            color: chartColor,\r\n            animation: false,\r\n            grid: {\r\n                left: 100,\r\n                right: 120,\r\n                bottom: 25,\r\n                top: 40\r\n            },\r\n            xAxis: {\r\n                type: \'time\',\r\n                splitNumber: 12\r\n            },\r\n            yAxis: {\r\n                splitLine: { show: false },\r\n                offset: 10,\r\n                axisLabel: {\r\n                    formatter (params) {\r\n                        return unitConvert(params, unitTypes.bps, unit1).join(\' \')\r\n                    }\r\n                }\r\n            },\r\n            series: {\r\n                type: \'line\',\r\n                symbol: \'none\',\r\n                data: seriesData1,\r\n                markLine: {\r\n                    silent: true,\r\n                    lineStyle: {\r\n                        color: \'rgb(153,153,153)\'\r\n                    },\r\n                    symbol: \'none\',\r\n                    label: {\r\n                        formatter (params) {\r\n                            var arr = unitConvert(params.value, unitTypes.bps, unit1).join(\' \')\r\n                            var desc = \'\'\r\n                            switch (params.dataIndex) {\r\n                                case 0: {\r\n                                    desc = \'P50\'\r\n                                    break\r\n                                }\r\n                                case 1: {\r\n                                    desc = \'P90\'\r\n                                    break\r\n                                }\r\n                                case 2: {\r\n                                    desc = \'P99\'\r\n                                    break\r\n                                }\r\n                                default: break\r\n                            }\r\n                            return arr + \' (\' + desc + \')\'\r\n                        }\r\n                    }\r\n                }\r\n            }\r\n        }\r\n        if (quantile1.rate99 > quantile1.rate90 && quantile1.rate90 > quantile1.rate50 && (quantile1.rate90 && quantile1.rate50 && quantile1.rate99) !== 0){\r\n            option.visualMap = {\r\n                show: false,\r\n                pieces: [\r\n                    {\r\n                        lte: quantile1.rate50,\r\n                        color: \'rgb(251,219,15)\'\r\n                    },\r\n                    {\r\n                        gt: quantile1.rate50,\r\n                        lte: quantile1.rate90,\r\n                        color: \'rgb(252,125,2)\'\r\n                    },\r\n                    {\r\n                        gt: quantile1.rate90,\r\n                        lte: quantile1.rate99,\r\n                        color: \'rgb(253,1,0)\'\r\n                    },\r\n                    {\r\n                        gt: quantile1.rate99,\r\n                        color: \'rgb(170,6,159)\'\r\n                    }\r\n                ],\r\n                outOfRange: {\r\n                    color: \'rgb(153,153,153)\'\r\n                }\r\n            }\r\n            option.series.markLine.data = [\r\n                {\r\n                    yAxis: quantile1.rate50\r\n                },\r\n                {\r\n                    yAxis: quantile1.rate90\r\n                },\r\n                {\r\n                    yAxis: quantile1.rate99\r\n                }\r\n            ]\r\n        }\r\n        myChart.setOption(option)\r\n    }\r\n\r\n    var barOption1 = {\r\n        animation: false,\r\n        grid: {\r\n            top: 50,\r\n            bottom: 25,\r\n            right: 40,\r\n            left: 70\r\n        },\r\n        legend: {\r\n            show: true,\r\n            top: \'top\',\r\n            left: \'left\'\r\n        },\r\n        xAxis: {\r\n            type: \'category\',\r\n            axisLabel: {\r\n                interval: 0,\r\n                fontSize: 12\r\n            }\r\n        },\r\n        yAxis: [\r\n            {\r\n                name: \'流量\',\r\n                nameTextStyle: {\r\n                    color: \'transparent\'\r\n                },\r\n                type: \'value\',\r\n                axisLabel: {\r\n                    formatter (value) {\r\n                        return unitConvert(value, unitTypes.byte, \'KB\').join(\'\')\r\n                    }\r\n                }\r\n            },\r\n            {\r\n                show: false,\r\n                name: \'环比\',\r\n                type: \'value\'\r\n            }\r\n        ],\r\n        series: [\r\n            {\r\n                name: \'请求流量\',\r\n                barMinHeight: 5,\r\n                type: \'bar\',\r\n                barWidth: 40,\r\n                label: {\r\n                    show: true,\r\n                    formatter: function (param) {\r\n                        return unitConvert(param.value, unitTypes.byte, \'KB\').join(\'\') + \'\\n\' + unitConvert(param.data.percent, unitTypes.percent).join(\'\')\r\n                    },\r\n                    distance: 3,\r\n                    color: barLineColor.bar1,\r\n                    position: \'top\',\r\n                    fontSize: 10\r\n                },\r\n                itemStyle: {\r\n                    color: barLineColor.bar1\r\n                }\r\n            },\r\n            {\r\n                yAxisIndex: 1,\r\n                name: \'本期vs上期\',\r\n                type: \'line\',\r\n                zlevel: 1,\r\n                label: {\r\n                    show: true,\r\n                    formatter: function (param) {\r\n                        return param.value.toFixed(2) + \'%\'\r\n                    },\r\n                    align: \'right\',\r\n                    position: \'top\',\r\n                    color: barLineColor.line1\r\n                },\r\n                lineStyle: {\r\n                    type: \'dashed\'\r\n                },\r\n                itemStyle: {\r\n                    color: barLineColor.line1\r\n                }\r\n            },\r\n            {\r\n                yAxisIndex: 1,\r\n                name: \'上期vs上上期\',\r\n                type: \'line\',\r\n                label: {\r\n                    show: true,\r\n                    formatter: function (param) {\r\n                        return param.value.toFixed(2) + \'%\'\r\n                    },\r\n                    align: \'left\',\r\n                    position: \'bottom\',\r\n                    color: barLineColor.line3\r\n                },\r\n                lineStyle: {\r\n                    type: \'dashed\'\r\n                },\r\n                itemStyle: {\r\n                    color: barLineColor.line3\r\n                }\r\n            }\r\n        ]\r\n    }\r\n    var barOption2 = {\r\n        animation: false,\r\n        grid: {\r\n            top: 50,\r\n            bottom: 25,\r\n            right: 40,\r\n            left: 70\r\n        },\r\n        legend: {\r\n            show: true,\r\n            top: \'top\',\r\n            left: \'left\'\r\n        },\r\n        xAxis: {\r\n            type: \'category\',\r\n            axisLabel: {\r\n                interval: 0,\r\n                fontSize: 12\r\n            }\r\n        },\r\n        yAxis: [\r\n            {\r\n                name: \'流量\',\r\n                nameTextStyle: {\r\n                    color: \'transparent\'\r\n                },\r\n                type: \'value\',\r\n                axisLabel: {\r\n                    formatter (value) {\r\n                        return unitConvert(value, unitTypes.byte, \'KB\').join(\'\')\r\n                    }\r\n                }\r\n            },\r\n            {\r\n                show: false,\r\n                name: \'环比\',\r\n                type: \'value\'\r\n            }\r\n        ],\r\n        series: [\r\n            {\r\n                name: \'响应流量\',\r\n                barMinHeight: 5,\r\n                type: \'bar\',\r\n                barWidth: 40,\r\n                label: {\r\n                    show: true,\r\n                    formatter: function (param) {\r\n                        return unitConvert(param.value, unitTypes.byte, \'KB\').join(\'\') + \'\\n\' + unitConvert(param.data.percent, unitTypes.percent).join(\'\')\r\n                    },\r\n                    distance: 3,\r\n                    color: barLineColor.bar2,\r\n                    position: \'top\',\r\n                    fontSize: 10\r\n                },\r\n                itemStyle: {\r\n                    color: barLineColor.bar2\r\n                }\r\n            },\r\n            {\r\n                yAxisIndex: 1,\r\n                name: \'本期vs上期\',\r\n                type: \'line\',\r\n                zlevel: 1,\r\n                label: {\r\n                    show: true,\r\n                    formatter: function (param) {\r\n                        return param.value.toFixed(2) + \'%\'\r\n                    },\r\n                    align: \'right\',\r\n                    position: \'top\',\r\n                    color: barLineColor.line2\r\n                },\r\n                lineStyle: {\r\n                    type: \'dashed\'\r\n                },\r\n                itemStyle: {\r\n                    color: barLineColor.line2\r\n                }\r\n            },\r\n            {\r\n                yAxisIndex: 1,\r\n                name: \'上期vs上上期\',\r\n                type: \'line\',\r\n                label: {\r\n                    show: true,\r\n                    formatter: function (param) {\r\n                        return param.value.toFixed(2) + \'%\'\r\n                    },\r\n                    align: \'left\',\r\n                    position: \'bottom\',\r\n                    color: barLineColor.line1\r\n                },\r\n                lineStyle: {\r\n                    type: \'dashed\'\r\n                },\r\n                itemStyle: {\r\n                    color: barLineColor.line1\r\n                }\r\n            }\r\n        ]\r\n    }\r\n\r\n    // 2.1 Top 10 App流量概况\r\n    function initEcharts2 () {\r\n        var categoryData2 = appCompanyTrafficTop10.map(t => t.app_company)\r\n        var barSeriesData2 = appCompanyTrafficTop10.map(t => {\r\n            if (!t.bytes) {\r\n                t.bytes = 0\r\n            }\r\n            return {\r\n                value: t.bytes,\r\n                percent: trafficSummary.bytes === 0 ? 0 : parseFloat(t.bytes) / trafficSummary.bytes\r\n            }\r\n        })\r\n        // 第一条线\r\n        var lineSeriesData1_2 = []\r\n        // 第二条线\r\n        var lineSeriesData2_2 = []\r\n        appCompanyTrafficTop10.forEach(t => {\r\n            var findData = appCompanyTrafficTop10Pre1st.find(pt => pt.app_company === t.app_company)\r\n            if (findData && findData.bytes) {\r\n                lineSeriesData1_2.push(findData.bytes === 0 ? 0 : parseFloat(((t.bytes - findData.bytes) / parseFloat(findData.bytes) * 100).toFixed(2)))\r\n                var findData2 = appCompanyTrafficTop10Pre2nd.find(ppt => findData.app_company === ppt.app_company)\r\n                if (findData2 && findData2.bytes) {\r\n                    lineSeriesData2_2.push(findData2.bytes === 0 ? 0 : parseFloat(((findData.bytes - findData2.bytes) / parseFloat(findData2.bytes) * 100).toFixed(2)))\r\n                } else {\r\n                    lineSeriesData2_2.push(0)\r\n                }\r\n            } else {\r\n                lineSeriesData1_2.push(0)\r\n                lineSeriesData2_2.push(0)\r\n            }\r\n        })\r\n        var copyLineSeriesData2 = [...lineSeriesData1_2, ...lineSeriesData2_2]\r\n        var copyBarSeriesData2 = [...barSeriesData2]\r\n        copyLineSeriesData2.sort((a, b) => a - b)\r\n        copyBarSeriesData2.sort((a, b) => a.value - b.value)\r\n        var barMax2 = copyBarSeriesData2.length > 0 ? copyBarSeriesData2[copyBarSeriesData2.length - 1].value : 50\r\n        var lineMin2 = copyLineSeriesData2[0] ? copyLineSeriesData2[0] : 0\r\n        var lineMax2 = copyLineSeriesData2.length > 0 ? copyLineSeriesData2[copyLineSeriesData2.length - 1] : 0\r\n        if (lineMin2 == 0 && lineMin2 == lineMax2) {\r\n            lineMin2 = -5\r\n            lineMax2 = 1\r\n        } else {\r\n            var tempLineMin2 = lineMin2\r\n            lineMin2 = lineMin2 - 2.5 * (lineMax2 - lineMin2)\r\n            lineMax2 = lineMax2 + 0.5 * (lineMax2 - tempLineMin2)\r\n        }\r\n\r\n\r\n        var myChart = initEchartsInstance(\'canvas2\')\r\n        var option = deepClone(barOption1)\r\n        option.xAxis.data = categoryData2\r\n        option.yAxis[0].max = barMax2 * 2\r\n        option.yAxis[1].min = 