SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes FROM session_record_cn WHERE common_recv_time >= ${startTime} - ${timeDiff} AND common_recv_time < ${endTime} - ${timeDiff} AND client_region IN (\'IDC\') AND server_region NOT IN (\'IDC\') AND (app_company IN (\'${Provider}\'))\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"pre1stxxxServiceIn2outTrafficTotal\"\r\n    },\r\n    {\r\n      \"querySql\": \"SELECT SUM(common_c2s_byte_num) AS bytes_sent, SUM(common_s2c_byte_num) AS bytes_received, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes FROM session_record_cn WHERE common_recv_time >= ${startTime} - 2*${timeDiff} AND common_recv_time < ${endTime} - 2*${timeDiff} AND client_region IN (\'IDC\') AND server_region NOT IN (\'IDC\') AND (app_company IN (\'${Provider}\'))\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"pre2ndxxxServiceIn2outTrafficTotal\"\r\n    },\r\n    {\r\n      \"querySql\": \"SELECT IFNULL(ROUND(QUANTILE(rate, 0.5), 4), 0) AS rate50, IFNULL(ROUND(QUANTILE(rate, 0.9), 4), 0) AS rate90, IFNULL(ROUND(QUANTILE(rate, 0.99), 4), 0) AS rate99, IFNULL(ROUND(AVG(rate), 4), 0) AS rate_avg, IFNULL(ROUND(max(rate), 4), 0) AS rate_max, IFNULL(ROUND(min(rate), 4), 0) AS rate_min FROM ( SELECT SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes, (bytes * 8) / 300 AS rate, toDateTime(toStartOfInterval(toDateTime(common_recv_time), INTERVAL 5 MINUTE)) AS granularity FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND (app_company IN (\'${Provider}\')) GROUP BY granularity)\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"xxxServiceRate\"\r\n    },\r\n\r\n    {\r\n      \"querySql\": \"SELECT IFNULL(ROUND(QUANTILE(rate, 0.5), 4), 0) AS rate50, IFNULL(ROUND(QUANTILE(rate, 0.9), 4), 0) AS rate90, IFNULL(ROUND(QUANTILE(rate, 0.99), 4), 0) AS rate99, IFNULL(ROUND(AVG(rate), 4), 0) AS rate_avg, IFNULL(ROUND(max(rate), 4), 0) AS rate_max, IFNULL(ROUND(min(rate), 4), 0) A