s[2].data = lineSeriesData2_5\r\n        myChart.setOption(option)\r\n    }\r\n\r\n    // 省外访问省内${overviewApp}服务 TOP 10 省内地区响应流量分布(Region Out2in Received Traffic Bytes Top 10)\r\n    function initEcharts11 () {\r\n        var categoryData11 = regionIn2idcReceivedTrafficBytesTop10.map(t => t.client_region)\r\n    	var barSeriesData11 = regionIn2idcReceivedTrafficBytesTop10.map(t => {\r\n            if (!t.bytes_received) {\r\n                t.bytes_received = 0\r\n            }\r\n            return {\r\n                value: t.bytes_received,\r\n                percent: xxxServiceIn2idctraffictotal.bytes_received === 0 ? 0 : parseFloat(t.bytes_received) / xxxServiceIn2idctraffictotal.bytes_received\r\n            }\r\n        })\r\n        // 第一条线\r\n        var lineSeriesData1_11 = []\r\n        // 第二条线\r\n        var lineSeriesData2_11 = []\r\n        regionIn2idcReceivedTrafficBytesTop10.forEach(t => {\r\n      		var findData = pre1stRegionIn2idcReceivedTrafficBytesTop10.find(pt => pt.client_region === t.client_region)\r\n            if (findData && findData.bytes_received) {\r\n                lineSeriesData1_11.push(findData.bytes_received === 0 ? 0 : parseFloat(((t.bytes_received - findData.bytes_received) / parseFloat(findData.bytes_received) * 100).toFixed(2)))\r\n				var findData2 = pre2ndRegionIn2idcReceivedTrafficBytesTop10.find(ppt => findData.client_region === ppt.client_region)\r\n                if (findData2 && findData2.bytes_received) {\r\n                    lineSeriesData2_11.push(findData2.bytes_received === 0 ? 0 : parseFloat(((findData.bytes_received - findData2.bytes_received) / parseFloat(findData2.bytes_received) * 100).toFixed(2)))\r\n                } else {\r\n                    lineSeriesData2_11.push(0)\r\n                }\r\n            } else {\r\n                lineSeriesData1_11.push(0)\r\n                lineSeriesData2_11.push(0)\r\n            }\r\n        })\r\n        var copyLineSeriesData11 = [...lineSeriesData1_11, ...lineSeriesData2_11]\r\n        var copyBarSeriesData11 = [...barSeriesData11]\r\n        copyLineSeriesData11.sort((a, b) => a - b)\r\n        copyBarSeriesData11.sort((a, b) => a.value - b.value)\r\n        var barMax11 = copyBarSeriesData11.length > 0 ? copyBarSeriesData11[copyBarSeriesData11.length - 1].value : 50\r\n        var lineMin11 = copyLineSeriesData11[0] ? copyLineSeriesData11[0] : 0\r\n        var lineMax11 = copyLineSeriesData11.length > 0 ? copyLineSeriesData11[copyLineSeriesData11.length - 1] : 0\r\n        if (lineMin11 == 0 && lineMin11 == lineMax11) {\r\n            lineMin11 = -5\r\n            lineMax11 = 1\r\n        } else {\r\n            var tempLineMin11 = lineMin11\r\n            lineMin11 = lineMin11 - 2.5 * (lineMax11 - lineMin11)\r\n            lineMax11 = lineMax11 + 0.5 * (lineMax11 - tempLineMin11)\r\n        }\r\n\r\n        var myChart = initEchartsInstance(\'canvas11\')\r\n        var option = deepClone(barOption2)\r\n        option.xAxis.data = categoryData11\r\n        option.yAxis[0].max = barMax11 * 2\r\n        option.yAxis[1].min = lineMin11\r\n        option.yAxis[1].max = lineMax11\r\n        option.series[0].data = barSeriesData11\r\n        option.series[1].data = lineSeriesData1_11\r\n        option.series[2].data = lineSeriesData2_11\r\n        myChart.setOption(option)\r\n    }\r\n\r\n\r\n    var pieOption = {\r\n        legend: {\r\n            show: false\r\n        },\r\n        title: {\r\n            show: true,\r\n            bottom: 0,\r\n            left: \'center\',\r\n            textStyle: {\r\n                fontSize: 14\r\n            }\r\n        },\r\n        color: chartColor,\r\n        animation: false,\r\n        series: [\r\n            {\r\n                type: \'pie\',\r\n                radius: [35, 60],\r\n                label: {\r\n                    formatter: \'{b} {d}%\',\r\n                    fontSize: 12,\r\n                },\r\n                center: [\'50%\', 145],\r\n                itemStyle: {\r\n                    borderWidth: 1,\r\n                    borderColor: \'white\'\r\n                }\r\n            }\r\n        ]\r\n    }\r\n\r\n    function initEcharts13 () {\r\n        var total13 = top10RelatedDomainBytes.find(b => b.domain === \'total\')\r\n        if (total13) {\r\n            var pieDomainData13 = []\r\n            var businessDistributionDomainData13 = top10RelatedDomainBytes.filter(t => t.domain !== \'total\')\r\n            var bytesAll = 0\r\n            pieDomainData13 = businessDistributionDomainData13.map(t => {\r\n                bytesAll += t.bytes\r\n                return {\r\n                    value: t.bytes === 0 ? 0 : t.bytes / total13.bytes,\r\n                    name: t.domain || \'null\'\r\n                }\r\n            })\r\n            pieDomainData13.push({ name: \'other\', value: (total13.bytes - bytesAll) / total13.bytes })\r\n        }\r\n        var myChart = initEchartsInstance(\'canvas13\')\r\n        var option = deepClone(pieOption)\r\n        option.series[0].data = pieDomainData13\r\n        myChart.setOption(option)\r\n    }\r\n    function initEcharts18 () {\r\n        var total18 = top10RelatedProtocolBytes.find(b => b.l7_protocol === \'total\')\r\n        if (total18) {\r\n            var pieDomainData18 = []\r\n            var businessDistributionDomainData18 = top10RelatedProtocolBytes.filter(t => t.l7_protocol !== \'total\')\r\n            var bytesAll = 0\r\n            pieDomainData18 = businessDistributionDomainData18.map(t => {\r\n                bytesAll += t.bytes\r\n                return {\r\n                    value: t.bytes === 0 ? 0 : t.bytes / total18.bytes,\r\n                    name: t.l7_protocol || \'null\'\r\n                }\r\n            })\r\n            pieDomainData18.push({ name: \'other\', value: (total18.bytes - bytesAll) / total18.bytes })\r\n        }\r\n        var myChart = initEchartsInstance(\'canvas18\')\r\n        var option = deepClone(pieOption)\r\n        option.series[0].data = pieDomainData18\r\n        myChart.setOption(option)\r\n    }\r\n\r\n    var sankeyOption = {\r\n        animation: false,\r\n        series: [\r\n            {\r\n                type: \'sankey\',\r\n                layout: \'none\',\r\n                emphasis: {\r\n                    disabled: true\r\n                },\r\n                lineStyle: {\r\n                    color: \'gradient\',\r\n                    curveness: 0.5\r\n                }\r\n            }\r\n        ]\r\n    }\r\n    var barOption = {\r\n        animation: false,\r\n        color: [chartColor[12], chartColor[6], chartColor[1]],\r\n        grid: {\r\n            top: 30,\r\n            bottom: 35,\r\n            right: 20,\r\n            left: 70\r\n        },\r\n        xAxis: {\r\n            type: \'category\',\r\n            axisLabel: {\r\n                interval: 0,\r\n                rotate: 20,\r\n                fontSize: 12\r\n            }\r\n        },\r\n        yAxis: {\r\n            type: \'value\',\r\n            axisLabel: {\r\n                formatter (value) {\r\n                    return unitConvert(value, unitTypes.percent).join(\'\')\r\n                }\r\n            }\r\n        },\r\n        series: [\r\n            {\r\n                type: \'bar\',\r\n                barWidth: 10,\r\n                barMinHeight: 2\r\n            },\r\n            {\r\n                type: \'bar\',\r\n                barWidth: 10,\r\n                barMinHeight: 2\r\n            },\r\n            {\r\n                type: \'bar\',\r\n                barWidth: 10,\r\n                barMinHeight: 2\r\n            }\r\n        ]\r\n    }\r\n\r\n    try { initEcharts1() } catch (e) { console.error(e) }\r\n    try { initEcharts2() } catch (e) { console.error(e) }\r\n    try { initEcharts3() } catch (e) { console.error(e) }\r\n    try { initEcharts4() } catch (e) { console.error(e) }\r\n    try { initEcharts5() } catch (e) { console.error(e) }\r\n    try { initEcharts8() } catch (e) { console.error(e) }\r\n    try { initEcharts9() } catch (e) { console.error(e) }\r\n    try { initEcharts10() } catch (e) { console.error(e) }\r\n    try { initEcharts11() } catch (e) { console.error(e) }\r\n    try { initEcharts13() } catch (e) { console.error(e) }\r\n    try { initEcharts18() } catch (e) { console.error(e) }\r\n    try { initTimeRange() } catch (e) { console.error(e) }\r\n</script>\r\n</body>\r\n\r\n</html>\r\n', '{\r\n  \"queryParam\":[{\r\n		\"key\":\"overviewApp\",\r\n		\"value\":\"\",\r\n		\"i18n\":\"report.overviewApp\"\r\n  }],\r\n  \"dataset\": [\r\n    {\r\n      \"querySql\": \"SELECT SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime}\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"trafficTotal\"\r\n    },\r\n    {\r\n      \"querySql\": \"SELECT SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND (common_app_label IN (\'${overviewApp}\'))\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"xxxServiceTrafficTotal\"\r\n    },\r\n    {\r\n      \"querySql\": \"SELECT SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes FROM session_record_cn WHERE common_recv_time >= ${startTime} - ${timeDiff} AND common_recv_time < ${endTime} - ${timeDiff} AND (common_app_label IN (\'${overviewApp}\'))\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"pre1stxxxServiceTrafficTotal\"\r\n    },\r\n    {\r\n      \"querySql\": \"SELECT SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes FROM session_record_cn WHERE common_recv_time >= ${startTime} - 2*${timeDiff} AND common_recv_time < ${endTime} - 2*${timeDiff} AND (common_app_label IN (\'${overviewApp}\'))\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"pre2ndxxxServiceTrafficTotal\"\r\n    },\r\n    {\r\n      \"querySql\": \"SELECT SUM(common_c2s_byte_num) AS bytes_sent, SUM(common_s2c_byte_num) AS bytes_received, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND client_region NOT IN (\'IDC\') AND server_region IN (\'IDC\') AND (common_app_label IN (\'${overviewApp}\'))\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"xxxServiceOut2inTrafficTotal\"\r\n    },\r\n    {\r\n      \"querySql\": \"SELECT SUM(common_c2s_byte_num) AS bytes_sent, SUM(common_s2c_byte_num) AS bytes_received, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes FROM session_record_cn WHERE common_recv_time >= ${startTime} - ${timeDiff} AND common_recv_time < ${endTime} - ${timeDiff} AND client_region NOT IN (\'IDC\') AND server_region IN (\'IDC\') AND (common_app_label IN (\'${overviewApp}\'))\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"Pre1stxxxServiceOut2inTrafficTotal\"\r\n    },\r\n    {\r\n      \"querySql\": \"SELECT SUM(common_c2s_byte_num) AS bytes_sent, SUM(common_s2c_byte_num) AS bytes_received, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes FROM session_record_cn WHERE common_recv_time >= ${startTime} - 2*${timeDiff} AND common_recv_time < ${endTime} - 2*${timeDiff} AND client_region NOT IN (\'IDC\') AND server_region IN (\'IDC\') AND (common_app_label IN (\'${overviewApp}\'))\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"Pre2ndxxxServiceOut2inTrafficTotal\"\r\n    },\r\n    {\r\n      \"querySql\": \"SELECT SUM(common_c2s_byte_num) AS bytes_sent, SUM(common_s2c_byte_num) AS bytes_received, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND client_region IN (\'IDC\') AND server_region NOT IN (\'IDC\') AND (common_app_label IN (\'${overviewApp}\'))\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"xxxServiceIn2outTrafficTotal\"\r\n    },\r\n    {\r\n      \"querySql\": \"SELECT SUM(common_c2s_byte_num) AS bytes_sent, SUM(common_s2c_byte_num) AS bytes_received, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes FROM session_record_cn WHERE common_recv_time >= ${startTime} - ${timeDiff} AND common_recv_time < ${endTime} - ${timeDiff} AND client_region IN (\'IDC\') AND server_region NOT IN (\'IDC\') AND (common_app_label IN (\'${overviewApp}\'))\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"pre1stxxxServiceIn2outTrafficTotal\"\r\n    },\r\n    {\r\n      \"querySql\": \"SELECT SUM(common_c2s_byte_num) AS bytes_sent, SUM(common_s2c_byte_num) AS bytes_received, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes FROM session_record_cn WHERE common_recv_time >= ${startTime} - 2*${timeDiff} AND common_recv_time < ${endTime} - 2*${timeDiff} AND client_region IN (\'IDC\') AND server_region NOT IN (\'IDC\') AND (common_app_label IN (\'${overviewApp}\'))\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"pre2ndxxxServiceIn2outTrafficTotal\"\r\n    },\r\n    {\r\n      \"querySql\": \"SELECT IFNULL(ROUND(QUANTILE(rate, 0.5), 4), 0) AS rate50, IFNULL(ROUND(QUANTILE(rate, 0.9), 4), 0) AS rate90, IFNULL(ROUND(QUANTILE(rate, 0.99), 4), 0) AS rate99, IFNULL(ROUND(AVG(rate), 4), 0) AS rate_avg, IFNULL(ROUND(max(rate), 4), 0) AS rate_max, IFNULL(ROUND(min(rate), 4), 0) AS rate_min FROM ( SELECT SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes, (bytes * 8) / 300 AS rate, toDateTime(toStartOfInterval(toDateTime(common_recv_time), INTERVAL 5 MINUTE)) AS granularity FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND (common_app_label IN (\'${overviewApp}\')) GROUP BY granularity)\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"xxxServiceRate\"\r\n    },\r\n\r\n    {\r\n      \"querySql\": \"SELECT IFNULL(ROUND(QUANTILE(rate, 0.5), 4), 0) AS rate50, IFNULL(ROUND(QUANTILE(rate, 0.9), 4), 0) AS r