iewApp}\')) GROUP BY server_region ORDER BY SUM(common_c2s_byte_num) DESC LIMIT 10 ) GROUP BY granularity, server_region) GROUP BY server_region ORDER BY bytes_sent DESC LIMIT 10\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"pre2ndRegionIdc2inSentTrafficBytesTop10\"\r\n    },\r\n    {\r\n      \"querySql\": \"SELECT server_region AS server_region, SUM(bytes_received) AS bytes_received, IFNULL(ROUND(AVG(received_rate), 4), 0) AS received_rate_avg, IFNULL(ROUND(MAX(received_rate), 4), 0) AS received_rate_max, IFNULL(ROUND(MIN(received_rate), 4), 0) AS received_rate_min FROM ( SELECT server_region AS server_region, SUM(common_s2c_byte_num) AS bytes_received, (bytes_received * 8) / (300) AS received_rate, toDateTime(toStartOfInterval(toDateTime(common_recv_time), INTERVAL 5 MINUTE)) AS granularity FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND (common_app_label IN (\'${overviewApp}\')) AND client_region IN (\'IDC\') AND server_region in ( SELECT server_region AS server_region FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND client_region  IN (\'IDC\') AND server_region IN (\'IPTV\', \'VBAS测试\', \'阿克苏\', \'阿勒泰\', \'巴州\', \'博州\', \'昌吉\', \'哈密\', \'和田\', \'喀什\', \'克拉玛依\', \'克州\', \'奎屯\', \'区公司\', \'石河子\',\'塔城\', \'吐鲁番\', \'乌鲁木齐\', \'伊犁\', \'移动互联网\', \'移动网\',\'预留\') AND (common_app_label IN (\'${overviewApp}\')) GROUP BY server_region ORDER BY SUM(common_s2c_byte_num) DESC LIMIT 10 ) GROUP BY granularity, server_region) GROUP BY server_region ORDER BY bytes_received DESC LIMIT 10\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"regionIdc2inReceivedTrafficBytesTop10\"\r\n    },\r\n    {\r\n      \"querySql\": \"SELECT server_region AS server_region, SUM(bytes_received) AS bytes_received, IFNULL(ROUND(AVG(received_rate), 4), 0) AS received_rate_avg, IFNULL(ROUND(MAX(received_rate), 4), 0) AS received_rate_max, IFNULL(ROUND(MIN(received_rate), 4), 0)