       </#if>\r\n    ]\r\n    // 前一周期(Pre 1st Region AZ Received Traffic Bytes Top 10)\r\n    var pre1stRegionAZReceivedTrafficBytesTop10 = [\r\n        <#if pre1stRegionAZReceivedTrafficBytesTop10??>\r\n        <#list pre1stRegionAZReceivedTrafficBytesTop10 as d>\r\n        {client_region:\'${getFromObj(d,\'client_region\',\'string\')}\',bytes_received:${jsGetNumFromObj(d,\'bytes_received\')/1024},received_rate_avg:${jsGetNumFromObj(d,\'received_rate_avg\')/1000},received_rate_max:${jsGetNumFromObj(d,\'received_rate_max\')/1000},received_rate_min:${jsGetNumFromObj(d,\'received_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n    // 前二周期(Pre 2nd Region In2out Received Traffic Bytes Top 10)\r\n    var pre2ndRegionIn2outReceivedTrafficBytesTop10 = [\r\n        <#if pre2ndRegionIn2outReceivedTrafficBytesTop10??>\r\n        <#list pre2ndRegionIn2outReceivedTrafficBytesTop10 as d>\r\n        {client_region:\'${getFromObj(d,\'client_region\',\'string\')}\',bytes_received:${jsGetNumFromObj(d,\'bytes_received\')/1024},received_rate_avg:${jsGetNumFromObj(d,\'received_rate_avg\')/1000},received_rate_max:${jsGetNumFromObj(d,\'received_rate_max\')/1000},received_rate_min:${jsGetNumFromObj(d,\'received_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n    // Top 10省内各地区流量分布（省外访问省内${overviewApp}服务）\r\n    var regionOut2inSentTrafficBytesTop10 = [\r\n        <#if regionOut2inSentTrafficBytesTop10??>\r\n        <#list regionOut2inSentTrafficBytesTop10 as d>\r\n        {server_region:\'${getFromObj(d,\'server_region\',\'string\')}\',bytes_sent:${jsGetNumFromObj(d,\'bytes_sent\')/1024},sent_rate_avg:${jsGetNumFromObj(d,\'sent_rate_avg\')/1000},sent_rate_max:${jsGetNumFromObj(d,\'sent_rate_max\')/1000},sent_rate_min:${jsGetNumFromObj(d,\'sent_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n    // 前一周期(Pre 1st Region Out2in Sent Traffic Bytes Top 10)\r\n    var pre1stRegionOut2inSentTrafficBytesTop10 = [\r\n        <#if pre1stRegionOut2inSentTrafficBytesTop10??>\r\n        <#list pre1stRegionOut2inSentTrafficBytesTop10 as d>\r\n        {server_region:\'${getFromObj(d,\'server_region\',\'string\')}\',bytes_sent:${jsGetNumFromObj(d,\'bytes_sent\')/1024},sent_rate_avg:${jsGetNumFromObj(d,\'sent_rate_avg\')/1000},sent_rate_max:${jsGetNumFromObj(d,\'sent_rate_max\')/1000},sent_rate_min:${jsGetNumFromObj(d,\'sent_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n    // 前二周期(Pre 2nd Region Out2in Sent Traffic Bytes Top 10)\r\n    var pre2ndRegionOut2inSentTrafficBytesTop10 = [\r\n        <#if pre2ndRegionOut2inSentTrafficBytesTop10??>\r\n        <#list pre2ndRegionOut2inSentTrafficBytesTop10 as d>\r\n        {server_region:\'${getFromObj(d,\'server_region\',\'string\')}\',bytes_sent:${jsGetNumFromObj(d,\'bytes_sent\')/1024},sent_rate_avg:${jsGetNumFromObj(d,\'sent_rate_avg\')/1000},sent_rate_max:${jsGetNumFromObj(d,\'sent_rate_max\')/1000},sent_rate_min:${jsGetNumFromObj(d,\'sent_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n    // 省外访问省内${overviewApp}服务 TOP 10 省内地区响应流量分布(Region Out2in Received Traffic Bytes Top 10)\r\n    var regionOut2inReceivedTrafficBytesTop10 = [\r\n        <#if regionOut2inReceivedTrafficBytesTop10??>\r\n        <#list regionOut2inReceivedTrafficBytesTop10 as d>\r\n        {server_region:\'${getFromObj(d,\'server_region\',\'string\')}\',bytes_received:${jsGetNumFromObj(d,\'bytes_received\')/1024},received_rate_avg:${jsGetNumFromObj(d,\'received_rate_avg\')/1000},received_rate_max:${jsGetNumFromObj(d,\'received_rate_max\')/1000},received_rate_min:${jsGetNumFromObj(d,\'received_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n    // 前一周期(Pre 1st Region Out2in Received Traffic Bytes Top 10)\r\n    var pre1stRegionOut2inReceivedTrafficBytesTop10 = [\r\n        <#if pre1stRegionOut2inReceivedTrafficBytesTop10??>\r\n        <#list pre1stRegionOut2inReceivedTrafficBytesTop10 as d>\r\n        {server_region:\'${getFromObj(d,\'server_region\',\'string\')}\',bytes_received:${jsGetNumFromObj(d,\'bytes_received\')/1024},received_rate_avg:${jsGetNumFromObj(d,\'received_rate_avg\')/1000},received_rate_max:${jsGetNumFromObj(d,\'received_rate_max\')/1000},received_rate_min:${jsGetNumFromObj(d,\'received_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n    // 前二周期(Pre 2nd Region Out2in Received Traffic Bytes Top 10)\r\n    var pre2ndRegionOut2inReceivedTrafficBytesTop10 = [\r\n        <#if pre2ndRegionOut2inReceivedTrafficBytesTop10??>\r\n        <#list pre2ndRegionOut2inReceivedTrafficBytesTop10 as d>\r\n        {server_region:\'${getFromObj(d,\'server_region\',\'string\')}\',bytes_received:${jsGetNumFromObj(d,\'bytes_received\')/1024},received_rate_avg:${jsGetNumFromObj(d,\'received_rate_avg\')/1000},received_rate_max:${jsGetNumFromObj(d,\'received_rate_max\')/1000},received_rate_min:${jsGetNumFromObj(d,\'received_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n\r\n    // 4.1 ${overviewApp}服务省内访问省外\r\n    var linkDirectionTrafficIn2Out = [\r\n        <#if linkDirectionTrafficIn2Out??>\r\n        <#list linkDirectionTrafficIn2Out as d>\r\n        {\r\n            egress_link_direction:\'${getFromObj(d,\'egress_link_direction\',\'string\')}\',\r\n            ingress_link_direction:\'${getFromObj(d,\'ingress_link_direction\',\'string\')}\',\r\n            egress_bytes:${jsGetNumFromObj(d,\'egress_bytes\')/1024},\r\n            ingress_bytes:${jsGetNumFromObj(d,\'ingress_bytes\')/1024},\r\n            bytes:${jsGetNumFromObj(d,\'bytes\')/1024},\r\n            sessions:${jsGetNumFromObj(d,\'sessions\')}\r\n        },\r\n        </#list>\r\n        </#if>\r\n    ]\r\n\r\n    // 4.2 各链路Top5指标流量占比\r\n    // 上行链路总流量统计\r\n    var linkEgressTrafficIn2Out = [\r\n        <#if linkEgressTrafficIn2Out??>\r\n        <#list linkEgressTrafficIn2Out as d>\r\n        {\r\n            egress_link_direction:\'${getFromObj(d,\'egress_link_direction\',\'string\'