n    {\r\n      \"querySql\": \"SELECT ingress_link_direction AS ingress_link_direction, client_province AS client_province, SUM(common_c2s_byte_num) AS ingress_bytes, SUM(common_sessions) AS sessions FROM session_record_cn WHERE common_recv_time >= ${startTime} - ${timeDiff} * 2 AND common_recv_time < ${endTime} - ${timeDiff} * 2 AND client_region NOT IN (\'IDC\', \'IPTV\', \'VBAS测试\', \'阿克苏\', \'阿勒泰\', \'巴州\', \'博州\', \'昌吉\', \'哈密\', \'和田\', \'喀什\', \'克拉玛依\', \'克州\', \'奎屯\', \'区公司\', \'石河子\',\'塔城\', \'吐鲁番\', \'乌鲁木齐\', \'伊犁\', \'移动互联网\', \'移动网\',\'预留\') AND server_region IN (\'IDC\', \'IPTV\', \'VBAS测试\', \'阿克苏\', \'阿勒泰\', \'巴州\', \'博州\', \'昌吉\', \'哈密\', \'和田\', \'喀什\', \'克拉玛依\', \'克州\', \'奎屯\', \'区公司\', \'石河子\',\'塔城\', \'吐鲁番\', \'乌鲁木齐\', \'伊犁\', \'移动互联网\', \'移动网\',\'预留\') AND (common_app_label IN (\'${overviewApp}\')) AND ingress_link_direction IN (\'西安\') AND client_province IN ( SELECT client_province FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND notEmpty(client_province) AND client_region NOT IN (\'IDC\', \'IPTV\', \'VBAS测试\', \'阿克苏\', \'阿勒泰\', \'巴州\', \'博州\', \'昌吉\', \'哈密\', \'和田\', \'喀什\', \'克拉玛依\', \'克州\', \'奎屯\', \'区公司\', \'石河子\',\'塔城\', \'吐鲁番\', \'乌鲁木齐\', \'伊犁\', \'移动互联网\', \'移动网\',\'预留\') AND server_region IN (\'IDC\', \'IPTV\', \'VBAS测试\', \'阿克苏\', \'阿勒泰\', \'巴州\', \'博州\', \'昌吉\', \'哈密\', \'和田\', \'喀什\', \'克拉玛依\', \'克州\', \'奎屯\', \'区公司\', \'石河子\',\'塔城\', \'吐鲁番\', \'乌鲁木齐\', \'伊犁\', \'移动互联网\', \'移动网\',\'预留\') AND (common_app_label IN (\'${overviewApp}\')) AND ingress_link_direction IN (\'西安\') GROUP BY client_province ORDER BY SUM(common_c2s_byte_num) DESC LIMIT 5 ) GROUP BY ingress_link_direction, client_province ORDER BY ingress_bytes DESC LIMIT 5\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"pre2ndLinkIngressTrafficTopNProvinceOut2InXA\"\r\n    }\r\n  ]\r\n}', 0, '2022-10-18 23:00:27', 1, '2022-10-18 23:00:34', NULL);
INSERT INTO `report_category` VALUES (12, 'Application Report', '<!DOCTYPE html>\r\n<html lang=\"en\"><head>\r\n    <meta charset=\"UTF-8\">\r\n    <#setting number_format=\"0.####\"/>\r\n    <title>Application Report-${overviewApp}</title>\r\n    <script src=\"http://${uiStaticUrl}/assets/echarts.min.js\"></script>\r\n    <style>${reportStyleCommon}</style>\r\n</head>\r\n<body>\r\n<div class=\"header1\">Application Report-${overviewApp}<span class=\"header1__time\" id=\"currentRange0\"></span></div>\r\n<div class=\"table__footer\">\r\n    <div class=\"footer__label\"></div>\r\n</div>\r\n<div class=\"header2\">1.Network Summary</div>\r\n<div class=\"header3\">1.1 Traffic Summary</div>\r\n<div class=\"table-box indent-3\">\r\n    <div class=\"table__title\">Table1 Traffic Statistics</div>\r\n    <table class=\"table\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th class=\"table__th\">Avg Data Rate</th>\r\n            <th class=\"table__th\">Min Data Rate</th>\r\n            <th class=\"table__th\" style=\"width: 200px\">Quantiles of Data Rate</th>\r\n            <th class=\"table__th\">Max Data Rate</th>\r\n            <th class=\"table__th\" style=\"width: 130px\">Change of Avg Data Rate</th>\r\n            <th class=\"table__th\">Throughput</th>\r\n            <th class=\"table__th\" style=\"width: 150px\">Percentage of Overall Throughput</th>\r\n            <th class=\"table__th\" style=\"width: 130px\">Change of Throughput</th>\r\n        </tr>\r\n        </thead>\r\n        <tbody><tr class=\"table__tr\">\r\n            <td class=\"table__td\">\r\n                ${convertNumber(getFromArr(xxxServiceRate,0,\'rate_avg\',\'number\'),\'bps\',1000)}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertNumber(getFromArr(xxxServiceRate,0,\'rate_min\',\'number\'),\'bps\',1000)}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                <div class=\"td__quantile-group\">\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p50\"></span>P50</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertNumber(getFromArr(xxxServiceRate,0,\'rate50\',\'number\'),\'bps\',1000)}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p90\"></span>P90</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertNumber(getFromArr(xxxServiceRate,0,\'rate90\',\'number\'),\'bps\',1000)}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p99\"></span>P99</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertNumber(getFromArr(xxxServiceRate,0,\'rate99\',\'number\'),\'bps\',1000)}\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertNumber(getFromArr(xxxServiceRate,0,\'rate_max\',\'number\'),\'bps\',1000)}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${chainRatio(getFromArr(xxxServiceRate,0,\'rate_avg\',\'number\'),getFromArr(pre1stxxxServiceRate,0,\'rate_avg\',\'number\'))}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertNumber(getFromArr(xxxServiceTrafficTotal,0,\'bytes\',\'number\'),\'byte\',1024)}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${proportion(getFromArr(xxxServiceTrafficTotal,0,\'bytes\',\'number\'),getFromArr(trafficTotal,0,\'bytes\',\'number\'))}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${chainRatio(getFromArr(xxxServiceTrafficTotal,0,\'bytes\',\'number\'),getFromArr(pre1stxxxServiceTrafficTotal,0,\'bytes\',\'number\'))}\r\n            </td>\r\n        </tr>\r\n        </tbody></table>\r\n    <div class=\"table__footer\">\r\n        <div class=\"footer__label\"></div>\r\n    </div>\r\n</div>\r\n<div class=\"echarts-box indent-3\">\r\n    <div class=\"echarts\">\r\n        <div class=\"echarts__canvas echarts__line\" id=\"canvas1\"></div>\r\n        <div class=\"echarts__title\">Fig 1. Bandwidth Trend</div>\r\n    </div>\r\n</div>\r\n\r\n<div class=\"header3\">1.2 Network Performance Summary</div>\r\n<div class=\"table-box indent-3\">\r\n    <div class=\"table__title\">Table 2. Sessions from External to Internal</div>\r\n    <table class=\"table\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th class=\"table__th\">NPM Metric</th>\r\n            <th class=\"table__th\">Quantiles</th>\r\n            <th class=\"table__th\">Max Value</th>\r\n            <th class=\"table__th\">Avg Value</th>\r\n            <th class=\"table__th\">Change of Avg Value</th>\r\n        </tr>\r\n        </thead>\r\n        <tbody><tr class=\"table__tr\">\r\n            <td class=\"table__td\">TCP Connection Establish Latency</td>\r\n            <td class=\"table__td\">\r\n                <div class=\"td__quantile-group\">\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p50\"></span>P50</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertTime(getFromArr(xxxServiceOut2inTcp,0,\'establish_latency_p50\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p90\"></span>P90</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertTime(getFromArr(xxxServiceOut2inTcp,0,\'establish_latency_p90\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p99\"></span>P99</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertTime(getFromArr(xxxServiceOut2inTcp,0,\'establish_latency_p99\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertTime(getFromArr(xxxServiceOut2inTcp,0,\'establish_latency_max\',\'number\'))}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertTime(getFromArr(xxxServiceOut2inTcp,0,\'establish_latency_avg\',\'number\'))}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${chainRatio(getFromArr(xxxServiceOut2inTcp,0,\'establish_latency_avg\',\'number\'),getFromArr(pre1stxxxServiceOut2inTcp,0,\'establish_latency_avg\',\'number\'))}\r\n            </td>\r\n        </tr>\r\n        <tr class=\"table__tr\">\r\n            <td class=\"table__td\">Packet Loss</td>\r\n            <td class=\"table__td\">\r\n                <div class=\"td__quantile-group\">\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p50\"></span>P50</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertPercent(getFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_p50\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p90\"></span>P90</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertPercent(getFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_p90\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p99\"></span>P99</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertPercent(getFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_p99\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertPercent(getFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_max\',\'number\'))}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertPercent(getFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_avg\',\'number\'))}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${chainRatio(getFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_avg\',\'number\'),getFromArr(pre1stxxxServiceOut2inLossPackets,0,\'sequence_gap_loss_avg\',\'number\'))}\r\n            </td>\r\n        </tr>\r\n        </tbody></table>\r\n</div>\r\n<div class=\"table-box indent-3\">\r\n    <div class=\"table__title\">Table 3. Sessions from Internal to External</div>\r\n    <table class=\"table\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th class=\"table__th\">NPM Metric</th>\r\n            <th class=\"table__th\">Quantiles</th>\r\n            <th class=\"table__th\">Max Value</th>\r\n            <th class=\"table__th\">Avg Value</th>\r\n            <th class=\"table__th\">Change of Avg Value</th>\r\n        </tr>\r\n        </thead>\r\n        <tbody><tr class=\"table__tr\">\r\n            <td class=\"table__td\">TCP Connection Establish Latency</td>\r\n            <td class=\"table__td\">\r\n                <div class=\"td__quantile-group\">\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p50\"></span>P50</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertTime(getFromArr(xxxServiceIn2outTcp,0,\'establish_latency_p50\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p90\"></span>P90</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertTime(getFromArr(xxxServiceIn2outTcp,0,\'establish_latency_p90\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p99\"></span>P99</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertTime(getFromArr(xxxServiceIn2outTcp,0,\'establish_latency_p99\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertTime(getFromArr(xxxServiceIn2outTcp,0,\'establish_latency_max\',\'number\'))}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertTime(getFromArr(xxxServiceIn2outTcp,0,\'establish_latency_avg\',\'number\'))}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${chainRatio(getFromArr(xxxServiceIn2outTcp,0,\'establish_latency_avg\',\'number\'),getFromArr(pre1stxxxServiceIn2outTcp,0,\'establish_latency_avg\',\'number\'))}\r\n            </td>\r\n        </tr>\r\n        <tr class=\"table__tr\">\r\n            <td class=\"table__td\">Packet Loss</td>\r\n            <td class=\"table__td\">\r\n                <div class=\"td__quantile-group\">\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p50\"></span>P50</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertPercent(getFromArr(xxxServiceIn2outLossPackets,0,\'sequence_gap_loss_p50\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p90\"></span>P90</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertPercent(getFromArr(xxxServiceIn2outLossPackets,0,\'sequence_gap_loss_p90\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p99\"></span>P99</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertPercent(getFromArr(xxxServiceIn2outLossPackets,0,\'sequence_gap_loss_p99\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertPercent(getFromArr(xxxServiceIn2outLossPackets,0,\'sequence_gap_loss_max\',\'number\'))}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertPercent(getFromArr(xxxServiceIn2outLossPackets,0,\'sequence_gap_loss_avg\',\'number\'))}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${chainRatio(getFromArr(xxxServiceIn2outLossPackets,0,\'sequence_gap_loss_avg\',\'number\'),getFromArr(pre1stxxxServiceIn2outLossPackets,0,\'sequence_gap_loss_avg\',\'number\'))}\r\n            </td>\r\n        </tr>\r\n        </tbody></table>\r\n</div>\r\n\r\n<div class=\"header2\">2. Top Services</div>\r\n<div class=\"echarts-box indent-3\">\r\n    <span class=\"echarts pie-style\">\r\n    <div class=\"echarts__canvas echarts__pie\" id=\"canvas13\"></div>\r\n    <div class=\"echarts__title\">Fig 2. Top Domains by Percentage of Throughput</div>\r\n  </span>\r\n    <span class=\"echarts pie-style\">\r\n    <div class=\"echarts__canvas echarts__pie\" id=\"canvas18\"></div>\r\n    <div class=\"echarts__title\">Fig 3. Top Protocols by Percentage of Throughput</div>\r\n  </span>\r\n</div>\r\n\r\n<div class=\"header2\">3. Geographical Distribution</div>\r\n<div class=\"echarts-box indent-3\">\r\n    <div class=\"echarts\">\r\n        <div class=\"echarts__canvas echarts__line-and-bar\" id=\"canvas2\"></div>\r\n    </div>\r\n</div>\r\n<div class=\"table-box indent-3\">\r\n    <table class=\"table\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th class=\"table__th\">Data Ratio by Region</th>\r\n            <#if provinceIn2outSentTrafficBytesTop10??>\r\n                <#list provinceIn2outSentTrafficBytesTop10 as val>\r\n                    <th class=\"table__th\">${getFromObj(val,\'server_province\',\'string\')}</th>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </thead>\r\n        <tbody><tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">Max Value</td>\r\n            <#if provinceIn2outSentTrafficBytesTop10??>\r\n                <#list provinceIn2outSentTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'sent_rate_max\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        <tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">Avg Value</td>\r\n            <#if provinceIn2outSentTrafficBytesTop10??>\r\n                <#list provinceIn2outSentTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'sent_rate_avg\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </tbody></table>\r\n    <div class=\"echarts__title echarts__line-and-bar-title\">Fig 4. Top 10 Regions by Request Traffic from Internal to External</div>\r\n</div>\r\n\r\n<div class=\"echarts-box indent-3\">\r\n    <div class=\"echarts\">\r\n        <div class=\"echarts__canvas echarts__line-and-bar\" id=\"canvas8\"></div>\r\n    </div>\r\n</div>\r\n<div class=\"table-box indent-3\">\r\n    <table class=\"table\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th class=\"table__th\">Data Ratio by Region</th>\r\n            <#if provinceIn2outReceivedTrafficBytesTop10??>\r\n                <#list provinceIn2outReceivedTrafficBytesTop10 as val>\r\n                    <th class=\"table__th\">${getFromObj(val,\'server_province\',\'string\')}</th>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </thead>\r\n        <tbody>\r\n        <tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">Max Value</td>\r\n            <#if provinceIn2outReceivedTrafficBytesTop10??>\r\n                <#list provinceIn2outReceivedTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'received_rate_max\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        <tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">Avg Value</td>\r\n            <#if provinceIn2outReceivedTrafficBytesTop10??>\r\n                <#list provinceIn2outReceivedTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'received_rate_avg\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </tbody></table>\r\n    <div class=\"echarts__title echarts__line-and-bar-title\">Fig 5. Top 10 Regions by Response Traffic from Internal to External</div>\r\n</div>\r\n\r\n<div class=\"echarts-box indent-3\">\r\n    <div class=\"echarts\">\r\n        <div class=\"echarts__canvas echarts__line-and-bar\" id=\"canvas3\"></div>\r\n    </div>\r\n</div>\r\n<div class=\"table-box indent-3\">\r\n    <table class=\"table\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th class=\"table__th\">Data Ratio by Region</th>\r\n            <#if provinceOut2inSentTrafficBytesTop10??>\r\n                <#list provinceOut2inSentTrafficBytesTop10 as val>\r\n                    <th class=\"table__th\">${getFromObj(val,\'client_province\',\'string\')}</th>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </thead>\r\n        <tbody><tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">Max Value</td>\r\n            <#if provinceOut2inSentTrafficBytesTop10??>\r\n                <#list provinceOut2inSentTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'sent_rate_max\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        <tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">Avg Value</td>\r\n            <#if provinceOut2inSentTrafficBytesTop10??>\r\n                <#list provinceOut2inSentTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'sent_rate_avg\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </tbody></table>\r\n    <div class=\"echarts__title echarts__line-and-bar-title\">Fig 6. Top 10 Regions by Request Traffic from External to Internal</div>\r\n</div>\r\n\r\n<div class=\"echarts-box indent-3\">\r\n    <div class=\"echarts\">\r\n        <div class=\"echarts__canvas echarts__line-and-bar\" id=\"canvas9\"></div>\r\n    </div>\r\n</div>\r\n<div class=\"table-box indent-3\">\r\n    <table class=\"table\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th class=\"table__th\">Data Ratio by Region</th>\r\n            <#if provinceOut2inReceivedTrafficBytesTop10??>\r\n                <#list provinceOut2inReceivedTrafficBytesTop10 as val>\r\n                    <th class=\"table__th\">${getFromObj(val,\'client_province\',\'string\')}</th>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </thead>\r\n        <tbody>\r\n        <tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">Max Value</td>\r\n            <#if provinceOut2inReceivedTrafficBytesTop10??>\r\n                <#list provinceOut2inReceivedTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'received_rate_max\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        <tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">Avg Value</td>\r\n            <#if provinceOut2inReceivedTrafficBytesTop10??>\r\n                <#list provinceOut2inReceivedTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'received_rate_avg\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </tbody></table>\r\n    <div class=\"echarts__title echarts__line-and-bar-title\">Fig 7. Top 10 Regions by Response Traffic from External to Internal</div>\r\n</div>\r\n\r\n<script>\r\n    /** 数据 begin */\r\n        // 时间区间\r\n    var timeRange = [${startTime}, ${endTime}]\r\n    // 时区偏移毫秒\r\n    var timeZoneOffset = ${timeZoneOffset}\r\n    /* 1.1 流量变化曲线 */\r\n    // 总流量\r\n    var trafficTotal = ${jsGetNumFromArr(trafficTotal,0,\'bytes\')/1024}\r\n    // xxx服务总流量 (xxxService traffic total)\r\n    var xxxServiceTrafficTotal = ${jsGetNumFromArr(xxxServiceTrafficTotal,0,\'bytes\')/1024}\r\n    // 前一周期(Pre 1st xxxService traffic total)\r\n    var pre1stxxxServiceTrafficTotal = ${jsGetNumFromArr(pre1stxxxServiceTrafficTotal,0,\'bytes\')/1024}\r\n    // 前二周期(Pre 2st xxxService traffic total)\r\n    var pre2ndxxxServiceTrafficTotal = ${jsGetNumFromArr(pre2ndxxxServiceTrafficTotal,0,\'bytes\')/1024}\r\n    // 省外访问省内服${overviewApp}的服务质量\r\n    var xxxServiceOut2inTrafficTotal = {\r\n        bytes_sent: ${jsGetNumFromArr(xxxServiceOut2inTrafficTotal,0,\'bytes_sent\')/1024},\r\n        bytes_received: ${jsGetNumFromArr(xxxServiceOut2inTrafficTotal,0,\'bytes_received\')/1024},\r\n        bytes: ${jsGetNumFromArr(xxxServiceOut2inTrafficTotal,0,\'bytes\')/1024}\r\n    }\r\n    // 前一周期(Pre 1st xxxService ZA traffic total)\r\n    var Pre1stxxxServiceOut2inTrafficTotal = {\r\n        bytes_sent: ${jsGetNumFromArr(Pre1stxxxServiceOut2inTrafficTotal,0,\'bytes_sent\')/1024},\r\n        bytes_received: ${jsGetNumFromArr(Pre1stxxxServiceOut2inTrafficTotal,0,\'bytes_received\')/1024},\r\n        bytes: ${jsGetNumFromArr(Pre1stxxxServiceOut2inTrafficTotal,0,\'bytes\')/1024}\r\n    }\r\n    // 前二周期(Pre 2nd xxxService ZA traffic total)\r\n    var Pre2ndxxxServiceOut2inTrafficTotal = {\r\n        bytes_sent: ${jsGetNumFromArr(Pre2ndxxxServiceOut2inTrafficTotal,0,\'bytes_sent\')/1024},\r\n        bytes_received: ${jsGetNumFromArr(Pre2ndxxxServiceOut2inTrafficTotal,0,\'bytes_received\')/1024},\r\n        bytes: ${jsGetNumFromArr(Pre2ndxxxServiceOut2inTrafficTotal,0,\'bytes\')/1024}\r\n    }\r\n    // 省内访问省外${overviewApp}服务流量\r\n    var xxxServiceIn2outTrafficTotal = {\r\n        bytes_sent: ${jsGetNumFromArr(xxxServiceIn2outTrafficTotal,0,\'bytes_sent\')/1024},\r\n        bytes_received: ${jsGetNumFromArr(xxxServiceIn2outTrafficTotal,0,\'bytes_received\')/1024},\r\n        bytes: ${jsGetNumFromArr(xxxServiceIn2outTrafficTotal,0,\'bytes\')/1024}\r\n    }\r\n    var pre1stxxxServiceIn2outTrafficTotal = {\r\n        bytes_sent: ${jsGetNumFromArr(pre1stxxxServiceIn2outTrafficTotal,0,\'bytes_sent\')/1024},\r\n        bytes_received: ${jsGetNumFromArr(pre1stxxxServiceIn2outTrafficTotal,0,\'bytes_received\')/1024},\r\n        bytes: ${jsGetNumFromArr(pre1stxxxServiceIn2outTrafficTotal,0,\'bytes\')/1024}\r\n    }\r\n    var pre2ndxxxServiceIn2outTrafficTotal = {\r\n        bytes_sent: ${jsGetNumFromArr(pre2ndxxxServiceIn2outTrafficTotal,0,\'bytes_sent\')/1024},\r\n        bytes_received: ${jsGetNumFromArr(pre2ndxxxServiceIn2outTrafficTotal,0,\'bytes_received\')/1024},\r\n        bytes: ${jsGetNumFromArr(pre2ndxxxServiceIn2outTrafficTotal,0,\'bytes\')/1024}\r\n    }\r\n    // ${overviewApp}服务速率\r\n    var xxxServiceRate = {\r\n        rate50: ${jsGetNumFromArr(xxxServiceRate,0,\'rate50\')/1000},\r\n        rate90: ${jsGetNumFromArr(xxxServiceRate,0,\'rate90\')/1000},\r\n        rate99: ${jsGetNumFromArr(xxxServiceRate,0,\'rate99\')/1000},\r\n        rate_avg:${jsGetNumFromArr(xxxServiceRate,0,\'rate_avg\')/1000},\r\n        rate_max:${jsGetNumFromArr(xxxServiceRate,0,\'rate_max\')/1000},\r\n        rate_min:${jsGetNumFromArr(xxxServiceRate,0,\'rate_min\')/1000}\r\n    }\r\n    var pre1stxxxServiceRate = {\r\n        rate50: ${jsGetNumFromArr(pre1stxxxServiceRate,0,\'rate50\')/1000},\r\n        rate90: ${jsGetNumFromArr(pre1stxxxServiceRate,0,\'rate90\')/1000},\r\n        rate99: ${jsGetNumFromArr(pre1stxxxServiceRate,0,\'rate99\')/1000},\r\n        rate_avg:${jsGetNumFromArr(pre1stxxxServiceRate,0,\'rate_avg\')/1000},\r\n        rate_max:${jsGetNumFromArr(pre1stxxxServiceRate,0,\'rate_max\')/1000},\r\n        rate_min:${jsGetNumFromArr(pre1stxxxServiceRate,0,\'rate_min\')/1000}\r\n    }\r\n    var pre2ndxxxServiceRate = {\r\n        rate50: ${jsGetNumFromArr(pre2ndxxxServiceRate,0,\'rate50\')/1000},\r\n        rate90: ${jsGetNumFromArr(pre2ndxxxServiceRate,0,\'rate90\')/1000},\r\n        rate99: ${jsGetNumFromArr(pre2ndxxxServiceRate,0,\'rate99\')/1000},\r\n        rate_avg:${jsGetNumFromArr(pre2ndxxxServiceRate,0,\'rate_avg\')/1000},\r\n        rate_max:${jsGetNumFromArr(pre2ndxxxServiceRate,0,\'rate_max\')/1000},\r\n        rate_min:${jsGetNumFromArr(pre2ndxxxServiceRate,0,\'rate_min\')/1000}\r\n    }\r\n    // ${overviewApp}服务当日流量变化曲线\r\n    var xxxServiceTrafficChangingCurve = [\r\n        <#if xxxServiceTrafficChangingCurve??>\r\n        <#list xxxServiceTrafficChangingCurve as d>\r\n        {stat_time:${jsGetNumFromObj(d,\'stat_time\') * 1000},rate:${jsGetNumFromObj(d,\'rate\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n\r\n    // 1.2 服务质量情况\r\n    // 省外访问省内${overviewApp}服务的服务质量\r\n    // TCP会话创建延迟(xxxService Out2in TCP)\r\n    var xxxServiceOut2inTcp = {\r\n        establish_latency_p50: ${jsGetNumFromArr(xxxServiceOut2inTcp,0,\'establish_latency_p50\')},\r\n        establish_latency_p90: ${jsGetNumFromArr(xxxServiceOut2inTcp,0,\'establish_latency_p90\')},\r\n        establish_latency_p99: ${jsGetNumFromArr(xxxServiceOut2inTcp,0,\'establish_latency_p99\')},\r\n        establish_latency_avg:${jsGetNumFromArr(xxxServiceOut2inTcp,0,\'establish_latency_avg\')},\r\n        establish_latency_max:${jsGetNumFromArr(xxxServiceOut2inTcp,0,\'establish_latency_max\')},\r\n        establish_latency_min:${jsGetNumFromArr(xxxServiceOut2inTcp,0,\'establish_latency_min\')}\r\n    }\r\n    // 上周期(Pre 1st xxxService Out2in TCP)\r\n    var pre1stxxxServiceOut2inTcp = {\r\n        establish_latency_p50: ${jsGetNumFromArr(pre1stxxxServiceOut2inTcp,0,\'establish_latency_p50\')},\r\n        establish_latency_p90: ${jsGetNumFromArr(pre1stxxxServiceOut2inTcp,0,\'establish_latency_p90\')},\r\n        establish_latency_p99: ${jsGetNumFromArr(pre1stxxxServiceOut2inTcp,0,\'establish_latency_p99\')},\r\n        establish_latency_avg:${jsGetNumFromArr(pre1stxxxServiceOut2inTcp,0,\'establish_latency_avg\')},\r\n        establish_latency_max:${jsGetNumFromArr(pre1stxxxServiceOut2inTcp,0,\'establish_latency_max\')},\r\n        establish_latency_min:${jsGetNumFromArr(pre1stxxxServiceOut2inTcp,0,\'establish_latency_min\')}\r\n    }\r\n    // 丢包率(xxxService Out2in loss packets)\r\n    var xxxServiceOut2inLossPackets = {\r\n        sequence_gap_loss_p50: ${jsGetNumFromArr(xxxServiceOut2inLossPackets,0,\'establish_latency_p50\')},\r\n        sequence_gap_loss_p90: ${jsGetNumFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_p90\')},\r\n        sequence_gap_loss_p99: ${jsGetNumFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_p99\')},\r\n        sequence_gap_loss_avg:${jsGetNumFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_avg\')},\r\n        sequence_gap_loss_max:${jsGetNumFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_max\')},\r\n        sequence_gap_loss_min:${jsGetNumFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_min\')}\r\n    }\r\n    // 上周期(Pre 1st xxxService Out2in loss packets)\r\n    var pre1stxxxServiceOut2inLossPackets = {\r\n        sequence_gap_loss_p50: ${jsGetNumFromArr(pre1stxxxServiceOut2inLossPackets,0,\'sequence_gap_loss_p50\')},\r\n        sequence_gap_loss_p90: ${jsGetNumFromArr(pre1stxxxServiceOut2inLossPackets,0,\'sequence_gap_loss_p90\')},\r\n        sequence_gap_loss_p99: ${jsGetNumFromArr(pre1stxxxServiceOut2inLossPackets,0,\'sequence_gap_loss_p99\')},\r\n        sequence_gap_loss_avg:${jsGetNumFromArr(pre1stxxxServiceOut2inLossPackets,0,\'sequence_gap_loss_avg\')},\r\n        sequence_gap_loss_max:${jsGetNumFromArr(pre1stxxxServiceOut2inLossPackets,0,\'sequence_gap_loss_max\')},\r\n        sequence_gap_loss_min:${jsGetNumFromArr(pre1stxxxServiceOut2inLossPackets,0,\'sequence_gap_loss_min\')}\r\n    }\r\n    // 省内访问省外${overviewApp}的服务质量\r\n    // TCP会话创建延迟(xxxService In2out TCP)\r\n    var xxxServiceIn2outTcp = {\r\n        establish_latency_p50: ${jsGetNumFromArr(xxxServiceIn2outTcp,0,\'establish_latency_p50\')},\r\n        establish_latency_p90: ${jsGetNumFromArr(xxxServiceIn2outTcp,0,\'establish_latency_p90\')},\r\n        establish_latency_p99: ${jsGetNumFromArr(xxxServiceIn2outTcp,0,\'establish_latency_p99\')},\r\n        establish_latency_avg:${jsGetNumFromArr(xxxServiceIn2outTcp,0,\'establish_latency_avg\')},\r\n        establish_latency_max:${jsGetNumFromArr(xxxServiceIn2outTcp,0,\'establish_latency_max\')},\r\n        establish_latency_min:${jsGetNumFromArr(xxxServiceIn2outTcp,0,\'establish_latency_min\')}\r\n    }\r\n    // 上周期(Pre 1st xxxService In2out TCP)\r\n    var pre1stxxxServiceIn2outTcp = {\r\n        establish_latency_p50: ${jsGetNumFromArr(pre1stxxxServiceIn2outTcp,0,\'establish_latency_p50\')},\r\n        establish_latency_p90: ${jsGetNumFromArr(pre1stxxxServiceIn2outTcp,0,\'establish_latency_p90\')},\r\n        establish_latency_p99: ${jsGetNumFromArr(pre1stxxxServiceIn2outTcp,0,\'establish_latency_p99\')},\r\n        establish_latency_avg:${jsGetNumFromArr(pre1stxxxServiceIn2outTcp,0,\'establish_latency_avg\')},\r\n        establish_latency_max:${jsGetNumFromArr(pre1stxxxServiceIn2outTcp,0,\'establish_latency_max\')},\r\n        establish_latency_min:${jsGetNumFromArr(pre1stxxxServiceIn2outTcp,0,\'establish_latency_min\')}\r\n    }\r\n    // 丢包率(xxxService In2out loss packets)\r\n    var xxxServiceIn2outLossPackets = {\r\n        sequence_gap_loss_p50: ${jsGetNumFromArr(xxxServiceIn2outLossPackets,0,\'sequence_gap_loss_p50\')},\r\n        sequence_gap_loss_p90: ${jsGetNumFromArr(xxxServiceIn2outLossPackets,0,\'sequence_gap_loss_p90\')},\r\n        sequence_gap_loss_p99: ${jsGetNumFromArr(xxxServiceIn2outLossPackets,0,\'sequence_gap_loss_p99\')},\r\n        sequence_gap_loss_avg:${jsGetNumFromArr(xxxServiceIn2outLossPackets,0,\'sequence_gap_loss_avg\')},\r\n        sequence_gap_loss_max:${jsGetNumFromArr(xxxServiceIn2outLossPackets,0,\'sequence_gap_loss_max\')},\r\n        sequence_gap_loss_min:${jsGetNumFromArr(xxxServiceIn2outLossPackets,0,\'sequence_gap_loss_min\')}\r\n    }\r\n    // 上周期(Pre 1st xxxService In2out loss packets)\r\n    var pre1stxxxServiceIn2outLossPackets = {\r\n        sequence_gap_loss_p50: ${jsGetNumFromArr(pre1stxxxServiceIn2outLossPackets,0,\'sequence_gap_loss_p50\')},\r\n        sequence_gap_loss_p90: ${jsGetNumFromArr(pre1stxxxServiceIn2outLossPackets,0,\'sequence_gap_loss_p90\')},\r\n        sequence_gap_loss_p99: ${jsGetNumFromArr(pre1stxxxServiceIn2outLossPackets,0,\'sequence_gap_loss_p99\')},\r\n        sequence_gap_loss_avg:${jsGetNumFromArr(pre1stxxxServiceIn2outLossPackets,0,\'sequence_gap_loss_avg\')},\r\n        sequence_gap_loss_max:${jsGetNumFromArr(pre1stxxxServiceIn2outLossPackets,0,\'sequence_gap_loss_max\')},\r\n        sequence_gap_loss_min:${jsGetNumFromArr(pre1stxxxServiceIn2outLossPackets,0,\'sequence_gap_loss_min\')}\r\n    }\r\n    /* 2 业务分部 */\r\n    // 相关Domain流量占比\r\n    var top10RelatedDomainBytes = [\r\n        <#if top10RelatedDomainBytes??>\r\n        <#list top10RelatedDomainBytes as d>\r\n        {domain:\'${getFromObj(d,\'domain\',\'string\')}\',bytes:${jsGetNumFromObj(d,\'bytes\')/1024}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n    // 应用层协议占比\r\n    var top10RelatedProtocolBytes = [\r\n        <#if top10RelatedProtocolBytes??>\r\n        <#list top10RelatedProtocolBytes as d>\r\n        {l7_protocol:\'${getFromObj(d,\'l7_protocol\',\'string\')}\',bytes:${jsGetNumFromObj(d,\'bytes\')/1024}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n\r\n\r\n    /* 3 地理位置分布 */\r\n    // 3.1 各省份流量分布\r\n    // Top 10省份流量分布（省内访问省外${overviewApp}服务）\r\n    var provinceIn2outSentTrafficBytesTop10 = [\r\n        <#if provinceIn2outSentTrafficBytesTop10??>\r\n        <#list provinceIn2outSentTrafficBytesTop10 as d>\r\n        {server_province:\'${getFromObj(d,\'server_province\',\'string\')}\',bytes_sent:${jsGetNumFromObj(d,\'bytes_sent\')/1024},sent_rate_avg:${jsGetNumFromObj(d,\'sent_rate_avg\')/1000},sent_rate_max:${jsGetNumFromObj(d,\'sent_rate_max\')/1000},sent_rate_min:${jsGetNumFromObj(d,\'sent_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n    // 前一周期(Pre 1st Province In2out Sent Traffic Bytes Top 10)\r\n    var pre1stProvinceIn2outSentTrafficBytesTop10 = [\r\n        <#if pre1stProvinceIn2outSentTrafficBytesTop10??>\r\n        <#list pre1stProvinceIn2outSentTrafficBytesTop10 as d>\r\n        {server_province:\'${getFromObj(d,\'server_province\',\'string\')}\',bytes_sent:${jsGetNumFromObj(d,\'bytes_sent\')/1024},sent_rate_avg:${jsGetNumFromObj(d,\'sent_rate_avg\')/1000},sent_rate_max:${jsGetNumFromObj(d,\'sent_rate_max\')/1000},sent_rate_min:${jsGetNumFromObj(d,\'sent_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n\r\n    // 省内访问省外${overviewApp}服务TOP10省份响应流量分布(Province In2out Received Traffic Bytes Top 10)\r\n    var provinceIn2outReceivedTrafficBytesTop10 = [\r\n        <#if provinceIn2outReceivedTrafficBytesTop10??>\r\n        <#list provinceIn2outReceivedTrafficBytesTop10 as d>\r\n        {server_province:\'${getFromObj(d,\'server_province\',\'string\')}\',bytes_received:${jsGetNumFromObj(d,\'bytes_received\')/1024},received_rate_avg:${jsGetNumFromObj(d,\'received_rate_avg\')/1000},received_rate_max:${jsGetNumFromObj(d,\'received_rate_max\')/1000},received_rate_min:${jsGetNumFromObj(d,\'received_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n    // 前一周期( Pre 1st Province In2out Received Traffic Bytes Top 10)\r\n    var pre1stProvinceIn2outReceivedTrafficBytesTop10 = [\r\n        <#if pre1stProvinceIn2outReceivedTrafficBytesTop10??>\r\n        <#list pre1stProvinceIn2outReceivedTrafficBytesTop10 as d>\r\n        {server_province:\'${getFromObj(d,\'server_province\',\'string\')}\',bytes_received:${jsGetNumFromObj(d,\'bytes_received\')/1024},received_rate_avg:${jsGetNumFromObj(d,\'received_rate_avg\')/1000},received_rate_max:${jsGetNumFromObj(d,\'received_rate_max\')/1000},received_rate_min:${jsGetNumFromObj(d,\'received_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n\r\n    // Top 10省份流量分布（省外访问省内${overviewApp}服务）\r\n    var provinceOut2inSentTrafficBytesTop10 = [\r\n        <#if provinceOut2inSentTrafficBytesTop10??>\r\n        <#list provinceOut2inSentTrafficBytesTop10 as d>\r\n        {client_province:\'${getFromObj(d,\'client_province\',\'string\')}\',bytes_sent:${jsGetNumFromObj(d,\'bytes_sent\')/1024},sent_rate_avg:${jsGetNumFromObj(d,\'sent_rate_avg\')/1000},sent_rate_max:${jsGetNumFromObj(d,\'sent_rate_max\')/1000},sent_rate_min:${jsGetNumFromObj(d,\'sent_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n    // 前一周期(Pre 1st Province Out2in Sent Traffic Bytes Top 10)\r\n    var pre1stProvinceOut2inSentTrafficBytesTop10 = [\r\n        <#if pre1stProvinceOut2inSentTrafficBytesTop10??>\r\n        <#list pre1stProvinceOut2inSentTrafficBytesTop10 as d>\r\n        {client_province:\'${getFromObj(d,\'client_province\',\'string\')}\',bytes_sent:${jsGetNumFromObj(d,\'bytes_sent\')/1024},sent_rate_avg:${jsGetNumFromObj(d,\'sent_rate_avg\')/1000},sent_rate_max:${jsGetNumFromObj(d,\'sent_rate_max\')/1000},sent_rate_min:${jsGetNumFromObj(d,\'sent_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n\r\n    // 省外访问省内${overviewApp}服务TOP 10省份响应流量分布(Province Out2in Received Traffic Bytes Top 10)\r\n    var provinceOut2inReceivedTrafficBytesTop10 =  [\r\n        <#if provinceOut2inReceivedTrafficBytesTop10??>\r\n        <#list provinceOut2inReceivedTrafficBytesTop10 as d>\r\n        {client_province:\'${getFromObj(d,\'client_province\',\'string\')}\',bytes_received:${jsGetNumFromObj(d,\'bytes_received\')/1024},received_rate_avg:${jsGetNumFromObj(d,\'received_rate_avg\')/1000},received_rate_max:${jsGetNumFromObj(d,\'received_rate_max\')/1000},received_rate_min:${jsGetNumFromObj(d,\'received_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n    // 前一周期(Pre 1st Province Out2in Received Traffic Bytes Top 10)\r\n    var pre1stProvinceOut2inReceivedTrafficBytesTop10 = [\r\n        <#if pre1stProvinceOut2inReceivedTrafficBytesTop10??>\r\n        <#list pre1stProvinceOut2inReceivedTrafficBytesTop10 as d>\r\n        {client_province:\'${getFromObj(d,\'client_province\',\'string\')}\',bytes_received:${jsGetNumFromObj(d,\'bytes_received\')/1024},received_rate_avg:${jsGetNumFromObj(d,\'received_rate_avg\')/1000},received_rate_max:${jsGetNumFromObj(d,\'received_rate_max\')/1000},received_rate_min:${jsGetNumFromObj(d,\'received_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n\r\n    /** 数据 end */\r\n\r\n    ${reportJsCommon}\r\n\r\n\r\n    if (!isNaN(parseInt(timeZoneOffset))) {\r\n        var explorerTimeOffset = new Date().getTimezoneOffset() * 60 * 1000\r\n        xxxServiceTrafficChangingCurve = xxxServiceTrafficChangingCurve.map(d => ({ rate: d.rate, stat_time: d.stat_time + explorerTimeOffset + timeZoneOffset}))\r\n        timeRange = [timeRange[0] + explorerTimeOffset / 1000 + timeZoneOffset / 1000, timeRange[1] + explorerTimeOffset / 1000 + timeZoneOffset / 1000]\r\n    }\r\n    // 计算出前三个周期的时间戳范围，填充时间\r\n    function initTimeRange () {\r\n        var timeOffset = timeRange[1] - timeRange[0]\r\n        var wholeTimeOffset = [60 * 60 - 1, 60 * 60 * 24 - 1, 60 * 60 * 24 * 7 - 1]\r\n        if (wholeTimeOffset.indexOf(timeOffset) > -1) {\r\n            timeOffset++\r\n        }\r\n        var prevTimeRange = [timeRange[0] - timeOffset, timeRange[1] - timeOffset]\r\n        var pprevTimeRange = [prevTimeRange[0] - timeOffset, prevTimeRange[1] - timeOffset]\r\n        var ppprevTimeRange = [pprevTimeRange[0] - timeOffset, pprevTimeRange[1] - timeOffset]\r\n        var statisticTimeRange = [prevTimeRange[0] - timeOffset, prevTimeRange[1] - timeOffset]\r\n\r\n        var currentRanges = [\r\n            \'currentRange0\',\r\n            \'currentRange20\',\r\n            \'currentRange21\',\r\n            \'currentRange22\'\r\n        ]\r\n        var statisticsRanges = [\r\n            \'statisticsRange9\',\r\n            \'statisticsRange10\',\r\n            \'statisticsRange11\'\r\n        ]\r\n        var prevRanges = [\r\n            \'prevRange20\',\r\n            \'prevRange21\',\r\n            \'prevRange22\'\r\n        ]\r\n\r\n        var currentRangeStr = \'\'\r\n        var prevRangeStr = \'\'\r\n        var statisticsStr = \'\'\r\n        if (isWholeDay(timeRange)) {\r\n            currentRangeStr = timestampToStr(timeRange[0]).substring(0, 10)\r\n            prevRangeStr = timestampToStr(prevTimeRange[0]).substring(0, 10)\r\n            statisticsStr = timestampToStr(statisticTimeRange[0]).substring(0, 10)\r\n        } else {\r\n            currentRangeStr = timestampToStr(timeRange[0]) + \' -- \' + timestampToStr(timeRange[1])\r\n            prevRangeStr = timestampToStr(prevTimeRange[0]) + \' -- \' + timestampToStr(prevTimeRange[1])\r\n            statisticsStr = timestampToStr(statisticTimeRange[0]) + \' -- \' + timestampToStr(statisticTimeRange[1])\r\n        }\r\n        currentRanges.forEach(c => {\r\n            var dom = document.getElementById(c)\r\n            if (dom) {\r\n                dom.innerText = currentRangeStr\r\n            }\r\n        })\r\n        prevRanges.forEach(c => {\r\n            var dom = document.getElementById(c)\r\n            if (dom) {\r\n                dom.innerText = prevRangeStr\r\n            }\r\n        })\r\n        statisticsRanges.forEach(c => {\r\n            var dom = document.getElementById(c)\r\n            if (dom) {\r\n                dom.innerText = statisticsStr\r\n            }\r\n        })\r\n    }\r\n    // Top5 流量占比 公方法\r\n    function barDataFormatHandling (total, preTotalList, ppreTotalList, list, preList, ppreList, oneLevelKey, twoLevelKey, dataKey) {\r\n        var seriesData = []\r\n        var prevSeriesData = []\r\n        var pprevSeriesData = []\r\n        var categoryData = []\r\n        if (total) {\r\n            var prevTotal = preTotalList.find(t => t[oneLevelKey] === total[oneLevelKey])\r\n            if (prevTotal) {\r\n                var pprevTotal = ppreTotalList.find(d => d[oneLevelKey] === prevTotal[oneLevelKey])\r\n            }\r\n            list.forEach(d => {\r\n                if (d[oneLevelKey] === total[oneLevelKey]) {\r\n                    categoryData.push(d[twoLevelKey])\r\n                    if (total && total[dataKey] !== 0) {\r\n                        seriesData.push(d[dataKey] / total[dataKey])\r\n                    } else {\r\n                        seriesData.push(0)\r\n                    }\r\n                    var prevTwoLevel = preList.find(p => p[twoLevelKey] === d[twoLevelKey] && p[oneLevelKey] === d[oneLevelKey])\r\n                    if (prevTwoLevel && prevTwoLevel[dataKey] && prevTotal && prevTotal[dataKey] !== 0) {\r\n                        prevSeriesData.push(prevTwoLevel[dataKey] / prevTotal[dataKey])\r\n                        var pprevTwoLevel = ppreList.find(p => p[twoLevelKey] === d[twoLevelKey] && p[oneLevelKey] === d[oneLevelKey])\r\n                        if (pprevTwoLevel && pprevTwoLevel[dataKey] && pprevTotal && pprevTotal[dataKey] !== 0) {\r\n                            pprevSeriesData.push(pprevTwoLevel[dataKey] / pprevTotal[dataKey])\r\n                        } else {\r\n                            pprevSeriesData.push(0)\r\n                        }\r\n                    } else {\r\n                        prevSeriesData.push(0)\r\n                    }\r\n                }\r\n            })\r\n        }\r\n        return {\r\n            seriesData,\r\n            prevSeriesData,\r\n            pprevSeriesData,\r\n            categoryData\r\n        }\r\n    }\r\n\r\n    function initEcharts1 () {\r\n        var seriesData1 = xxxServiceTrafficChangingCurve.map(d => [d.stat_time, d.rate])\r\n        var unit1 = \'Kbps\'\r\n\r\n        var myChart = initEchartsInstance(\'canvas1\')\r\n        var option = {\r\n            color: chartColor,\r\n            animation: false,\r\n            grid: {\r\n                left: 100,\r\n                right: 120,\r\n                bottom: 25,\r\n                top: 40\r\n            },\r\n            xAxis: {\r\n                type: \'time\',\r\n                splitNumber: 12\r\n            },\r\n            yAxis: {\r\n                splitLine: { show: false },\r\n                offset: 10,\r\n                axisLabel: {\r\n                    formatter (params) {\r\n                        return unitConvert(params, unitTypes.bps, unit1).join(\' \')\r\n                    }\r\n                }\r\n            },\r\n            series: {\r\n                type: \'line\',\r\n                symbol: \'none\',\r\n                data: seriesData1,\r\n                markLine: {\r\n                    silent: true,\r\n                    lineStyle: {\r\n                        color: \'rgb(153,153,153)\'\r\n                    },\r\n                    symbol: \'none\',\r\n                    label: {\r\n                        formatter (params) {\r\n                            var arr = unitConvert(params.value, unitTypes.bps, unit1).join(\' \')\r\n                            var desc = \'\'\r\n                            switch (params.dataIndex) {\r\n                                case 0: {\r\n                                    desc = \'P50\'\r\n                                    break\r\n                                }\r\n                                case 1: {\r\n                                    desc = \'P90\'\r\n                                    break\r\n                                }\r\n                                case 2: {\r\n                                    desc = \'P99\'\r\n                                    break\r\n                                }\r\n                                default: break\r\n                            }\r\n                            return arr + \' (\' + desc + \')\'\r\n                        }\r\n                    }\r\n                }\r\n            }\r\n        }\r\n        if (xxxServiceRate.rate99 > xxxServiceRate.rate90 && xxxServiceRate.rate90 > xxxServiceRate.rate50 && xxxServiceRate.rate50 !== 0 && xxxServiceRate.rate90 !== 0 && xxxServiceRate.rate99 !== 0){\r\n            option.visualMap = {\r\n                show: false,\r\n                pieces: [\r\n                    {\r\n                        lte: xxxServiceRate.rate50,\r\n                        color: \'rgb(251,219,15)\'\r\n                    },\r\n                    {\r\n                        gt: xxxServiceRate.rate50,\r\n                        lte: xxxServiceRate.rate90,\r\n                        color: \'rgb(252,125,2)\'\r\n                    },\r\n                    {\r\n                        gt: xxxServiceRate.rate90,\r\n                        lte: xxxServiceRate.rate99,\r\n                        color: \'rgb(253,1,0)\'\r\n                    },\r\n                    {\r\n                        gt: xxxServiceRate.rate99,\r\n                        color: \'rgb