_protocol, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND notEmpty(common_l7_protocol) AND (common_app_label IN (\'${overviewApp}\')) GROUP BY common_l7_protocol ORDER BY bytes DESC\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"top10RelatedProtocolBytes\"\r\n    },\r\n    {\r\n      \"querySql\": \"SELECT server_province AS server_province, SUM(bytes_sent) AS bytes_sent, IFNULL(ROUND(AVG(sent_rate), 4), 0) AS sent_rate_avg, IFNULL(ROUND(MAX(sent_rate), 4), 0) AS sent_rate_max, IFNULL(ROUND(MIN(sent_rate), 4), 0) AS sent_rate_min FROM ( SELECT server_province AS server_province, SUM(common_c2s_byte_num) AS bytes_sent, (bytes_sent * 8) / (300) AS sent_rate, toDateTime(toStartOfInterval(toDateTime(common_recv_time), INTERVAL 5 MINUTE)) AS granularity FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND (common_app_label IN (\'${overviewApp}\')) AND client_zone = \'internal\' AND server_zone = \'external\' AND server_province in ( SELECT server_province AS server_province FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND notEmpty(server_province) AND client_zone = \'internal\' AND server_zone = \'external\' AND (common_app_label IN (\'${overviewApp}\')) GROUP BY server_province ORDER BY SUM(common_c2s_byte_num) DESC LIMIT 10 ) GROUP BY granularity, server_province) GROUP BY server_province ORDER BY bytes_sent DESC LIMIT 10\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"provinceIn2outSentTrafficBytesTop10\"\r\n    },\r\n    {\r\n      \"querySql\": \"SELECT server_province AS server_province, SUM(bytes_sent) AS bytes_sent, IFNULL(ROUND(AVG(sent_rate), 4), 0) AS sent_rate_avg, IFNULL(ROUND(MAX(sent_rate), 4), 0) AS sent_rate_max, IFNULL(ROUND(MIN(sent_rate), 4), 0) AS sent_rate_min FROM ( SELECT server_province AS server_province, SUM(common_c