INSERT INTO `report_category` VALUES (13, 'IDC域名报告', '<!DOCTYPE html>\r\n<html lang=\"en\"><head>\r\n    <meta charset=\"UTF-8\">\r\n    <#setting number_format=\"0.####\"/>\r\n    <title>IDC 域名${domain}报告</title>\r\n    <script src=\"http://${uiStaticUrl}/assets/echarts.min.js\"></script>\r\n    <style>${reportStyleCommon}</style>\r\n</head>\r\n<body>\r\n<div class=\"header1\">IDC 域名${domain}报告<span class=\"header1__time\" id=\"currentRange0\"></span></div>\r\n<div class=\"table__footer\">\r\n    <div class=\"footer__label\">* 流量接入情况说明：</div>IDC链路共计22条，总带宽1.21Tbps（11*100Gbps、11*10Gbps）；系统实际接入链路15条，接入带宽1.14Tbps（11*100Gbps、4*10Gbps）。实际接入带宽为总带宽的94.21%。\r\n</div>\r\n<div class=\"header2\">一.整体流量概况</div>\r\n<div class=\"header3\">1.流量规模概况</div>\r\n<div class=\"table-box indent-3\">\r\n    <div class=\"table__title\">表1 IDC ${domain}整体流量概况</div>\r\n    <table class=\"table\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th class=\"table__th\">速率均值</th>\r\n            <th class=\"table__th\">速率谷值</th>\r\n            <th class=\"table__th\">速率分位值</th>\r\n            <th class=\"table__th\">速率峰值</th>\r\n            <th class=\"table__th\">速率均值环比</th>\r\n            <th class=\"table__th\">总流量</th>\r\n            <th class=\"table__th\">总流量占比</th>\r\n            <th class=\"table__th\">总流量环比</th>\r\n        </tr>\r\n        </thead>\r\n        <tbody><tr class=\"table__tr\">\r\n            <td class=\"table__td\">\r\n                ${convertNumber(getFromArr(xxxServiceRate,0,\'rate_avg\',\'number\'),\'bps\',1000)}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertNumber(getFromArr(xxxServiceRate,0,\'rate_min\',\'number\'),\'bps\',1000)}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                <div class=\"td__quantile-group\">\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p50\"></span>P50</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertNumber(getFromArr(xxxServiceRate,0,\'rate50\',\'number\'),\'bps\',1000)}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p90\"></span>P90</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertNumber(getFromArr(xxxServiceRate,0,\'rate90\',\'number\'),\'bps\',1000)}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p99\"></span>P99</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertNumber(getFromArr(xxxServiceRate,0,\'rate99\',\'number\'),\'bps\',1000)}\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertNumber(getFromArr(xxxServiceRate,0,\'rate_max\',\'number\'),\'bps\',1000)}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                <div class=\"td__quantile-group\">\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label quantile__label--ratio\">\r\n                            <div class=\"label-box\">\r\n                                <div>本期vs上期</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value quantile__value--ratio\">\r\n                            ${chainRatio(getFromArr(xxxServiceRate,0,\'rate_avg\',\'number\'),getFromArr(pre1stxxxServiceRate,0,\'rate_avg\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label quantile__label--ratio\">\r\n                            <div class=\"label-box\">\r\n                                <div>上期vs上上期</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value quantile__value--ratio\">\r\n                            ${chainRatio(getFromArr(pre1stxxxServiceRate,0,\'rate_avg\',\'number\'),getFromArr(pre2ndxxxServiceRate,0,\'rate_avg\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertNumber(getFromArr(xxxServiceTrafficTotal,0,\'bytes\',\'number\'),\'byte\',1024)}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${proportion(getFromArr(xxxServiceTrafficTotal,0,\'bytes\',\'number\'),getFromArr(trafficTotal,0,\'bytes\',\'number\'))}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                <div class=\"td__quantile-group\">\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label quantile__label--ratio\">\r\n                            <div class=\"label-box\">\r\n                                <div>本期vs上期</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value quantile__value--ratio\">\r\n                            ${chainRatio(getFromArr(xxxServiceTrafficTotal,0,\'bytes\',\'number\'),getFromArr(pre1stxxxServiceTrafficTotal,0,\'bytes\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label quantile__label--ratio\">\r\n                            <div class=\"label-box\">\r\n                                <div>上期vs上上期</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value quantile__value--ratio\">\r\n                            ${chainRatio(getFromArr(pre1stxxxServiceTrafficTotal,0,\'bytes\',\'number\'),getFromArr(pre2ndxxxServiceTrafficTotal,0,\'bytes\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n        </tr>\r\n        </tbody></table>\r\n    <div class=\"table__footer\">\r\n        <div class=\"footer__label\">* 流量速率分位值计算方式：</div>以5分钟为时间粒度计算平均流量速率vi，取观测时间范围内的{v1, v2, v3……vn}的分位值，下同。\r\n    </div>\r\n</div>\r\n<div class=\"echarts-box indent-3\">\r\n    <div class=\"echarts\">\r\n        <div class=\"echarts__canvas echarts__line\" id=\"canvas1\"></div>\r\n        <div class=\"echarts__title\">图1 当日流量变化曲线</div>\r\n    </div>\r\n</div>\r\n\r\n<div class=\"header3\">2.服务质量概况</div>\r\n<div class=\"table-box indent-3\">\r\n    <div class=\"table__title\">表2 域外访问域内${domain}的服务质量</div>\r\n    <table class=\"table\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th class=\"table__th\">服务质量指标</th>\r\n            <th class=\"table__th\">分位值</th>\r\n            <th class=\"table__th\">峰值</th>\r\n            <th class=\"table__th\">均值</th>\r\n            <th class=\"table__th\">均值环比</th>\r\n        </tr>\r\n        </thead>\r\n        <tbody><tr class=\"table__tr\">\r\n            <td class=\"table__td\">TCP会话创建延迟</td>\r\n            <td class=\"table__td\">\r\n                <div class=\"td__quantile-group\">\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p50\"></span>P50</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertTime(getFromArr(xxxServiceOut2inTcp,0,\'establish_latency_p50\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p90\"></span>P90</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertTime(getFromArr(xxxServiceOut2inTcp,0,\'establish_latency_p90\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p99\"></span>P99</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertTime(getFromArr(xxxServiceOut2inTcp,0,\'establish_latency_p99\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertTime(getFromArr(xxxServiceOut2inTcp,0,\'establish_latency_max\',\'number\'))}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertTime(getFromArr(xxxServiceOut2inTcp,0,\'establish_latency_avg\',\'number\'))}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${chainRatio(getFromArr(xxxServiceOut2inTcp,0,\'establish_latency_avg\',\'number\'),getFromArr(pre1stxxxServiceOut2inTcp,0,\'establish_latency_avg\',\'number\'))}\r\n            </td>\r\n        </tr>\r\n        <tr class=\"table__tr\">\r\n            <td class=\"table__td\">缺包率</td>\r\n            <td class=\"table__td\">\r\n                <div class=\"td__quantile-group\">\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p50\"></span>P50</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertPercent(getFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_p50\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p90\"></span>P90</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertPercent(getFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_p90\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p99\"></span>P99</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertPercent(getFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_p99\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertPercent(getFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_max\',\'number\'))}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertPercent(getFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_avg\',\'number\'))}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${chainRatio(getFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_avg\',\'number\'),getFromArr(pre1stxxxServiceOut2inLossPackets,0,\'sequence_gap_loss_avg\',\'number\'))}\r\n            </td>\r\n        </tr>\r\n        </tbody></table>\r\n</div>\r\n<div class=\"table-box indent-3\">\r\n    <div class=\"table__title\">表3 域内访问域外的${domain}的服务质量</div>\r\n    <table class=\"table\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th class=\"table__th\">服务质量指标</th>\r\n            <th class=\"table__th\">分位值</th>\r\n            <th class=\"table__th\">峰值</th>\r\n            <th class=\"table__th\">均值</th>\r\n            <th class=\"table__th\">均值环比</th>\r\n        </tr>\r\n        </thead>\r\n        <tbody><tr class=\"table__tr\">\r\n            <td class=\"table__td\">TCP会话创建延迟</td>\r\n            <td class=\"table__td\">\r\n                <div class=\"td__quantile-group\">\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p50\"></span>P50</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertTime(getFromArr(xxxServiceIn2outTcp,0,\'establish_latency_p50\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p90\"></span>P90</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertTime(getFromArr(xxxServiceIn2outTcp,0,\'establish_latency_p90\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p99\"></span>P99</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertTime(getFromArr(xxxServiceIn2outTcp,0,\'establish_latency_p99\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertTime(getFromArr(xxxServiceIn2outTcp,0,\'establish_latency_max\',\'number\'))}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertTime(getFromArr(xxxServiceIn2outTcp,0,\'establish_latency_avg\',\'number\'))}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${chainRatio(getFromArr(xxxServiceIn2outTcp,0,\'establish_latency_avg\',\'number\'),getFromArr(pre1stxxxServiceIn2outTcp,0,\'establish_latency_avg\',\'number\'))}\r\n            </td>\r\n        </tr>\r\n        <tr class=\"table__tr\">\r\n            <td class=\"table__td\">缺包率</td>\r\n            <td class=\"table__td\">\r\n                <div class=\"td__quantile-group\">\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p50\"></span>P50</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertPercent(getFromArr(xxxServiceIn2outLossPackets,0,\'sequence_gap_loss_p50\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p90\"></span>P90</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertPercent(getFromArr(xxxServiceIn2outLossPackets,0,\'sequence_gap_loss_p90\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p99\"></span>P99</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertPercent(getFromArr(xxxServiceIn2outLossPackets,0,\'sequence_gap_loss_p99\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertPercent(getFromArr(xxxServiceIn2outLossPackets,0,\'sequence_gap_loss_max\',\'number\'))}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertPercent(getFromArr(xxxServiceIn2outLossPackets,0,\'sequence_gap_loss_avg\',\'number\'))}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${chainRatio(getFromArr(xxxServiceIn2outLossPackets,0,\'sequence_gap_loss_avg\',\'number\'),getFromArr(pre1stxxxServiceIn2outLossPackets,0,\'sequence_gap_loss_avg\',\'number\'))}\r\n            </td>\r\n        </tr>\r\n        </tbody></table>\r\n</div>\r\n\r\n<div class=\"header2\">二.地理位置分布</div>\r\n<div class=\"header3\">1.各省份流量分布</div>\r\n<div class=\"echarts-box indent-3\">\r\n    <div class=\"echarts\">\r\n        <div class=\"echarts__canvas echarts__line-and-bar\" id=\"canvas2\"></div>\r\n    </div>\r\n</div>\r\n<div class=\"table-box indent-3\">\r\n    <table class=\"table\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th class=\"table__th\">各省份流量速率</th>\r\n            <#if provinceIn2outSentTrafficBytesTop10??>\r\n                <#list provinceIn2outSentTrafficBytesTop10 as val>\r\n                    <th class=\"table__th\">${getFromObj(val,\'server_province\',\'string\')}</th>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </thead>\r\n        <tbody><tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">峰值</td>\r\n            <#if provinceIn2outSentTrafficBytesTop10??>\r\n                <#list provinceIn2outSentTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'sent_rate_max\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        <tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">均值</td>\r\n            <#if provinceIn2outSentTrafficBytesTop10??>\r\n                <#list provinceIn2outSentTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'sent_rate_avg\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </tbody></table>\r\n    <div class=\"echarts__title echarts__line-and-bar-title\">图2 IDC访问各省份${domain}的Top 10 省份请求流量分布</div>\r\n</div>\r\n\r\n<div class=\"echarts-box indent-3\">\r\n    <div class=\"echarts\">\r\n        <div class=\"echarts__canvas echarts__line-and-bar\" id=\"canvas8\"></div>\r\n    </div>\r\n</div>\r\n<div class=\"table-box indent-3\">\r\n    <table class=\"table\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th class=\"table__th\">各省份流量速率</th>\r\n            <#if provinceIn2outReceivedTrafficBytesTop10??>\r\n                <#list provinceIn2outReceivedTrafficBytesTop10 as val>\r\n                    <th class=\"table__th\">${getFromObj(val,\'server_province\',\'string\')}</th>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </thead>\r\n        <tbody>\r\n        <tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">峰值</td>\r\n            <#if provinceIn2outReceivedTrafficBytesTop10??>\r\n                <#list provinceIn2outReceivedTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'received_rate_max\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        <tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">均值</td>\r\n            <#if provinceIn2outReceivedTrafficBytesTop10??>\r\n                <#list provinceIn2outReceivedTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'received_rate_avg\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </tbody></table>\r\n    <div class=\"echarts__title echarts__line-and-bar-title\">图3 IDC访问各省份${domain}的Top 10 省份响应流量分布</div>\r\n</div>\r\n\r\n<div class=\"echarts-box indent-3\">\r\n    <div class=\"echarts\">\r\n        <div class=\"echarts__canvas echarts__line-and-bar\" id=\"canvas3\"></div>\r\n    </div>\r\n</div>\r\n<div class=\"table-box indent-3\">\r\n    <table class=\"table\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th class=\"table__th\">各省份流量速率</th>\r\n            <#if provinceOut2inSentTrafficBytesTop10??>\r\n                <#list provinceOut2inSentTrafficBytesTop10 as val>\r\n                    <th class=\"table__th\">${getFromObj(val,\'client_province\',\'string\')}</th>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </thead>\r\n        <tbody><tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">峰值</td>\r\n            <#if provinceOut2inSentTrafficBytesTop10??>\r\n                <#list provinceOut2inSentTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'sent_rate_max\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        <tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">均值</td>\r\n            <#if provinceOut2inSentTrafficBytesTop10??>\r\n                <#list provinceOut2inSentTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'sent_rate_avg\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </tbody></table>\r\n    <div class=\"echarts__title echarts__line-and-bar-title\">图4 各省份访问IDC ${domain}的Top 10 省份请求流量分布</div>\r\n</div>\r\n\r\n<div class=\"echarts-box indent-3\">\r\n    <div class=\"echarts\">\r\n        <div class=\"echarts__canvas echarts__line-and-bar\" id=\"canvas9\"></div>\r\n    </div>\r\n</div>\r\n<div class=\"table-box indent-3\">\r\n    <table class=\"table\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th class=\"table__th\">各省份流量速率</th>\r\n            <#if provinceOut2inReceivedTrafficBytesTop10??>\r\n                <#list provinceOut2inReceivedTrafficBytesTop10 as val>\r\n                    <th class=\"table__th\">${getFromObj(val,\'client_province\',\'string\')}</th>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </thead>\r\n        <tbody>\r\n        <tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">峰值</td>\r\n            <#if provinceOut2inReceivedTrafficBytesTop10??>\r\n                <#list provinceOut2inReceivedTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'received_rate_max\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        <tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">均值</td>\r\n            <#if provinceOut2inReceivedTrafficBytesTop10??>\r\n                <#list provinceOut2inReceivedTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'received_rate_avg\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </tbody></table>\r\n    <div class=\"echarts__title echarts__line-and-bar-title\">图5 各省份访问IDC ${domain}的Top 10 省份响应流量分布 </div>\r\n</div>\r\n\r\n<div class=\"header3\">2.省内各地区流量分布</div>\r\n<div class=\"echarts-box indent-3\">\r\n    <div class=\"echarts\">\r\n        <div class=\"echarts__canvas echarts__line-and-bar\" id=\"canvas4\"></div>\r\n    </div>\r\n</div>\r\n<div class=\"table-box indent-3\">\r\n    <table class=\"table\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th class=\"table__th\">各地区流量速率</th>\r\n            <#if regionIdc2inSentTrafficBytesTop10??>\r\n                <#list regionIdc2inSentTrafficBytesTop10 as val>\r\n                    <th class=\"table__th\">${getFromObj(val,\'server_region\',\'string\')}</th>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </thead>\r\n        <tbody><tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">峰值</td>\r\n            <#if regionIdc2inSentTrafficBytesTop10??>\r\n                <#list regionIdc2inSentTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'sent_rate_max\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n\r\n        <tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">均值</td>\r\n            <#if regionIdc2inSentTrafficBytesTop10??>\r\n                <#list regionIdc2inSentTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'sent_rate_avg\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </tbody></table>\r\n    <div class=\"echarts__title echarts__line-and-bar-title\">图6 IDC访问省内${domain}的Top 10 省内地区请求流量分布</div>\r\n</div>\r\n\r\n<div class=\"echarts-box indent-3\">\r\n    <div class=\"echarts\">\r\n        <div class=\"echarts__canvas echarts__line-and-bar\" id=\"canvas10\"></div>\r\n    </div>\r\n</div>\r\n<div class=\"table-box indent-3\">\r\n    <table class=\"table\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th class=\"table__th\">各地区流量速率</th>\r\n            <#if regionIdc2inReceivedTrafficBytesTop10??>\r\n                <#list regionIdc2inReceivedTrafficBytesTop10 as val>\r\n                    <th class=\"table__th\">${getFromObj(val,\'server_region\',\'string\')}</th>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </thead>\r\n        <tbody>\r\n        <tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">峰值</td>\r\n            <#if regionIdc2inReceivedTrafficBytesTop10??>\r\n                <#list regionIdc2inReceivedTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'received_rate_max\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        <tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">均值</td>\r\n            <#if regionIdc2inReceivedTrafficBytesTop10??>\r\n                <#list regionIdc2inReceivedTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'received_rate_avg\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </tbody></table>\r\n    <div class=\"echarts__title echarts__line-and-bar-title\">图7 IDC访问省内${domain}的Top 10 省内地区响应流量分布</div>\r\n</div>\r\n\r\n<div class=\"echarts-box indent-3\">\r\n    <div class=\"echarts\">\r\n        <div class=\"echarts__canvas echarts__line-and-bar\" id=\"canvas5\"></div>\r\n    </div>\r\n</div>\r\n<div class=\"table-box indent-3\">\r\n    <table class=\"table\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th class=\"table__th\">各地区流量速率</th>\r\n            <#if regionIn2idcSentTrafficBytesTop10??>\r\n                <#list regionIn2idcSentTrafficBytesTop10 as val>\r\n                    <th class=\"table__th\">${getFromObj(val,\'client_region\',\'string\')}</th>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </thead>\r\n        <tbody><tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">峰值</td>\r\n            <#if regionIn2idcSentTrafficBytesTop10??>\r\n                <#list regionIn2idcSentTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'sent_rate_max\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n\r\n        <tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">均值</td>\r\n            <#if regionIn2idcSentTrafficBytesTop10??>\r\n                <#list regionIn2idcSentTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'sent_rate_avg\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </tbody></table>\r\n    <div class=\"echarts__title echarts__line-and-bar-title\">图8 省内访问IDC ${domain}的Top 10 省内地区请求流量分布 </div>\r\n</div>\r\n\r\n<div class=\"echarts-box indent-3\">\r\n    <div class=\"echarts\">\r\n        <div class=\"echarts__canvas echarts__line-and-bar\" id=\"canvas11\"></div>\r\n    </div>\r\n</div>\r\n<div class=\"table-box indent-3\">\r\n    <table class=\"table\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th class=\"table__th\">各地区流量速率</th>\r\n            <#if regionIn2idcReceivedTrafficBytesTop10??>\r\n                <#list regionIn2idcReceivedTrafficBytesTop10 as val>\r\n                    <th class=\"table__th\">${getFromObj(val,\'client_region\',\'string\')}</th>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </thead>\r\n        <tbody>\r\n        <tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">峰值</td>\r\n            <#if regionIn2idcReceivedTrafficBytesTop10??>\r\n                <#list regionIn2idcReceivedTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'received_rate_max\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        <tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">均值</td>\r\n            <#if regionIn2idcReceivedTrafficBytesTop10??>\r\n                <#list regionIn2idcReceivedTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'received_rate_avg\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </tbody></table>\r\n    <div class=\"echarts__title echarts__line-and-bar-title\">图9 省内访问IDC ${domain}的Top 10 省内地区响应流量分布</div>\r\n</div>\r\n\r\n<script>\r\n    /** 数据 begin */\r\n        // 时间区间\r\n    var timeRange = [${startTime}, ${endTime}]\r\n    // 时区偏移毫秒\r\n    var timeZoneOffset = ${timeZoneOffset}\r\n    /* 1.1 流量变化曲线 */\r\n    // 总流量\r\n    var trafficTotal = ${jsGetNumFromArr(trafficTotal,0,\'bytes\')/1024}\r\n\r\n    // IDC访问省内应用服务流量(xxxServiceIdc2intraffictotal)\r\n    var xxxServiceTrafficTotal = ${jsGetNumFromArr(xxxServiceTrafficTotal,0,\'bytes\')/1024}\r\n    //前一周期\r\n    var pre1stxxxServiceTrafficTotal = ${jsGetNumFromArr(pre1stxxxServiceTrafficTotal,0,\'bytes\')/1024}\r\n    // 前二周期\r\n    var pre2ndxxxServiceTrafficTotal = ${jsGetNumFromArr(pre2ndxxxServiceTrafficTotal,0,\'bytes\')/1024}\r\n\r\n    // IDC访问省内应用服务流量(xxxServiceIdc2intraffictotal)\r\n    var xxxServiceIdc2intraffictotal = {\r\n        bytes_sent: ${jsGetNumFromArr(xxxServiceIdc2intraffictotal,0,\'bytes_sent\')/1024},\r\n        bytes_received: ${jsGetNumFromArr(xxxServiceIdc2intraffictotal,0,\'bytes_received\')/1024},\r\n        bytes: ${jsGetNumFromArr(xxxServiceIdc2intraffictotal,0,\'bytes\')/1024}\r\n    }\r\n    //前一周期(Pre 1st xxxService Idc2in traffic total)\r\n    var Pre1stxxxServiceIdc2intraffictotal = {\r\n        bytes_sent: ${jsGetNumFromArr(Pre1stxxxServiceIdc2intraffictotal,0,\'bytes_sent\')/1024},\r\n        bytes_received: ${jsGetNumFromArr(Pre1stxxxServiceIdc2intraffictotal,0,\'bytes_received\')/1024},\r\n        bytes: ${jsGetNumFromArr(Pre1stxxxServiceIdc2intraffictotal,0,\'bytes\')/1024}\r\n    }\r\n    // 前二周期(Pre 2nd xxxService Idc2in traffic total)\r\n    var Pre2ndxxxServiceIdc2intraffictotal = {\r\n        bytes_sent: ${jsGetNumFromArr(Pre2ndxxxServiceIdc2intraffictotal,0,\'bytes_sent\')/1024},\r\n        bytes_received: ${jsGetNumFromArr(Pre2ndxxxServiceIdc2intraffictotal,0,\'bytes_received\')/1024},\r\n        bytes: ${jsGetNumFromArr(Pre2ndxxxServiceIdc2intraffictotal,0,\'bytes\')/1024}\r\n    }\r\n    // 省内访问IDC 应用服务流量(xxxService In2idc traffic total)\r\n    var xxxServiceIn2idctraffictotal = {\r\n        bytes_sent: ${jsGetNumFromArr(xxxServiceIn2idctraffictotal,0,\'bytes_sent\')/1024},\r\n        bytes_received: ${jsGetNumFromArr(xxxServiceIn2idctraffictotal,0,\'bytes_received\')/1024},\r\n        bytes: ${jsGetNumFromArr(xxxServiceIn2idctraffictotal,0,\'bytes\')/1024}\r\n    }\r\n    // 前一周期（Pre 1st xxxService In2idc traffic total）\r\n    var pre1stxxxServiceIn2idctraffictotal = {\r\n        bytes_sent: ${jsGetNumFromArr(pre1stxxxServiceIn2idctraffictotal,0,\'bytes_sent\')/1024},\r\n        bytes_received: ${jsGetNumFromArr(pre1stxxxServiceIn2idctraffictotal,0,\'bytes_received\')/1024},\r\n        bytes: ${jsGetNumFromArr(pre1stxxxServiceIn2idctraffictotal,0,\'bytes\')/1024}\r\n    }\r\n    // 前二周期(Pre 2nd xxxService In2idc traffic total)\r\n    var pre2ndxxxServiceIn2idctraffictotal = {\r\n        bytes_sent: ${jsGetNumFromArr(pre2ndxxxServiceIn2idctraffictotal,0,\'bytes_sent\')/1024},\r\n        bytes_received: ${jsGetNumFromArr(pre2ndxxxServiceIn2idctraffictotal,0,\'bytes_received\')/1024},\r\n        bytes: ${jsGetNumFromArr(pre2ndxxxServiceIn2idctraffictotal,0,\'bytes\')/1024}\r\n    }\r\n\r\n    // 省外访问省内服${domain}的服务质量\r\n    var xxxServiceOut2inTrafficTotal = {\r\n        bytes_sent: ${jsGetNumFromArr(xxxServiceOut2inTrafficTotal,0,\'bytes_sent\')/1024},\r\n        bytes_received: ${jsGetNumFromArr(xxxServiceOut2inTrafficTotal,0,\'bytes_received\')/1024},\r\n        bytes: ${jsGetNumFromArr(xxxServiceOut2inTrafficTotal,0,\'bytes\')/1024}\r\n    }\r\n    // 前一周期(Pre 1st xxxService ZA traffic total)\r\n    var Pre1stxxxServiceOut2inTrafficTotal = {\r\n        bytes_sent: ${jsGetNumFromArr(Pre1stxxxServiceOut2inTrafficTotal,0,\'bytes_sent\')/1024},\r\n        bytes_received: ${jsGetNumFromArr(Pre1stxxxServiceOut2inTrafficTotal,0,\'bytes_received\')/1024},\r\n        bytes: ${jsGetNumFromArr(Pre1stxxxServiceOut2inTrafficTotal,0,\'bytes\')/1024}\r\n    }\r\n    // 前二周期(Pre 2nd xxxService ZA traffic total)\r\n    var Pre2ndxxxServiceOut2inTrafficTotal = {\r\n        bytes_sent: ${jsGetNumFromArr(Pre2ndxxxServiceOut2inTrafficTotal,0,\'bytes_sent\')/1024},\r\n        bytes_received: ${jsGetNumFromArr(Pre2ndxxxServiceOut2inTrafficTotal,0,\'bytes_received\')/1024},\r\n        bytes: ${jsGetNumFromArr(Pre2ndxxxServiceOut2inTrafficTotal,0,\'bytes\')/1024}\r\n    }\r\n    // 省内访问省外${domain}服务流量\r\n    var xxxServiceIn2outTrafficTotal = {\r\n        bytes_sent: ${jsGetNumFromArr(xxxServiceIn2outTrafficTotal,0,\'bytes_sent\')/1024},\r\n        bytes_received: ${jsGetNumFromArr(xxxServiceIn2outTrafficTotal,0,\'bytes_received\')/1024},\r\n        bytes: ${jsGetNumFromArr(xxxServiceIn2outTrafficTotal,0,\'bytes\')/1024}\r\n    }\r\n    var pre1stxxxServiceIn2outTrafficTotal = {\r\n        bytes_sent: ${jsGetNumFromArr(pre1stxxxServiceIn2outTrafficTotal,0,\'bytes_sent\')/1024},\r\n        bytes_received: ${jsGetNumFromArr(pre1stxxxServiceIn2outTrafficTotal,0,\'bytes_received\')/1024},\r\n        bytes: ${jsGetNumFromArr(pre1stxxxServiceIn2outTrafficTotal,0,\'bytes\')/1024}\r\n    }\r\n    var pre2ndxxxServiceIn2outTrafficTotal = {\r\n        bytes_sent: ${jsGetNumFromArr(pre2ndxxxServiceIn2outTrafficTotal,0,\'bytes_sent\')/1024},\r\n        bytes_received: ${jsGetNumFromArr(pre2ndxxxServiceIn2outTrafficTotal,0,\'bytes_received\')/1024},\r\n        bytes: ${jsGetNumFromArr(pre2ndxxxServiceIn2outTrafficTotal,0,\'bytes\')/1024}\r\n    }\r\n    // ${domain}服务速率\r\n    var xxxServiceRate = {\r\n        rate50: ${jsGetNumFromArr(xxxServiceRate,0,\'rate50\')/1000},\r\n        rate90: ${jsGetNumFromArr(xxxServiceRate,0,\'rate90\')/1000},\r\n        rate99: ${jsGetNumFromArr(xxxServiceRate,0,\'rate99\')/1000},\r\n        rate_avg:${jsGetNumFromArr(xxxServiceRate,0,\'rate_avg\')/1000},\r\n        rate_max:${jsGetNumFromArr(xxxServiceRate,0,\'rate_max\')/1000},\r\n        rate_min:${jsGetNumFromArr(xxxServiceRate,0,\'rate_min\')/1000}\r\n    }\r\n    var pre1stxxxServiceRate = {\r\n        rate50: ${jsGetNumFromArr(pre1stxxxServiceRate,0,\'rate50\')/1000},\r\n        rate90: ${jsGetNumFromArr(pre1stxxxServiceRate,0,\'rate90\')/1000},\r\n        rate99: ${jsGetNumFromArr(pre1stxxxServiceRate,0,\'rate99\')/1000},\r\n        rate_avg:${jsGetNumFromArr(pre1stxxxServiceRate,0,\'rate_avg\')/1000},\r\n        rate_max:${jsGetNumFromArr(pre1stxxxServiceRate,0,\'rate_max\')/1000},\r\n        rate_min:${jsGetNumFromArr(pre1stxxxServiceRate,0,\'rate_min\')/1000}\r\n    }\r\n    var pre2ndxxxServiceRate = {\r\n        rate50: ${jsGetNumFromArr(pre2ndxxxServiceRate,0,\'rate50\')/1000},\r\n        rate90: ${jsGetNumFromArr(pre2ndxxxServiceRate,0,\'rate90\')/1000},\r\n        rate99: ${jsGetNumFromArr(pre2ndxxxServiceRate,0,\'rate99\')/1000},\r\n        rate_avg:${jsGetNumFromArr(pre2ndxxxServiceRate,0,\'rate_avg\')/1000},\r\n        rate_max:${jsGetNumFromArr(pre2ndxxxServiceRate,0,\'rate_max\')/1000},\r\n        rate_min:${jsGetNumFromArr(pre2ndxxxServiceRate,0,\'rate_min\')/1000}\r\n    }\r\n    // ${domain}服务当日流量变化曲线\r\n    var xxxServiceTrafficChangingCurve = [\r\n        <#if xxxServiceTraf