ing\')}\',bytes_received:${jsGetNumFromObj(d,\'bytes_received\')/1024},received_rate_avg:${jsGetNumFromObj(d,\'received_rate_avg\')/1000},received_rate_max:${jsGetNumFromObj(d,\'received_rate_max\')/1000},received_rate_min:${jsGetNumFromObj(d,\'received_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n    // 前一周期(Pre 1st Region AZ Received Traffic Bytes Top 10)\r\n    var pre1stRegionIdc2inReceivedTrafficBytesTop10 = [\r\n        <#if pre1stRegionIdc2inReceivedTrafficBytesTop10??>\r\n        <#list pre1stRegionIdc2inReceivedTrafficBytesTop10 as d>\r\n        {server_region:\'${getFromObj(d,\'server_region\',\'string\')}\',bytes_received:${jsGetNumFromObj(d,\'bytes_received\')/1024},received_rate_avg:${jsGetNumFromObj(d,\'received_rate_avg\')/1000},received_rate_max:${jsGetNumFromObj(d,\'received_rate_max\')/1000},received_rate_min:${jsGetNumFromObj(d,\'received_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n    // 前二周期(Pre 2nd Region In2out Received Traffic Bytes Top 10)\r\n    var pre2ndRegionIdc2inReceivedTrafficBytesTop10 = [\r\n        <#if pre2ndRegionIdc2inReceivedTrafficBytesTop10??>\r\n        <#list pre2ndRegionIdc2inReceivedTrafficBytesTop10 as d>\r\n        {server_region:\'${getFromObj(d,\'server_region\',\'string\')}\',bytes_received:${jsGetNumFromObj(d,\'bytes_received\')/1024},received_rate_avg:${jsGetNumFromObj(d,\'received_rate_avg\')/1000},received_rate_max:${jsGetNumFromObj(d,\'received_rate_max\')/1000},received_rate_min:${jsGetNumFromObj(d,\'received_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n    // Top 10省内各地区流量分布（省外访问省内${domain}服务）\r\n    var regionIn2idcSentTrafficBytesTop10 = [\r\n        <#if regionIn2idcSentTrafficBytesTop10??>\r\n        <#list regionIn2idcSentTrafficBytesTop10 as d>\r\n        {client_region:\'${getFromObj(d,\'client_region\',\'string\')}\',bytes_sent:${jsGetNumFromObj(d,\'bytes_sent\')/1024},sent_rate_avg:${jsGetNumFromObj(d,\'sent_rate_avg\')/1000},sent_rate_max:${jsGetNumFromObj(d,\'sent_rate_max\')/1000},sent_rate_min:${jsGetNumFromObj(d,\'sent_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n    // 前一周期(Pre 1st Region Out2in Sent Traffic Bytes Top 10)\r\n    var pre1stRegionIn2idcSentTrafficBytesTop10 = [\r\n        <#if pre1stRegionIn2idcSentTrafficBytesTop10??>\r\n        <#list pre1stRegionIn2idcSentTrafficBytesTop10 as d>\r\n        {client_region:\'${getFromObj(d,\'client_region\',\'string\')}\',bytes_sent:${jsGetNumFromObj(d,\'bytes_sent\')/1024},sent_rate_avg:${jsGetNumFromObj(d,\'sent_rate_avg\')/1000},sent_rate_max:${jsGetNumFromObj(d,\'sent_rate_max\')/1000},sent_rate_min:${jsGetNumFromObj(d,\'sent_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n    // 前二周期(Pre 2nd Region Out2in Sent Traffic Bytes Top 10)\r\n    var pre2ndRegionIn2idcSentTrafficBytesTop10 = [\r\n        <#if pre2ndRegionIn2idcSentTrafficBytesTop10??>\r\n        <#list pre2ndRegionIn2idcSentTrafficBytesTop10 as d>\r\n        {client_region:\'${getFromObj(d,\'client_region\',\'string\')}\',bytes_sent:${jsGetNumFromObj(d,\'bytes_sent\')/1024},sent_rate_avg:${jsGetNumFromObj(d,\'sent_rate_avg\')/1000},sent_rate_max:${jsGetNumFromObj(d,\'sent_rate_max\')/1000},sent_rate_min:${jsGetNumFromObj(d,\'sent_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n    // 省外访问省内${domain}服务 TOP 10 省内地区响应流量分布(Region Out2in Received Traffic Bytes Top 10)\r\n    var regionIn2idcReceivedTrafficBytesTop10 = [\r\n        <#if regionIn2idcReceivedTrafficBytesTop10??>\r\n        <#list regionIn2idcReceivedTrafficBytesTop10 as d>\r\n        {client_region:\'${getFromObj(d,\'client_region\',\'string\')}\',bytes_received:${jsGetNumFromObj(d,\'bytes_received\')/1024},received_rate_avg:${jsGetNumFromObj(d,\'received_rate_avg\')/1000},received_rate_max:${jsGetNumFromObj(d,\'received_rate_max\')/1000},received_rate_min:${jsGetNumFromObj(d,\'received_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n    // 前一周期(Pre 1st Region Out2in Received Traffic Bytes Top 10)\r\n    var pre1stRegionIn2idcReceivedTrafficBytesTop10 = [\r\n        <#if pre1stRegionIn2idcReceivedTrafficBytesTop10??>\r\n        <#list pre1stRegionIn2idcReceivedTrafficBytesTop10 as d>\r\n        {client_region:\'${getFromObj(d,\'client_region\',\'string\')}\',bytes_received:${jsGetNumFromObj(d,\'bytes_received\')/1024},received_rate_avg:${jsGetNumFromObj(d,\'received_rate_avg\')/1000},received_rate_max:${jsGetNumFromObj(d,\'received_rate_max\')/1000},received_rate_min:${jsGetNumFromObj(d,\'received_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n    // 前二周期(Pre 2nd Region Out2in Received Traffic Bytes Top 10)\r\n    var pre2ndRegionIn2idcReceivedTrafficBytesTop10 = [\r\n        <#if pre2ndRegionIn2idcReceivedTrafficBytesTop10??>\r\n        <#list pre2ndRegionIn2idcReceivedTrafficBytesTop10 as d>\r\n        {client_region:\'${getFromObj(d,\'client_region\',\'string\')}\',bytes_received:${jsGetNumFromObj(d,\'bytes_received\')/1024},received_rate_avg:${jsGetNumFromObj(d,\'received_rate_avg\')/1000},received_rate_max:${jsGetNumFromObj(d,\'received_rate_max\')/1000},received_rate_min:${jsGetNumFromObj(d,\'received_rate_min\')/1000}},\r\n        </#list>\r\n        </#if>\r\n    ]\r\n\r\n    /** 数据 end */\r\n\r\n    ${reportJsCommon}\r\n\r\n\r\n    if (!isNaN(parseInt(timeZoneOffset))) {\r\n        var explorerTimeOffset = new Date().getTimezoneOffset() * 60 * 1000\r\n        xxxServiceTrafficChangingCurve = xxxServiceTrafficChangingCurve.map(d => ({ rate: d.rate, stat_time: d.stat_time + explorerTimeOffset + timeZoneOffset}))\r\n        timeRange = [timeRange[0] + explorerTimeOffset / 1000 + timeZoneOffset / 1000, timeRange[1] + explorerTimeOffset / 1000 + timeZoneOffset / 1000]\r\n    }\r\n    // 计算出前三个周期的时间戳范围，填充时间\r\n    function initTimeRange () {\r\n        var timeOffset = timeRange[1] - timeRange[0]\r\n        var wholeTimeOffset = [60 * 60 - 1, 60 * 60 * 24 - 1, 60 * 60 * 24 * 7 - 1]\r\n        if (wholeTimeOffset.indexOf(timeOffset) > -1) {\r\n            timeOffset++\r\n        }\r\n        var prevTimeRange = [timeRange[0] - timeOffset, timeRange[1] - timeOffset]\r\n        var pprevTimeRange = [prevTimeRange[0] - timeOffset, prevTimeRange[1] - timeOffset]\r\n        var ppprevTimeRange = [pprevTimeRange[0] - timeOffset, pprevTimeRange[1] - timeOffset]\r\n        var statisticTimeRange = [prevTimeRange[0] - timeOffset, prevTimeRange[1] - timeOffset]\r\n\r\n        var currentRanges = [\r\n            \'currentRange0\',\r\n            \'currentRange20\',\r\n            \'currentRange21\',\r\n            \'currentRange22\'\r\n        ]\r\n        var statisticsRanges = [\r\n            \'statisticsRange9\',\r\n            \'statisticsRange10\',\r\n            \'statisticsRange11\'\r\n        ]\r\n        var prevRanges = [\r\n            \'prevRange20\',\r\n            \'prevRange21\',\r\n            \'prevRange22\'\r\n        ]\r\n\r\n        var currentRangeStr = \'\'\r\n        var prevRangeStr = \'\'\r\n        var statisticsStr = \'\'\r\n        if (isWholeDay(timeRange)) {\r\n            currentRangeStr = timestampToStr(timeRange[0]).substring(0, 10)\r\n            prevRangeStr = timestampToStr(prevTimeRange[0]).substring(0, 10)\r\n            statisticsStr = timestampToStr(statisticTimeRange[0]).substring(0, 10)\r\n        } else {\r\n            currentRangeStr = timestampToStr(timeRange[0]) + \' -- \' + timestampToStr(timeRange[1])\r\n            prevRangeStr = timestampToStr(prevTimeRange[0]) + \' -- \' + timestampToStr(prevTimeRange[1])\r\n            statisticsStr = timestampToStr(statisticTimeRange[0]) + \' -- \' + timestampToStr(statisticTimeRange[1])\r\n        }\r\n        currentRanges.forEach(c => {\r\n            var dom = document.getElementById(c)\r\n            if (dom) {\r\n                dom.innerText = currentRangeStr\r\n            }\r\n        })\r\n        prevRanges.forEach(c => {\r\n            var dom = document.getElementById(c)\r\n            if (dom) {\r\n                dom.innerText = prevRangeStr\r\n            }\r\n        })\r\n        statisticsRanges.forEach(c => {\r\n            var dom = document.getElementById(c)\r\n            if (dom) {\r\n                dom.innerText = statisticsStr\r\n            }\r\n        })\r\n    }\r\n    // Top5 流量占比 公方法\r\n    function barDataFormatHandling (total, preTotalList, ppreTotalList, list, preList, ppreList, oneLevelKey, twoLevelKey, dataKey) {\r\n        var seriesData = []\r\n        var prevSeriesData = []\r\n        var pprevSeriesData = []\r\n        var categoryData = []\r\n        if (total) {\r\n            var prevTotal = preTotalList.find(t => t[oneLevelKey] === total[oneLevelKey])\r\n            if (prevTotal) {\r\n                var pprevTotal = ppreTotalList.find(d => d[oneLevelKey] === prevTotal[oneLevelKey])\r\n            }\r\n            list.forEach(d => {\r\n                if (d[oneLevelKey] === total[oneLevelKey]) {\r\n                    categoryData.push(d[twoLevelKey])\r\n                    if (total && total[dataKey] !== 0) {\r\n                        seriesData.push(d[dataKey] / total[dataKey])\r\n                    } else {\r\n                        seriesData.push(0)\r\n                    }\r\n                    var prevTwoLevel = preList.find(p => p[twoLevelKey] === d[twoLevelKey] && p[oneLevelKey] === d[oneLevelKey])\r\n                    if (prevTwoLevel && prevTwoLevel[dataKey] && prevTotal && prevTotal[dataKey] !== 0) {\r\n                        prevSeriesData.push(prevTwoLevel[dataKey] / prevTotal[dataKey])\r\n                        var pprevTwoLevel = ppreList.find(p => p[twoLevelKey] === d[twoLevelKey] && p[oneLevelKey] === d[oneLevelKey])\r\n                        if (pprevTwoLevel && pprevTwoLevel[dataKey] && pprevTotal && pprevTotal[dataKey] !== 0) {\r\n                            pprevSeriesData.push(pprevTwoLevel[dataKey] / pprevTotal[dataKey])\r\n                        } else {\r\n                            pprevSeriesData.push(0)\r\n                        }\r\n                    } else {\r\n                        prevSeriesData.push(0)\r\n                    }\r\n                }\r\n            })\r\n        }\r\n        return {\r\n            seriesData,\r\n            prevSeriesData,\r\n            pprevSeriesData,\r\n            categoryData\r\n        }\r\n    }\r\n\r\n    function initEcharts1 () {\r\n        var seriesData1 = xxxServiceTrafficChangingCurve.map(d => [d.stat_time, d.rate])\r\n        var unit1 = \'Kbps\'\r\n\r\n        var myChart = initEchartsInstance(\'canvas1\')\r\n        var option = {\r\n            color: chartColor,\r\n            animation: false,\r\n            grid: {\r\n                left: 100,\r\n                right: 120,\r\n                bottom: 25,\r\n                top: 40\r\n            },\r\n            xAxis: {\r\n                type: \'time\',\r\n                splitNumber: 12\r\n            },\r\n            yAxis: {\r\n                splitLine: { show: false },\r\n                offset: 10,\r\n                axisLabel: {\r\n                    formatter (params) {\r\n                        return unitConvert(params, unitTypes.bps, unit1).join(\' \')\r\n                    }\r\n                }\r\n            },\r\n            series: {\r\n                type: \'line\',\r\n                symbol: \'none\',\r\n                data: seriesData1,\r\n                markLine: {\r\n                    silent: true,\r\n                    lineStyle: {\r\n                        color: \'rgb(153,153,153)\'\r\n                    },\r\n                    symbol: \'none\',\r\n                    label: {\r\n                        formatter (params) {\r\n                            var arr = unitConvert(params.value, unitTypes.bps, unit1).join(\' \')\r\n                            var desc = \'\'\r\n                            switch (params.dataIndex) {\r\n                                case 0: {\r\n                                    desc = \'P50\'\r\n                                    break\r\n                                }\r\n                                case 1: {\r\n                                    desc = \'P90\'\r\n                                    break\r\n                                }\r\n                                case 2: {\r\n                                    desc = \'P99\'\r\n                                    break\r\n                                }\r\n                                default: break\r\n                            }\r\n                            return arr + \' (\' + desc + \')\'\r\n                        }\r\n                    }\r\n                }\r\n            }\r\n        }\r\n        if (xxxServiceRate.rate99 > xxxServiceRate.rate90 && xxxServiceRate.rate90 > xxxServiceRate.rate50 && xxxServiceRate.rate50 !== 0 && xxxServiceRate.rate90 !== 0 && xxxServiceRate.rate99 !== 0){\r\n            option.visualMap = {\r\n                show: false,\r\n                pieces: [\r\n                    {\r\n                        lte: xxxServiceRate.rate50,\r\n                        color: \'rgb(251,219,15)\'\r\n                    },\r\n                    {\r\n                        gt: xxxServiceRate.rate50,\r\n                        lte: xxxServiceRate.rate90,\r\n                        color: \'rgb(252,125,2)\'\r\n                    },\r\n                    {\r\n                        gt: xxxServiceRate.rate90,\r\n                        lte: xxxServiceRate.rate99,\r\n                        color: \'rgb(253,1,0)\'\r\n                    },\r\n                    {\r\n                        gt: xxxServiceRate.rate99,\r\n                        color: \'rgb(170,6,159)\'\r\n                    }\r\n                ],\r\n                outOfRange: {\r\n                    color: \'rgb(153,153,153)\'\r\n                }\r\n            }\r\n            option.series.markLine.data = [\r\n                {\r\n                    yAxis: xxxServiceRate.rate50\r\n                },\r\n                {\r\n                    yAxis: xxxServiceRate.rate90\r\n                },\r\n                {\r\n                    yAxis: xxxServiceRate.rate99\r\n                }\r\n            ]\r\n        }\r\n        myChart.setOption(option)\r\n    }\r\n    var barOption1 = {\r\n        animation: false,\r\n        grid: {\r\n            top: 50,\r\n            bottom: 25,\r\n            right: 40,\r\n            left: 70\r\n        },\r\n        legend: {\r\n            show: true,\r\n            top: \'top\',\r\n            left: \'left\'\r\n        },\r\n        xAxis: {\r\n            type: \'category\',\r\n            axisLabel: {\r\n                interval: 0,\r\n                fontSize: 12\r\n            }\r\n        },\r\n        yAxis: [\r\n            {\r\n                name: \'流量\',\r\n                nameTextStyle: {\r\n                    color: \'transparent\'\r\n                },\r\n                type: \'value\',\r\n                axisLabel: {\r\n                    formatter (value) {\r\n                        return unitConvert(value, unitTypes.byte, \'KB\').join(\'\')\r\n                    }\r\n                }\r\n            },\r\n            {\r\n                show: false,\r\n                name: \'环比\',\r\n                type: \'value\'\r\n            }\r\n        ],\r\n        series: [\r\n            {\r\n                name: \'请求流量\',\r\n                barMinHeight: 5,\r\n                type: \'bar\',\r\n                barWidth: 40,\r\n                label: {\r\n                    show: true,\r\n                    formatter: function (param) {\r\n                        return unitConvert(param.value, unitTypes.byte, \'KB\').join(\'\') + \'\\n\' + unitConvert(param.data.percent, unitTypes.percent).join(\'\')\r\n                    },\r\n                    distance: 3,\r\n    