\n        },\r\n        </#list>\r\n        </#if>\r\n    ]\r\n\r\n    // 下行链路TopNProvince-上上周期\r\n    var pre2ndLinkIngressTrafficTopNProvinceIn2OutTY = [\r\n        <#if pre2ndLinkIngressTrafficTopNProvinceIn2OutTY??>\r\n        <#list pre2ndLinkIngressTrafficTopNProvinceIn2OutTY as d>\r\n        {\r\n            ingress_link_direction:\'${getFromObj(d,\'ingress_link_direction\',\'string\')}\',\r\n            server_province:\'${getFromObj(d,\'server_province\',\'string\')}\',\r\n            ingress_bytes:${jsGetNumFromObj(d,\'ingress_bytes\')/1024},\r\n            sessions:${jsGetNumFromObj(d,\'sessions\')}\r\n        },\r\n        </#list>\r\n        </#if>\r\n    ]\r\n\r\n    // 西安链路TopN 省份统计\r\n    // 上行链路TopN Province-本周期\r\n    var linkEgressTrafficTopNProvinceIn2OutXA = [\r\n        <#if linkEgressTrafficTopNProvinceIn2OutXA??>\r\n        <#list linkEgressTrafficTopNProvinceIn2OutXA as d>\r\n        {\r\n            egress_link_direction:\'${getFromObj(d,\'egress_link_direction\',\'string\')}\',\r\n            server_province:\'${getFromObj(d,\'server_province\',\'string\')}\',\r\n            egress_bytes:${jsGetNumFromObj(d,\'egress_bytes\')/1024},\r\n            sessions:${jsGetNumFromObj(d,\'sessions\')}\r\n        },\r\n        </#list>\r\n        </#if>\r\n    ]\r\n\r\n    // 上行链路TopNProvince-上周期\r\n    var pre1stLinkEgressTrafficTopNProvinceIn2OutXA = [\r\n        <#if pre1stLinkEgressTrafficTopNProvinceIn2OutXA??>\r\n        <#list pre1stLinkEgressTrafficTopNProvinceIn2OutXA as d>\r\n        {\r\n            egress_link_direction:\'${getFromObj(d,\'egress_link_direction\',\'string\')}\',\r\n            server_province:\'${getFromObj(d,\'server_province\',\'string\')}\',\r\n            egress_bytes:${jsGetNumFromObj(d,\'egress_bytes\')/1024},\r\n            sessions:${jsGetNumFromObj(d,\'sessions\')}\r\n        },\r\n        </#list>\r\n        </#if>\r\n    ]\r\n\r\n    // 上行链路TopNProvince-上上周期\r\n    var pre2ndLinkEgressTrafficTopNProvinceIn2OutXA =