 第二条线\r\n        var lineSeriesData2_2 = []\r\n        provinceIn2outSentTrafficBytesTop10.forEach(t => {\r\n            var findData = pre1stProvinceIn2outSentTrafficBytesTop10.find(pt => pt.server_province === t.server_province)\r\n            if (findData && findData.bytes_sent) {\r\n                lineSeriesData1_2.push(findData.bytes_sent === 0 ? 0 : parseFloat(((t.bytes_sent - findData.bytes_sent) / parseFloat(findData.bytes_sent) * 100).toFixed(2)))\r\n                var findData2 = pre2ndProvinceIn2outSentTrafficBytesTop10.find(ppt => findData.server_province === ppt.server_province)\r\n                if (findData2 && findData2.bytes_sent) {\r\n                    lineSeriesData2_2.push(findData2.bytes_sent === 0 ? 0 : parseFloat(((findData.bytes_sent - findData2.bytes_sent) / parseFloat(findData2.bytes_sent) * 100).toFixed(2)))\r\n                } else {\r\n                    lineSeriesData2_2.push(0)\r\n                }\r\n            } else {\r\n                lineSeriesData1_2.push(0)\r\n                lineSeriesData2_2.push(0)\r\n            }\r\n        })\r\n        var copyLineSeriesData2 = [...lineSeriesData1_2, ...lineSeriesData2_2]\r\n        var copyBarSeriesData2 = [...barSeriesData2]\r\n        copyLineSeriesData2.sort((a, b) => a - b)\r\n        copyBarSeriesData2.sort((a, b) => a.value - b.value)\r\n        var barMax2 = copyBarSeriesData2.length > 0 ? copyBarSeriesData2[copyBarSeriesData2.length - 1].value : 50\r\n        var lineMin2 = copyLineSeriesData2[0] ? copyLineSeriesData2[0] : 0\r\n        var lineMax2 = copyLineSeriesData2.length > 0 ? copyLineSeriesData2[copyLineSeriesData2.length - 1] : 0\r\n        if (lineMin2 == 0 && lineMin2 == lineMax2) {\r\n            lineMin2 = -5\r\n            lineMax2 = 1\r\n        } else {\r\n            var tempLineMin2 = lineMin2\r\n            lineMin2 = lineMin2 - 2.5 * (lineMax2 - lineMin2)\r\n            lineMax2 = lineMax2 + 0.5 * (lineMax2 - tempLineMin2)\r\n        }\r\n\r\n\r\n     