)\r\n            var bytesAll = 0\r\n            pieDomainData13 = businessDistributionDomainData13.map(t => {\r\n                bytesAll += t.bytes\r\n                return {\r\n                    value: t.bytes === 0 ? 0 : t.bytes / total13.bytes,\r\n                    name: t.domain || \'null\'\r\n                }\r\n            })\r\n            pieDomainData13.push({ name: \'other\', value: (total13.bytes - bytesAll) / total13.bytes })\r\n        }\r\n        var myChart = initEchartsInstance(\'canvas13\')\r\n        var option = deepClone(pieOption)\r\n        option.series[0].data = pieDomainData13\r\n        myChart.setOption(option)\r\n    }\r\n    function initEcharts18 () {\r\n        var total18 = top10RelatedProtocolBytes.find(b => b.l7_protocol === \'total\')\r\n        if (total18) {\r\n            var pieDomainData18 = []\r\n            var businessDistributionDomainData18 = top10RelatedProtocolBytes.filter(t => t.l7_protocol !== \'total\')\r\n            var bytesAll = 0\r\n            pieDomainData18 = businessDistributionDomainData18.map(t => {\r\n                bytesAll += t.bytes\r\n                return {\r\n                    value: t.bytes === 0 ? 0 : t.bytes / total18.bytes,\r\n                    name: t.l7_protocol || \'null\'\r\n                }\r\n            })\r\n            pieDomainData18.push({ name: \'other\', value: (total18.bytes - bytesAll) / total18.bytes })\r\n        }\r\n        var myChart = initEchartsInstance(\'canvas18\')\r\n        var option = deepClone(pieOption)\r\n        option.series[0].data = pieDomainData18\r\n        myChart.setOption(option)\r\n    }\r\n\r\n    var sankeyOption = {\r\n        animation: false,\r\n        series: [\r\n            {\r\n                type: \'sankey\',\r\n                layout: \'none\',\r\n                emphasis: {\r\n                    disabled: true\r\n                },\r\n                lineStyle: {\r\n                    color: \'gradient\',\r\n                    curveness: 0.5\r\n                }\r\n            }\r\n        ]\r\n    }\r\n    var barOption = {\r\n        animation: false,\r\n        color: [chartColor[12], chartColor[6], chartColor[1]],\r\n        grid: {\r\n            top: 30,\r\n            bottom: 35,\r\n            right: 20,\r\n            left: 70\r\n        },\r\n        xAxis: {\r\n            type: \'category\',\r\n            axisLabel: {\r\n                interval: 0,\r\n                rotate: 20,\r\n                fontSize: 12\r\n            }\r\n        },\r\n        yAxis: {\r\n            type: \'value\',\r\n            axisLabel: {\r\n                formatter (value) {\r\n                    return unitConvert(value, unitTypes.percent).join(\'\')\r\n                }\r\n            }\r\n        },\r\n        series: [\r\n            {\r\n                type: \'bar\',\r\n                barWidth: 10,\r\n                barMinHeight: 2\r\n            },\r\n            {\r\n                type: \'bar\',\r\n                barWidth: 10,\r\n                barMinHeight: 2\r\n            },\r\n            {\r\n                type: \'bar\',\r\n                barWidth: 10,\r\n                barMinHeight: 2\r\n            }\r\n        ]\r\n    }\r\n\r\n    try { initEcharts1() } catch (e) { console.error(e) }\r\n    try { initEcharts2() } catch (e) { console.error(e) }\r\n    try { initEcharts3() } catch (e) { console.error(e) }\r\n    try { initEcharts4() } catch (e) { console.error(e) }\r\n    try { initEcharts5() } catch (e) { console.error(e) }\r\n    try { initEcharts8() } catch (e) { console.error(e) }\r\n    try { initEcharts9() } catch (e) { console.error(e) }\r\n    try { initEcharts10() } catch (e) { console.error(e) }\r\n    try { initEcharts11() } catch (e) { console.error(e) }\r\n    try { initEcharts13() } catch (e) { console.error(e) }\r\n    try { initEcharts18() } catch (e) { console.error(e) }\r\n    try { initTimeRange() } catch (e) { console.error(e) }\r\n</script>