RVAL 5 MINUTE)) AS granularity FROM session_record_cn WHERE common_recv_time >= ${startTime} - 2*${timeDiff} AND common_recv_time < ${endTime} - 2*${timeDiff} AND (has(client_ip_tags,\'${ipTag}\')) AND server_region in ( SELECT server_region AS server_region FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND server_region IN (\'IDC\', \'IPTV\', \'VBAS测试\', \'阿克苏\', \'阿勒泰\', \'巴州\', \'博州\', \'昌吉\', \'哈密\', \'和田\', \'喀什\', \'克拉玛依\', \'克州\', \'奎屯\', \'区公司\', \'石河子\',\'塔城\', \'吐鲁番\', \'乌鲁木齐\', \'伊犁\', \'移动互联网\', \'移动网\',\'预留\') AND (has(client_ip_tags,\'${ipTag}\')) GROUP BY server_region ORDER BY SUM(common_s2c_byte_num) DESC LIMIT 10 ) GROUP BY granularity, server_region) GROUP BY server_region ORDER BY bytes_received DESC LIMIT 10\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"pre2ndRegionIdc2inReceivedTrafficBytesTop10\"\r\n    }\r\n  ]\r\n}', 0, '2023-03-08 17:58:55', 1, '2023-03-08 17:58:59', NULL);
INSERT INTO `report_category` VALUES (20, 'IDC IP标签报告new', '<!DOCTYPE html>\r\n<html lang=\"en\"><head>\r\n    <meta charset=\"UTF-8\">\r\n    <#setting number_format=\"0.####\"/>\r\n    <title>IP标签（${ipTag}）报告</title>\r\n    <script src=\"http://${uiStaticUrl}/assets/echarts.min.js\"></script>\r\n    <style>${reportStyleCommon}</style>\r\n</head>\r\n<body>\r\n<div class=\"header1\">IP标签（${ipTag}）报告<span class=\"header1__time\" id=\"currentRange0\"></span></div>\r\n<div class=\"table__footer\">\r\n    <div class=\"footer__label\">* 流量接入情况说明：</div>IDC链路共计22条，总带宽1.21Tbps（11*100Gbps、11*10Gbps）；系统实际接入链路15条，接入带宽1.14Tbps（11*100Gbps、4*10Gbps）。实际接入带宽为总带宽的94.21%。\r\n</div>\r\n<div class=\"header2\">一.整体流量概况</div>\r\n<div class=\"header3\">1.流量规模概况</div>\r\n<div class=\"table-box indent-3\">\r\n    <div class=\"table__title\">表1 ${ipTag}IP整体流量概况</div>\r\n    <table class=\"table\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th class=\"table__th\">速率均值</th>\r\n            <th class=\"table__th\">速率谷值</th>\r\n            <th class=\"table__th\">速率分位值</th>\r\n            <th class=\"table__th\">速率峰值</th>\r\n            <th class=\"table__th\">速率均值环比</th>\r\n            <th class=\"table__th\">总流量</th>\r\n            <th class=\"table__th\">总流量占比</th>\r\n            <th class=\"table__th\">总流量环比</th>\r\n        </tr>\r\n        </thead>\r\n        <tbody><tr class=\"table__tr\">\r\n            <td class=\"table__td\">\r\n                ${convertNumber(getFromArr(xxxServiceRate,0,\'rate_avg\',\'number\'),\'bps\',1000)}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertNumber(getFromArr(xxxServiceRate,0,\'rate_min\',\'number\'),\'bps\',1000)}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                <div class=\"td__quantile-group\">\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p50\"></span>P50</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertNumber(getFromArr(xxxServiceRate,0,\'rate50\',\'number\'),\'bps\',1000)}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p90\"></span>P90</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertNumber(getFromArr(xxxServiceRate,0,\'rate90\',\'number\'),\'bps\',1000)}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p99\"></span>P99</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertNumber(getFromArr(xxxServiceRate,0,\'rate99\',\'number\'),\'bps\',1000)}\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertNumber(getFromArr(xxxServiceRate,0,\'rate_max\',\'number\'),\'bps\',1000)}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                <div class=\"td__quantile-group\">\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label quantile__label--ratio\">\r\n                            <div class=\"label-box\">\r\n                                <div>本期vs上期</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value quantile__value--ratio\">\r\n                            ${chainRatio(getFromArr(xxxServiceRate,0,\'rate_avg\',\'number\'),getFromArr(pre1stxxxServiceRate,0,\'rate_avg\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label quantile__label--ratio\">\r\n                            <div class=\"label-box\">\r\n                                <div>上期vs上上期</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value quantile__value--ratio\">\r\n                            ${chainRatio(getFromArr(pre1stxxxServiceRate,0,\'rate_avg\',\'number\'),getFromArr(pre2ndxxxServiceRate,0,\'rate_avg\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertNumber(getFromArr(xxxServiceTrafficTotal,0,\'bytes\',\'number\'),\'byte\',1024)}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${proportion(getFromArr(xxxServiceTrafficTotal,0,\'bytes\',\'number\'),getFromArr(trafficTotal,0,\'bytes\',\'number\'))}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                <div class=\"td__quantile-group\">\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label quantile__label--ratio\">\r\n                            <div class=\"label-box\">\r\n                                <div>本期vs上期</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value quantile__value--ratio\">\r\n                            ${chainRatio(getFromArr(xxxServiceTrafficTotal,0,\'bytes\',\'number\'),getFromArr(pre1stxxxServiceTrafficTotal,0,\'bytes\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label quantile__label--ratio\">\r\n                            <div class=\"label-box\">\r\n                                <div>上期vs上上期</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value quantile__value--ratio\">\r\n                            ${chainRatio(getFromArr(pre1stxxxServiceTrafficTotal,0,\'bytes\',\'number\'),getFromArr(pre2ndxxxServiceTrafficTotal,0,\'bytes\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n        </tr>\r\n        </tbody></table>\r\n    <div class=\"table__footer\">\r\n        <div class=\"footer__label\">* 流量速率分位值计算方式：</div>以5分钟为时间粒度计算平均流量速率vi，取观测时间范围内的{v1, v2, v3……vn}的分位值，下同。\r\n    </div>\r\n</div>\r\n<div class=\"echarts-box indent-3\">\r\n    <div class=\"echarts\">\r\n        <div class=\"echarts__canvas echarts__line\" id=\"canvas1\"></div>\r\n        <div class=\"echarts__title\">图1 当日流量变化曲线</div>\r\n    </div>\r\n</div>\r\n\r\n<div class=\"header3\">2.服务质量概况</div>\r\n<div class=\"table-box indent-3\">\r\n    <div class=\"table__title\">表2 整体服务质量</div>\r\n    <table class=\"table\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th class=\"table__th\">服务质量指标</th>\r\n            <th class=\"table__th\">分位值</th>\r\n            <th class=\"table__th\">峰值</th>\r\n            <th class=\"table__th\">均值</th>\r\n            <th class=\"table__th\">均值环比</th>\r\n        </tr>\r\n        </thead>\r\n        <tbody><tr class=\"table__tr\">\r\n            <td class=\"table__td\">TCP会话创建延迟</td>\r\n            <td class=\"table__td\">\r\n                <div class=\"td__quantile-group\">\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p50\"></span>P50</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertTime(getFromArr(xxxServiceOut2inTcp,0,\'establish_latency_p50\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p90\"></span>P90</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertTime(getFromArr(xxxServiceOut2inTcp,0,\'establish_latency_p90\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p99\"></span>P99</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertTime(getFromArr(xxxServiceOut2inTcp,0,\'establish_latency_p99\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertTime(getFromArr(xxxServiceOut2inTcp,0,\'establish_latency_max\',\'number\'))}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertTime(getFromArr(xxxServiceOut2inTcp,0,\'establish_latency_avg\',\'number\'))}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${chainRatio(getFromArr(xxxServiceOut2inTcp,0,\'establish_latency_avg\',\'number\'),getFromArr(pre1stxxxServiceOut2inTcp,0,\'establish_latency_avg\',\'number\'))}\r\n            </td>\r\n        </tr>\r\n        <tr class=\"table__tr\">\r\n            <td class=\"table__td\">缺包率</td>\r\n            <td class=\"table__td\">\r\n                <div class=\"td__quantile-group\">\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p50\"></span>P50</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertPercent(getFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_p50\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p90\"></span>P90</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertPercent(getFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_p90\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"td__quantile\">\r\n                        <div class=\"quantile__label\">\r\n                            <div class=\"label-box\">\r\n                                <div><span class=\"quantile__point quantile__point--p99\"></span>P99</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"quantile__value\">\r\n                            ${convertPercent(getFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_p99\',\'number\'))}\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertPercent(getFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_max\',\'number\'))}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${convertPercent(getFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_avg\',\'number\'))}\r\n            </td>\r\n            <td class=\"table__td\">\r\n                ${chainRatio(getFromArr(xxxServiceOut2inLossPackets,0,\'sequence_gap_loss_avg\',\'number\'),getFromArr(pre1stxxxServiceOut2inLossPackets,0,\'sequence_gap_loss_avg\',\'number\'))}\r\n            </td>\r\n        </tr>\r\n        </tbody></table>\r\n</div>\r\n<div class=\"table__title\">表3 Top10 APP 服务质量</div>\r\n<table class=\"table\">\r\n    <thead class=\"table__header\">\r\n    <tr class=\"table__tr\">\r\n        <th rowspan=\"2\" class=\"table__th\">APP</th>\r\n        <th rowspan=\"2\" class=\"table__th\">流量占比</th>\r\n        <th colspan=\"3\" class=\"table__th\">TCP会话延迟(ms)</th>\r\n        <th colspan=\"3\" class=\"table__th\">缺包率</th>\r\n    </tr>\r\n    <tr class=\"table__tr\">\r\n        <th class=\"table__th\">P50 P90 P99</th>\r\n        <th class=\"table__th\">均值</th>\r\n        <th class=\"table__th\">均值环比</th>\r\n        <th class=\"table__th\">P50 P90 P99</th>\r\n        <th class=\"table__th\">均值</th>\r\n        <th class=\"table__th\">均值环比</th>\r\n    </tr>\r\n    </thead>\r\n    <tbody>\r\n    <#if xxxIPTagsTop10AppBytes??>\r\n        <#list xxxIPTagsTop10AppBytes as val>\r\n            <tr class=\"table__tr\">\r\n                <td class=\"table__td\">${getFromObj(val,\'app_company\',\'string\')}</td>\r\n                <td class=\"table__td\">${proportion(getFromObj(val,\'bytes\',\'number\'),getFromArr(xxxServiceTrafficTotal,0,\'bytes\',\'number\'))}</td>\r\n                <td class=\"table__td\">\r\n                    <div class=\"td__quantile-group\">\r\n                        <div class=\"td__quantile\">\r\n                            <div class=\"quantile__label\">\r\n                                <div class=\"label-box\">\r\n                                    <div><span class=\"quantile__point quantile__point--p50\"></span>P50</div>\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"quantile__value\">\r\n                                ${convertTime(getFromArr(xxxIPTagsTop10AppTCP,findRecordByName(getFromObj(val,\'app_company\',\'string\'), \'app_company\', val, xxxIPTagsTop10AppTCP),\'establish_latency_p50\',\'number\'))}\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"td__quantile\">\r\n                            <div class=\"quantile__label\">\r\n                                <div class=\"label-box\">\r\n                                    <div><span class=\"quantile__point quantile__point--p90\"></span>P90</div>\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"quantile__value\">\r\n                                ${convertTime(getFromArr(xxxIPTagsTop10AppTCP,findRecordByName(getFromObj(val,\'app_company\',\'string\'), \'app_company\', val, xxxIPTagsTop10AppTCP),\'establish_latency_p90\',\'number\'))}\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"td__quantile\">\r\n                            <div class=\"quantile__label\">\r\n                                <div class=\"label-box\">\r\n                                    <div><span class=\"quantile__point quantile__point--p99\"></span>P99</div>\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"quantile__value\">\r\n                                ${convertTime(getFromArr(xxxIPTagsTop10AppTCP,findRecordByName(getFromObj(val,\'app_company\',\'string\'), \'app_company\', val, xxxIPTagsTop10AppTCP),\'establish_latency_p99\',\'number\'))}\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </td>\r\n                <td class=\"table__td\">\r\n                    ${convertTime(getFromArr(xxxIPTagsTop10AppTCP,findRecordByName(getFromObj(val,\'app_company\',\'string\'), \'app_company\', val, xxxIPTagsTop10AppTCP),\'establish_latency_avg\',\'number\'))}\r\n                </td>\r\n                <td class=\"table__td\">\r\n                    ${chainRatio(getFromArr(xxxIPTagsTop10AppTCP,findRecordByName(getFromObj(val,\'app_company\',\'string\'), \'app_company\', val, xxxIPTagsTop10AppTCP),\'establish_latency_avg\',\'number\'),getFromArr(pre1stxxxIPTagsTop10AppTCP,findRecordByName(getFromObj(val,\'app_company\',\'string\'), \'app_company\', val, pre1stxxxIPTagsTop10AppTCP),\'establish_latency_avg\',\'number\'))}\r\n                </td>\r\n                <td class=\"table__td\">\r\n                    <div class=\"td__quantile-group\">\r\n                        <div class=\"td__quantile\">\r\n                            <div class=\"quantile__label\">\r\n                                <div class=\"label-box\">\r\n                                    <div><span class=\"quantile__point quantile__point--p50\"></span>P50</div>\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"quantile__value\">\r\n                                ${convertPercent(getFromArr(xxxIPTagsTop10AppLossPackets,findRecordByName(getFromObj(val,\'app_company\',\'string\'), \'app_company\', val, xxxIPTagsTop10AppLossPackets),\'sequence_gap_loss_p50\',\'number\'))}\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"td__quantile\">\r\n                            <div class=\"quantile__label\">\r\n                                <div class=\"label-box\">\r\n                                    <div><span class=\"quantile__point quantile__point--p90\"></span>P90</div>\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"quantile__value\">\r\n                                ${convertPercent(getFromArr(xxxIPTagsTop10AppLossPackets,findRecordByName(getFromObj(val,\'app_company\',\'string\'), \'app_company\', val, xxxIPTagsTop10AppLossPackets),\'sequence_gap_loss_p90\',\'number\'))}\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"td__quantile\">\r\n                            <div class=\"quantile__label\">\r\n                                <div class=\"label-box\">\r\n                                    <div><span class=\"quantile__point quantile__point--p99\"></span>P99</div>\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"quantile__value\">\r\n                                ${convertPercent(getFromArr(xxxIPTagsTop10AppLossPackets,findRecordByName(getFromObj(val,\'app_company\',\'string\'), \'app_company\', val, xxxIPTagsTop10AppLossPackets),\'sequence_gap_loss_p99\',\'number\'))}\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </td>\r\n                <td class=\"table__td\">\r\n                    ${convertPercent(getFromArr(xxxIPTagsTop10AppLossPackets,findRecordByName(getFromObj(val,\'app_company\',\'string\'), \'app_company\', val, xxxIPTagsTop10AppLossPackets),\'sequence_gap_loss_avg\',\'number\'))}\r\n                </td>\r\n                <td class=\"table__td\">\r\n                    ${chainRatio(getFromArr(xxxIPTagsTop10AppLossPackets,findRecordByName(getFromObj(val,\'app_company\',\'string\'), \'app_company\', val, xxxIPTagsTop10AppLossPackets),\'sequence_gap_loss_avg\',\'number\'),getFromArr(pre1stxxxIPTagsTop10AppLossPackets,findRecordByName(getFromObj(val,\'app_company\',\'string\'), \'app_company\', val, pre1stxxxIPTagsTop10AppLossPackets),\'sequence_gap_loss_avg\',\'number\'))}\r\n                </td>\r\n            </tr>\r\n        </#list>\r\n    </#if>\r\n    </tbody>\r\n</table>\r\n\r\n<div class=\"header2\">二.业务分布</div>\r\n<div class=\"header3\">1.承载业务分布</div>\r\n<div class=\"echarts-box indent-3\">\r\n    <span class=\"echarts pie-style\">\r\n    <div class=\"echarts__canvas echarts__pie\" id=\"canvas13\"></div>\r\n    <div class=\"echarts__title\">图2 APP流量占比</div>\r\n  </span>\r\n    <span class=\"echarts pie-style\">\r\n    <div class=\"echarts__canvas echarts__pie\" id=\"canvas18\"></div>\r\n    <div class=\"echarts__title\">图3 域名流量占比</div>\r\n  </span>\r\n</div>\r\n<div class=\"header3\">2.访问业务分布</div>\r\n<div class=\"echarts-box indent-3\">\r\n    <span class=\"echarts pie-style\">\r\n    <div class=\"echarts__canvas echarts__pie\" id=\"canvas14\"></div>\r\n    <div class=\"echarts__title\">图4 APP流量占比</div>\r\n  </span>\r\n    <span class=\"echarts pie-style\">\r\n    <div class=\"echarts__canvas echarts__pie\" id=\"canvas19\"></div>\r\n    <div class=\"echarts__title\">图5 域名流量占比</div>\r\n  </span>\r\n</div>\r\n\r\n<div class=\"header2\">三.地理位置分布</div>\r\n<div class=\"header3\">1.各省份流量分布</div>\r\n<div class=\"echarts-box indent-3\">\r\n    <div class=\"echarts\">\r\n        <div class=\"echarts__canvas echarts__line-and-bar\" id=\"canvas3\"></div>\r\n    </div>\r\n</div>\r\n<div class=\"table-box indent-3\">\r\n    <table class=\"table\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th class=\"table__th\">各省份流量速率</th>\r\n            <#if provinceOut2inSentTrafficBytesTop10??>\r\n                <#list provinceOut2inSentTrafficBytesTop10 as val>\r\n                    <th class=\"table__th\">${getFromObj(val,\'client_province\',\'string\')}</th>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </thead>\r\n        <tbody><tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">峰值</td>\r\n            <#if provinceOut2inSentTrafficBytesTop10??>\r\n                <#list provinceOut2inSentTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'sent_rate_max\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        <tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">均值</td>\r\n            <#if provinceOut2inSentTrafficBytesTop10??>\r\n                <#list provinceOut2inSentTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'sent_rate_avg\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </tbody></table>\r\n    <div class=\"echarts__title echarts__line-and-bar-title\">图6 各省份访问${ipTag}IP的Top 10 省份请求流量分布</div>\r\n</div>\r\n\r\n<div class=\"echarts-box indent-3\">\r\n    <div class=\"echarts\">\r\n        <div class=\"echarts__canvas echarts__line-and-bar\" id=\"canvas9\"></div>\r\n    </div>\r\n</div>\r\n<div class=\"table-box indent-3\">\r\n    <table class=\"table\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th class=\"table__th\">各省份流量速率</th>\r\n            <#if provinceOut2inReceivedTrafficBytesTop10??>\r\n                <#list provinceOut2inReceivedTrafficBytesTop10 as val>\r\n                    <th class=\"table__th\">${getFromObj(val,\'client_province\',\'string\')}</th>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </thead>\r\n        <tbody>\r\n        <tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">峰值</td>\r\n            <#if provinceOut2inReceivedTrafficBytesTop10??>\r\n                <#list provinceOut2inReceivedTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'received_rate_max\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        <tr class=\"table__tr font-size-14\">\r\n            <td class=\"table__td\">均值</td>\r\n            <#if provinceOut2inReceivedTrafficBytesTop10??>\r\n                <#list provinceOut2inReceivedTrafficBytesTop10 as val>\r\n                    <td class=\"table__td\">${convertNumber(getFromObj(val,\'received_rate_avg\',\'number\'),\'bps\',1000)}</td>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n        </tbody></table>\r\n    <div class=\"echarts__title echarts__line-and-bar-title\">图7 各省份访问${ipTag}IP的Top 10 省份响应流量分布</div>\r\n</div>\r\n\r\n<div class=\"echarts-box indent-3\">\r\n    <div class=\"echarts\">\r\n        <div class=\"echarts__canvas echarts__line-and-bar\" id=\"canvas2\"></div>\r\n    </div>\r\n</div>\r\n<div class=\"table-box indent-3\">\r\n    <table class=\"table\">\r\n        <thead class=\"table__header\">\r\n        <tr class=\"table__tr\">\r\n            <th class=\"table__th\">各省份流量速率</th>\r\n            <#if provinceIn2outSentTrafficBytesTop10??>\r\n                <#list provinceIn2outSentTrafficBytesTop10 as val>\r\n                    <th class=\"table__th\">${getFromObj(val,\'server_province\',\'string\')}</th>\r\n                </#list>\r\n            </#if>\r\n        </tr>\r\n    