erySql\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT5M\',\'zero\') AS stat_time, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes, ROUND(bytes * 8/300) AS rate FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND (has(client_ip_tags,\'${ipTag}\') or has(server_ip_tags,\'${ipTag}\')) GROUP BY stat_time ORDER BY stat_time ASC\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"xxxServiceTrafficChangingCurve\"\r\n    },\r\n    {\r\n      \"querySql\": \"SELECT SUM(bytes) AS all_bytes, IFNULL(ROUND(QUANTILE(establish_latency,0.5), 4), 0) AS establish_latency_p50, IFNULL(ROUND(QUANTILE(establish_latency,0.9), 4), 0) AS establish_latency_p90, IFNULL(ROUND(QUANTILE(establish_latency,0.99), 4), 0) AS establish_latency_p99, IFNULL(ROUND(AVG(establish_latency), 4), 0) AS establish_latency_avg, IFNULL(ROUND(MAX(establish_latency), 4), 0) AS establish_latency_max, IFNULL(ROUND(MIN(establish_latency), 4), 0) AS establish_latency_min FROM ( SELECT SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS bytes, ROUND(AVG(common_establish_latency_ms)) AS establish_latency, toDateTime(toStartOfInterval(toDateTime(common_recv_time),INTERVAL 300 SECOND)) AS granularity FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND common_l4_protocol IN (\'IPv4_TCP\', \'IPv6_TCP\') AND (has(client_ip_tags,\'${ipTag}\') or has(server_ip_tags,\'${ipTag}\')) GROUP BY granularity)\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"xxxServiceOut2inTcp\"\r\n    },\r\n    {\r\n      \"querySql\": \"SELECT SUM(bytes) AS all_bytes, IFNULL(ROUND(QUANTILE(establish_latency,0.5), 4), 0) AS establish_latency_p50, IFNULL(ROUND(QUANTILE(establish_latency,0.9), 4), 0) AS establish_latency_p90, IFNULL(ROUND(QUANTILE(establish_latency,0.99), 4), 0) AS establish_latency_p99, IFNULL(ROUND(AVG(establish_latency), 4), 0) AS establish_latency_avg, IFNULL(ROUND(MAX(establish_latency), 4)