          {\r\n                type: \'bar\',\r\n                barWidth: 10,\r\n                barMinHeight: 2\r\n            }\r\n        ]\r\n    }\r\n\r\n    try { initEcharts1() } catch (e) { console.error(e) }\r\n    try { initEcharts2() } catch (e) { console.error(e) }\r\n    try { initEcharts3() } catch (e) { console.error(e) }\r\n    try { initEcharts4() } catch (e) { console.error(e) }\r\n    try { initEcharts5() } catch (e) { console.error(e) }\r\n    try { initEcharts8() } catch (e) { console.error(e) }\r\n    try { initEcharts9() } catch (e) { console.error(e) }\r\n    try { initEcharts10() } catch (e) { console.error(e) }\r\n    try { initEcharts11() } catch (e) { console.error(e) }\r\n    try { initEcharts13() } catch (e) { console.error(e) }\r\n    try { initEcharts18() } catch (e) { console.error(e) }\r\n    try { initEcharts14() } catch (e) { console.error(e) }\r\n    try { initEcharts19() } catch (e) { console.error(e) }\r\n    try { initTimeRange() } catch (e) { console.error(e) }\r\n</script>\r\n</body>\r\n\r\n</html>\r\n', '{\r\n  \"isRepeat\": 1,\r\n  \"isScheduler\":1,\r\n  \"queryParam\":[{\r\n    \"key\":\"ipTag\",\r\n    \"value\":\"\",\r\n    \"i18n\":\"report.ipTag\",\r\n    \"labelType\": \"input\"\r\n  }],\r\n  \"cronExpression\":\"0 0 17 * * ? *\",\r\n  \"startTime\": \"\",\r\n  \"endTime\": \"\",\r\n  \"timeConfig\": {\r\n    \"type\": \"yesterday\",\r\n    \"offset\": 0,\r\n    \"unit\": \"\"\r\n  },\r\n  \"dataset\": [\r\n    {\r\n      \"querySql\": \"SELECT SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime}\",\r\n      \"type\": \"table\",\r\n      \"valueAlias\": \"trafficTotal\"\r\n    },\r\n    {\r\n      \"querySql\": \"SELECT SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes FROM session_record_cn WHERE common_recv_time >= ${startTime} AND common_recv_time < ${endTime} AND (has(client_ip_tags,\'${ipTag}\') or has(serv